(window.GIM_TS=window.GIM_TS||{})["Pesachim.5"]={"from":120,"a":[["\u0003בהאי קרא קמיפלגי\u0004 \u0005[בפסוק זה נחלקו]\u0006 שנאמר לענין קרבן אחר \u0003\"ונרצה לו לכפר עליו\"\u0004 (ויקרא א, ד), ומדייקים: \u0003\"עליו\" ולא על חבירו\u0004 שאינו יוצא אם מנסה להתכפר בקרבן הנועד לאחר. ובמסקנות היוצאות מהלכה זו לעניננו נחלקו. \u0003רבה סבר: חבירו דומיא דידיה\u0004 \u0005[בדומה לו]\u0006 \u0003מה הוא דבר\u0004 \u0005[שהוא בן]\u0006 \u0003כפרה?\u0004 (שראוי להתכפר)? על ידי זריקת דם של קרבן זה \u0003אף חבירו דבר\u0004 \u0005[שהוא בן]\u0006 \u0003כפרה, לאפוקי האי ערל\u0004 \u0005[להוציא ערל זה]\u0006 \u0003דלאו בר\u0004 \u0005[שאין בן]\u0006 \u0003כפרה הוא,\u0004 שהרי אינו ראוי לקרבן הפסח ולכך אין השחיטה עבורו פוסלת.","\u0003ורב חסדא סבר: האי ערל נמי כיון דבר חיובא הוא בר כפרה הוא\u0004 \u0005[אותו ערל גם כן, כיון שבן חיוב הוא בן כפרה הוא].\u0006 ומדוע אומרים אנו שהערל נכנס בחיוב קרבן הפסח? \u0003הואיל דאי בעי מתקן נפשיה\u0004 \u0005[הואיל שאם ירצה יוכל לתקן את עצמו]\u0006 כלומר להימול, וממילא תחול עליו חובת הקרבת פסח. והואיל ויכול להיות בכלל אוכלי הקרבן אין לומר שאינו בן כפרה כלל, ולכן השחיטה עבורו מעכבת.","ותוהים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו,\u0006 האם יקבל\u0005]\u0006 \u0003רב חסדא\u0004 נימוק זה של \u0003\"הואיל\"?\u0004 האמנם סבור רב חסדא שאפשר לדון בדבר שאינו קיים כעת הואיל וקיימת אפשרות שהמצב ישתנה? \u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו רבה ורב חסדא בנושא זה בדינו של \u0003האופה מיום טוב\u0004 לצורך יום \u0003חול, רב חסדא אמר: לוקה\u0004 על שחילל את החג ואפה בו לצורך החול. \u0003רבה אמר: אינו לוקה.\u0004","ומסבירים, \u0003רבה אמר: אינו לוקה, אמרינן\u0004 \u0005[אומרים אנו]\u0006 כנימוק \u0003הואיל ואי מקלעי ליה אורחים חזי ליה\u0004 \u0005[ואם יזדמנו לו אורחים יהא ראוי לו]\u0006 כל מה שיאפה לצורך יום טוב עצמו ונמצא שלא עבר כל עבירה, \u0003השתא נמי חזי ליה ולא לקי\u0004 \u0005[עכשיו גם כן\u0006 שלא באו האורחים הרי האוכל נחשב \u0005כראוי לו ואינו לוקה]\u0006 שהרי בשעת האפייה לא היה איסור ודאי בכך. \u0003רב חסדא אמר: לוקה, לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003\"הואיל\",\u0004 ולכאורה יש כאן סתירה עצמית כפולה הן בדברי רב חסדא והן בדברי רבה.","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מדברי \u0003רבה\u0004 על דברי \u0003רבה לא קשיא\u0004 \u0005[אינו קשה]\u0006 כי \u0003הכא\u0004 \u0005[כאן]\u0006 לענין הערל בפסח הריהו \u0003מחוסר מעשה\u0004 כיון שצריך עוד להימול שהיא פעולה מעשית, כדי לשנות את המצב, \u0003התם\u0004 \u0005[שם]\u0006 לענין האופה בחג האפשרות שיבואו לו אורחים \u0003לא מחוסר מעשה\u0004 מצד האופה. \u0003אלא\u0004 שיטת \u0003רב חסדא\u0004 על שיטת \u0003רב חסדא קשיא\u0004 \u0005[קשה]!\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתירוץ הסתירה: \u0003כי לית לה\u0004 \u0005[כאשר אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003לרב חסדא\u0004 נימוק זה של \u0003\"הואיל\" — הרי זה רק לקולא\u0004 \u0005[להקל]\u0006 ולפוטרו ממלקות, אבל כשהוא \u0003לחומרא\u0004 \u0005[להחמיר]\u0006 לפסול את הפסח, \u0003אית ליה\u0004 \u0005[יש לו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב מרי לרבינא: קתני\u0004 \u0005[שנינו]\u0006 בברייתא שכבר ציטטנו ממנה: \u0003הואיל וערלה פוסלת\u0004 בקרבן פסח \u0003וטומאה פוסלת, מה טומאה לא עשה בה מקצת טומאה ככל טומאה אף ערלה לא עשה מקצת ערלה ככל ערלה.\u0004 ונברר: \u0003האי טומאה היכי דמי\u0004 \u0005[טומאה זו\u0006 שהוזכרה \u0005כיצד\u0006 בדיוק \u0005היתה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בטומאת גברי\u0004 \u0005[האנשים\u0006 המנויים על הקרבן\u0005],\u0006 \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003לא עשה בה מקצת טומאה ככל טומאה — דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003ארבעה וחמשה גברי\u0004 \u0005[אנשים]\u0006 \u0003טמאין וארבעה וחמשה גברי\u0004 \u0005[אנשים]\u0006 \u0003טהורים לא פסלי להו\u0004 \u0005[אין פוסלים אותם]\u0006 ה\u0003טמאין לטהורין,\u0004","\u0003גבי ערלה נמי הא לא פסלי\u0004 \u0005[גם כן הרי אינם פוסלים],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 אם שחטו לשם \u0003מולין וערלים\u0004 יחד — \u0003כשר. מאי שנא טומאה דפשיטא ליה\u0004 \u0005[במה שונה\u0006 ההלכה \u0005בטומאה שפשוט לו]\u0006 שמקצת טמאים אינם פוסלים את הטהורים שבחבורתם, \u0003ומאי שנא ערלה דמספקא ליה\u0004 \u0005[ובמה שונה ערלה\u0006 ענין ערלים, \u0005שמסופק לו]?\u0006","\u0003אלא\u0004 ודאי יש להסביר שמדובר \u0003בטומאת בשר\u0004 הקרבן, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003לא עשה בה מקצת טומאה ככל טומאה? דאילו איטמי חד מאברים — האי דאיטמי שרפינן ליה ואידך אכלינן ליה\u0004 \u0005[שאילו היה נטמא אחד מן האיברים, זה שנטמא שורפים אנו אותו והשאר\u0006 היינו \u0005אוכלים אותו].\u0006","ומקשים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת\u0006 הסברת\u0005]\u0006 את הדברים \u0003בטומאת בשר,\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של אותה ברייתא: \u0003דנין דבר\u0004 (דין ערלה) \u0003שאינו נוהג בכל הזבחים מדבר\u0004 (דין טומאה) \u0003שאינו נוהג בכל הזבחים, ואל יוכיח זמן שנוהג בכל הזבחים. ומאי טומאה\u0004 \u0005[ומה,\u0006 באיזה, \u0005טומאה]\u0006 מדובר כאן? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003טומאת בשר, אמאי\u0004 \u0005[מדוע]\u0006 אומר אתה ש\u0003אינו נוהג בכל הזבחים?\u0004 ודאי נוהג דין זה בכל הזבחים כולם!","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003בטומאת גברי\u0004 \u0005[האנשים]\u0006 האוכלים מן הזבח, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003אינו נוהג בכל הזבחים\u0004 — כך יש לומר: ש\u0003אילו בכל הזבחים ערל וטמא\u0004 אף שהם עצמם אינם רשאים לאכול מן הקרבן, מכל מקום \u0003משלחין קרבנותיהן\u0004 ביד אחרים ומקריבים את הקרבן עבורם. \u0003ואילו בפסח ערל וטמא אין משלחין פסחיהן,\u0004 ועלינו להגיע למסקנה התמוהה כי \u0003רישא\u0004 \u0005[ההתחלה]\u0006 של הברייתא מדברת \u0003בטומאת בשר וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בטומאת גברי\u0004 \u0005[האנשים]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא: \u0003אין\u0004 \u0005[כן]\u0006 אפשר לקבל דבר הסבר זה משום ש\u0003שם טומאה קא פריך\u0004 \u0005[ממושג הטומאה\u0006 בכלל \u0005הקשה],\u0006 שמבחינת הבנת הענין יש לומר שלא הקשה מטומאת בשר על טומאת בשר אלא ממושג הטומאה הקיים בדבר אחד ואינו קיים באחר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003סיפא נמי\u0004 \u0005[סוף\u0006 הברייתא \u0005גם כן]\u0006 \u0003בטומאת בשר\u0004 מדובר. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003אינו נוהג בכל הזבחים\u0004 — כך יש להבין: ש\u0003אילו בכל הזבחים בין שנטמא חלב\u0004 הקרבן המוקרב למזבח \u0003ובשר\u0004 הקרבן \u0003קיים, בין שנטמא בשר וחלב קיים\u0004 — \u0003זורק\u0004 לכתחילה \u0003את הדם\u0004 ועולה הקרבן לרצון בין בהקטרת אימורים בין באכילת כהנים.","\u0003ואילו בפסח,\u0004 אם \u0003נטמא חלב ובשר קיים\u0004 שהוא טהור וכשר לאכילה — \u0003זורק את הדם,\u0004 אולם אם \u0003נטמא\u0004 ה\u0003בשר וחלב קיים\u0004 שהוא טהור וראוי להקטרה — \u0003אינו זורק את הדם\u0004 כי בקרבן פסח חובת אכילתו לבעלים היא עיקרו של הקרבן.","ומקשים עוד: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת,\u0006 הסברת\u0005]\u0006 את הברייתא — \u0003בטומאת בשר.\u0004 אם כן \u0003אימא סיפא\u0004 \u0005[אמור את סופה]\u0006 של הברייתא, בהמשך הדברים הלאה נאמר ש\u0003דנין דבר\u0004 (דין ערלה) \u0003שלא הותר מכללו מדבר\u0004 (דין זמן) \u0003שלא הותר מכללו, ואל תוכיח טומאה שהרי הותרה מכללה.\u0004 ונברר \u0003במאי\u0004 \u0005[במה]\u0006 באיזה ענין מדובר כאן? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006"],["\u0003בטומאת בשר היכא\u0004 \u0005[היכן]\u0006 \u0003הותרה\u0004 טומאת בשר באכילה? \u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003בטומאת גברי\u0004 \u0005[אנשים],\u0006 \u0003והיכא הותרה מכללה — בציבור,\u0004 שכאשר רוב הציבור נטמא מותר להקריב את קרבן הפסח ולאוכלו בטומאה.","ושוב אם כן יש לתמוה: \u0003רישא\u0004 \u0005[ראשיתה\u0006 של הברייתא\u0005]\u0006 \u0003בטומאת בשר, סיפא\u0004 \u0005[סופה]\u0006 \u0003בטומאת גברי\u0004 \u0005[אנשים]!\u0006 ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 אין זה דבר מופרך — כי \u0003שם טומאה קפריך\u0004 \u0005[\u0006ממושג \u0005הטומאה\u0006 בכלל \u0005מקשה]\u0006 ואינו מדקדק שיהא הדבר באותו סוג טומאה עצמה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: כל הברייתא \u0003כולה בטומאת בשר, והיכא\u0004 \u0005[והיכן]\u0006 \u0003הותרה — בטומאת פסח, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003פסח הבא בטומאה\u0004 כגון שרוב הצבור נטמא והותר להקריבו בטומאה אף \u0003נאכל בטומאה שלא בא מתחילתו אלא לאכילה,\u0004 שלא כשאר קרבנות הבאים בטומאה שרק מזים מדמם ואין אוכלים אותם. הרי שאף טומאת בשר הותרה מכללה במקרים מסויימים.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע\u0004 ממקום אחר, שנינו: \u0003הפסח שעברה שנתו\u0004 שקרבן הפסח מביאים מן הטלאים והגדיים עד גיל שנה, וקרבן זה שעברה שנתו \u0003ושחטו בזמנו\u0004 בערב הפסח \u0003לשמו. וכן השוחט אחרים\u0004 כגון גדי שהקדישו לשלמים \u0003לשם פסח בזמנו, ר' אליעזר פוסל\u0004 קרבן פסח זה, \u0003ור' יהושע מכשיר,\u0004 על פי הכלל שכל הקרבנות שנזבחו שלא לשמם כשרים חוץ מקרבן פסח, ולדעת ר' יהושע בשני המקרים לא היה זה קרבן פסח ממש, אלא שלמים שהוקרבו לשם פסח.","ונדקדק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 אם היה הדבר \u0003בזמנו\u0004 אז נחלקו בו תנאים, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003שלא בזמנו — כשר\u0004 לשלמים לדעת הכל, שהיו אלה כקרבנות שלמים אחרים. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 אומרים כך? \u0003נימא\u0004 \u0005[נאמר]\u0006 \u0003הואיל ובזמנו פוסל — שלא בזמנו נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל,\u0004 הרי שמשתמשים בנימוק של \"הואיל\" אפילו כדי להחמיר, וקשה על רב חסדא!","\u0003אמר רב פפא: שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בענין זה \u0003\"ואמרתם זבח פסח הוא\u0004 לה' אשר פסח על בתי בני ישראל במצרים בנגפו את מצרים ואת בתינו הציל ויקוד העם וישתחוו\u0003\"\u0004 (שמות יב, כז), ומלשון הכתוב נלמד \u0003\"הוא\"\u0004 משמע \u0003בהויתו\u0004 כמידתו, ללא שינוי, לא כש\u0003הוא\u0004 קרבן הפסח מוקרב \u0003לשום\u0004 (לשם) קרבנות \u0003אחרים ולא\u0004 קרבנות \u0003אחרים\u0004 כשרים כשמוקרבים \u0003לשמו.\u0004","ומכאן נדקדק: \u0003בזמנו\u0004 של הפסח \u0003שהוא פסול\u0004 כשמקריבו \u0003לשום\u0004 (לשם) קרבנות \u0003אחרים,\u0004 הרי גם \u0003אחרים פסולין לשמו\u0004 (לשיטת ר' אליעזר) אם חשב עליהם לקרבן פסח. אבל \u0003שלא בזמנו שהוא כשר\u0004 אם מקריבו \u0003לשום\u0004 (לשם) קרבנות \u0003אחרים\u0004 שקרבן פסח שהקריבו לשם שלמים שלא בזמן הפסח כשר, גם \u0003אחרים כשרים לשמו\u0004 ואין כאן מקום ל\"הואיל\".","במשנה יש בעיה עקרונית אחת, שנתבררה אגב מעשה שהיה, \u0003ר' שמלאי אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יוחנן, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ניתני לי מר\u0004 \u0005[ישנה לי אדוני]\u0006 \u0003ספר יוחסין\u0004 שהוא קובץ ברייתות, כעין מדרש לספר דברי הימים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מהיכן את\u0004 \u0005[אתה]\u0006 מה מוצא משפחתך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מלוד. והיכן\u0004 מקום \u0003מותבך\u0004 \u0005[מושבך]?\u0006 אמר לו: \u0003בנהרדעא. אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: מקובל בידי ש\u0003אין נידונין\u0004 (שונים) דברים מעין אלה \u0003לא ללודים ולא לנהרדעים, וכל שכן דאת\u0004 \u0005[שאתה]\u0006 \u0003מלוד ומותבך\u0004 \u0005[ומושבך]\u0006 \u0003בנהרדעא\u0004 ומצויים בך שני החסרונות כאחד. \u0003כפייה\u0004 \u0005[כפה אותו]\u0006 בהפצרה \u0003וארצי\u0004 \u0005[ונתרצה]\u0006 ר' יוחנן ללמדו,","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמלאי: הבה \u0003ניתנייה\u0004 \u0005[נשנה אותו]\u0006 את ספר יוחסין \u0003בשלשה ירחי\u0004 \u0005[חדשים],\u0006 \u0003שקל קלא פתק ביה\u0004 \u0005[לקח רגב\u0006 אדמה \u0005וזרק בו],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003ומה ברוריה דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003ר' מאיר ברתיה\u0004 \u0005[בתו]\u0006 של \u0003ר' חנניה בן תרדיון, דתניא תלת מאה שמעתתא ביומא משלש מאה רבוותא\u0004 \u0005[ששנתה שלוש מאות שמועות\u0006 הלכות \u0005ביום\u0006 אחד \u0005משלוש מאות חכמים]\u0006 שכל כך היתה חריפה ובעלת זכרון, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא יצתה ידי חובתה\u0004 בלימוד ספר יוחסין \u0003בתלת שנין\u0004 \u0005[בשלוש שנים]\u0006 לפי שהוא קשה ביותר וארוך, \u0003ואת אמרת בתלתא ירחי\u0004 \u0005[ואתה אומר בשלושה חדשים]\u0006 אלמדנו?! ולפיכך איני רוצה כלל ללמדך.","\u0003כי שקיל ואזיל\u0004 \u0005[כאשר נטל ויצא]\u0006 מר' יוחנן \u0003אמר ליה\u0004 \u0005[לו]:\u0006 בכל זאת \u0003רבי,\u0004 כיון שבאתי אשאל \u0003מה\u0004 טעם ההבדל במחשבה כשמקריבים קרבן הפסח \u0003לשמו ושלא לשמו,\u0004 שהמחשב בשתיהן יחד פוסל את הקרבן, ובין שמחשב בהקרבתו \u0003לאוכליו ושלא לאוכליו\u0004 שאינו פוסל?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הואיל וצורבא מרבנן את\u0004 \u0005[ותלמיד חכם אתה]\u0006 שכך אני מבין מתוך שאלתך, \u0003תא ואימא לך\u0004 \u0005[בוא ואומר לך]\u0006 תשובה: \u0003לשמו ושלא לשמו — פסולו בגופו\u0004 שהרי המחשבה היא על הקרבן עצמו, ואילו \u0003לאוכליו ושלא לאוכליו אין פסולו בגופו\u0004 אלא באנשים המנויים עליו.","ועוד: \u0003לשמו ושלא לשמו אי אפשר לברר איסורו\u0004 שאין לדעת מהו חלק האיסור ומהו חלק ההיתר בקרבן, אולם \u0003לאוכליו ושלא לאוכליו — אפשר לברר איסורו,\u0004 שאם מקצת האנשים ראויים ומקצתם אינם ראויים יש אפשרות עקרונית לברר ואף לחלק את הקרבן בין אלה לאלה.","ועוד: \u0003לשמו ושלא לשמו ישנו\u0004 שהיא מחשבה שיכולה לפסול בתוך \u0003ארבע עבודות\u0004 (שחיטה, קבלה, הולכה, זריקה), אבל מחשבת \u0003לאוכליו ושלא לאוכליו אינו בארבע עבודות\u0004 שאין מחשבת אוכלים בזריקה. ועוד: \u0003לשמו ושלא לשמו\u0004 הוא פסול שכן \u0003ישנו\u0004 בקרבן \u0003ציבור\u0004 כבקרבן \u0003יחיד,\u0004 ואילו \u0003לאוכליו ושלא לאוכליו — אינו בציבור כביחיד.\u0004","\u0003רב אשי אמר\u0004 על תשובות אלה כי אם מדקדקים בדבר אפשר להוכיח כי הנימוקים של \u0003פסולו בגופו ואי אפשר לברר איסורו — חדא מילתא היא\u0004 \u0005[דבר אחד הוא]\u0006 כלומר, טעם אחד ולא שני טעמים נפרדים, כי \u0003מה טעם אמר\u0004 שלא לשמו \u0003פסולו בגופו משום\u0004 ש\u0003אי אפשר לברר איסורו,\u0004 ולכן אומרים שהאיסור חל על גוף הקרבן עצמו.","כיון שהוזכר ספר יוחסין מזכירים מה ש\u0003אמר\u0004 בענין זה \u0003רמי בר רב יודא אמר רב: מיום שנגנז ספר יוחסין\u0004 ואינו מצוי עוד בידי חכמים \u0003תשש כחם של חכמים וכהה מאור עיניהם,\u0004 שהרבה טעמי תורה והרבה רשימות של ייחוס שהיו מצויים בו אבדו על ידי כך.","\u0003אמר מר זוטרא:\u0004 ספר יוחסין היה כה גדול בכמות עד שבהפלגה אמרו כי \u0003בין\u0004 המלה \u0003\"אצל\"\u0004 המוזכרת בכתוב \"ולאצל ששה בנים ואלה שמותם עזריקם בוכרו וישמעאל ושעריה ועובדיה וחנן כל אלה בני אצל\" (דברי הימים א' ח, לח), ובין המלה \u0003\"אצל\"\u0004 המוזכר בפסוק האחר \"ולאצל ששה בנים ואלה שמותם עזריקם בוכרו וישמעאל ושעריה ועובדיה וחנן אלה בני אצל\" (דברי הימים א' פרק ט, מד), \u0003טעינו ארבע מאה גמלי דדרשא\u0004 \u0005[טענו ארבע מאות גמלים של דרשות]\u0006 הכתובות על מקראות אלה, עד כדי כך מרובות היו הדרשות על ספר דברי הימים.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003אחרים אומרים:\u0004 כאשר חשב בפסול אוכלים \u0003הקדים\u0004 במחשבתו את העובדה כי מקריב הוא \u0003מולים לערלים\u0004 — הרי זה קרבן \u0003כשר,\u0004 אבל אם הקדים \u0003ערלים למולים — פסול.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 כאשר הקדים \u0003מולין לערלים\u0004 — ש\u0003כשר\u0004 ש\u0003כולה ערלה בעינן\u0004 \u0005[\u0006שכדי לפסול \u0005שכולו יהיה בערלים צריכים]\u0006 \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005]\u0006 שהרי מקצתם מולים. אולם אם כן כשהקדים \u0003ערלים למולים נמי\u0004 \u0005[גם כן]\u0006 \u0003כולה ערלה בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 ואם כן מה טעם ההבדל?"],["ושואלים: \u0003לימא קסברי\u0004 \u0005[האם נאמר שסבורים]\u0006 \u0003אחרים אינה לשחיטה אלא בסוף,\u0004 שהשחיטה איננה נחשבת בכל משך זמנה אלא רק ברגע האחרון של השחיטה, וכשיטת \u0003רבא\u0004 לענין אחר ש\u0003אמר רבא: עדיין היא מחלוקת\u0004 כלומר, המחלוקת בענין אם תופסים לשון ראשון או לשון אחרון קיימת גם במקרה שרצונו הברור לקבוע זמן מסויים שבו יחול דבר שרצונו לקבוע, כגון שאומר עד חצות היום תהא עולה ומאז והלאה שלמים (ר\"ח).","ודעת ר' מאיר, שהוא־הוא המכונה \"אחרים\" שתופסים רק לשון ראשון, \u0003הילכך\u0004 \u0005[על כן]\u0006 בהתאם להנחות מוקדמות אלה אם \u0003הקדים מולין לערלים — הרי מולין חיילי\u0004 \u0005[חלים]\u0006 כלומר, דבריו שאמר לגבי מולים חלים ותופסים \u0003ערלים לא חיילי\u0004 \u0005[אין חלים],\u0006 שהרי אם השחיטה נמשכת רק רגע אחד שהוא הרגע הקובע בה, אם אמר ברגע זה מולים — חלו דבריו. ולהיפך, אם \u0003הקדים ערלים למולין — ערלים חיילי\u0004 \u0005[חלים\u0006 עליהם הדברים\u0005]\u0006 \u0003מולין לא חיילי\u0004 \u0005[אין חלים].\u0006","\u0003אמר רבה: לא,\u0004 אין לומר כך, \u0003לעולם\u0004 תאמר ש\u0003קסברי\u0004 \u0005[סברו]\u0006 \u0003אחרים ישנה לשחיטה מתחלה ועד סוף, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 \u0003כגון שגמר בלבו לתרווייהו\u0004 \u0005[לשניהם]\u0006 כלומר, שהתכוון \u0003בין למולין בין לערלים, והוציא בפיו \"לערלים\" ולא הספיק לומר \"למולין\" עד שנגמרה שחיטה\u0004 בשעת אמירת \u0003\"ערלים\". ובהא פליגי\u0004 \u0005[וב\u0006עקרון \u0005זה חלוקים]\u0006 ש\u0003ר' מאיר\u0004 הוא אחרים \u0003סבר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהא \u0003פיו ולבו שוים\u0004 והכל הולך לפי הדיבור שהוציא מפיו, וכיון שאמר \"ערלים\" — הרי פסל. \u0003ורבנן סברי\u0004 \u0005[וחכמים סוברים]\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003פיו ולבו שוים,\u0004 וכיון שרצה לומר גם \"למולים\" וגם \"לערלים\" — לא פסל.","ותוהים: \u0003קסבר\u0004 \u0005[והאם סבר]\u0006 \u0003ר' מאיר לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיו \u0003פיו ולבו שוין? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 מן המשנה במסכת תרומות: \u0003המתכוין לומר\u0004 שפירות אלו שהוא מפריש יהיו \u0003\"תרומה\"\u0004 וטעה \u0003ואמר \"מעשר\",\u0004 או התכוון לומר \u0003\"מעשר\" ואמר \"תרומה\",\u0004 או שהתכוון לנדור \u0003\"איני נכנס לבית זה\" ואמר\u0004 בטעות \u0003לזה\u0004 — לבית אחר, או שהתכוון לנדור \u0003\"שאיני נהנה\u0004 לאדם \u0003זה\" ואמר \"לזה\" — לאדם אחר — לא אמר כלום עד שיהו פיו ולבו שוין\u0004 וזו היא סתם משנה, וסתם משנה — ר' מאיר היא!","\u0003אלא אמר אביי\u0004 לא כך יש להסביר, אלא \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר שחילק בתוך מעשה השחיטה עצמו, ששחיטה כשרה נעשית כאשר חותכים בצואר הבהמה את הקנה ואת הושט הקרויים \"סימנים\", ושחיטת שני הסימנים היא המכשירה את הבהמה, וכגון ש\u0003אמר סימן ראשון\u0004 אני שוחט \u0003למולין וסימן שני\u0004 אני שוחט \u0003אף לערלים,\u0004 ש\u0003בסימן שני נמי\u0004 \u0005[גם כן]\u0006 \u0003פתיכי ביה\u0004 \u0005[מעורבים בו]\u0006 \u0003מולין\u0004 ונמצא שהיו בתוך כוונתו תמיד המולים. \u0003סיפא\u0004 \u0005[בסוף]\u0006 מדובר ש\u0003אמר סימן ראשון לערלים סימן שני למולים,\u0004 ש\u0003בסימן ראשון הא לא פתיכי ביה\u0004 \u0005[הרי אין מעורבים בו]\u0006 \u0003מולין,\u0004 שבשחיטת סימן אחד היתה כוונתו רק לפסולים.","\u0003ור' מאיר לטעמיה\u0004 \u0005[לשיטתו]\u0006 ש\u0003אמר: מפגלין בחצי מתיר\u0004 כלומר, פיגול יכול לחול לא רק כשחשב מחשבת פיגול בכל המתיר (כגון בשני סימני השחיטה), אלא גם אם עשה מחצית המתיר את הקרבן (כגון סימן אחד) במחשבת פיגול — הרי הוא פיגול. \u0003ורבנן לטעמייהו\u0004 \u0005[וחכמים לשיטתם]\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003אין מפגלין בחצי מתיר\u0004 לעצמו, וכיון שבמשך זמן השחיטה אמר גם למולים וגם לערלים — לא נפסל הקרבן בכך.","\u0003השוחט את הפסח על החמץ\u0004 שעדיין יש חמץ ברשותו — \u0003עובר בלא תעשה,\u0004 כאמור בתורה \"לא תשחט על חמץ דם זבחי ולא ילין לבוקר זבח חג הפסח\" (שמות לד, כה). \u0003ר' יהודה אומר: אף\u0004 השוחט את \u0003התמיד\u0004 של בין הערביים בערב הפסח על החמץ — עובר. \u0003ר' שמעון אומר:\u0004 השוחט את \u0003הפסח בארבעה עשר\u0004 בניסן \u0003לשמו\u0004 והיה ברשותו חמץ — \u0003חייב,\u0004 שחטו \u0003שלא לשמו — פטור. ושאר כל הזבחים,\u0004 ששחט בערב הפסח בזמן איסור חמץ, \u0003בין\u0004 ששחטן \u0003לשמן ובין\u0004 ששחטן \u0003שלא לשמן — פטור.\u0004","\u0003ובמועד\u0004 כלומר, בתוך הפסח עצמו, אם שחט הפסח, \u0003לשמו — פטור\u0004 שכיון שפסח שנשחט לשמו שלא בזמנו פסול, אין זה קרבן ואין בו משום \"לא תשחט על חמץ\". ואם שחטו \u0003שלא לשמו\u0004 ועל ידי כך הוכשר הקרבן לשלמים — \u0003חייב\u0004 על החמץ. \u0003ושאר כל הזבחים\u0004 ששוחט בפסח כיון שאסור לשחוט על החמץ \u0003בין\u0004 ששחטן \u0003לשמן\u0004 בין ששחטן \u0003שלא לשמן — חייב. חוץ מן החטאת ששחטו שלא לשמה\u0004 ויש ברשותו חמץ, שקרבן החטאת נפסל כשנשחט שלא לשמו בפסח, שלא כשאר כל הזבחים, ועל קרבן פסול אינו עובר משום \"לא תשחט על חמץ דם זבחי\".","\u0003אמר ר' שמעון בן לקיש: לעולם אינו חייב\u0004 משום \"לא תשחט על חמץ\" \u0003עד שיהא החמץ לשוחט\u0004 הפסח עצמו \u0003או לזורק\u0004 את דמו."],["\u0003או\u0004 שיהא חמץ \u0003לאחד מבני חבורה\u0004 ואינו חייב \u0003עד שיהא\u0004 החמץ \u0003עמו בעזרה\u0004 עצמה. \u0003ר' יוחנן אמר:\u0004 חייב \u0003אף על פי שאין\u0004 החמץ \u0003עמו בעזרה.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שבדבר הביטוי \u0003\"על\"\u0004 אם משמעו \u0003בסמוך קמיפלגי\u0004 \u0005[נחלקו],\u0006 ש\u0003ר' שמעון בן לקיש סבר: \"על\"\u0004 משמעו תמיד \u0003בסמוך,\u0004 ולכן \"לא תשחט על חמץ\" משמעו שלא יהא החמץ סמוך לשוחט, בעזרה עצמה. \u0003ור' יוחנן סבר: לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהא \u0003\"על\" בסמוך.\u0004 אולם קשה, \u0003הא איפלגו בהא חדא זימנא\u0004 \u0005[הרי נחלקו ב\u0006שאלה \u0005זו פעם אחת]!\u0006","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השוחט תודה לפנים\u0004 בתוך העזרה \u0003ולחמה\u0004 של התודה (אותן ארבעים חלות המובאות עם זבח התודה) היה מצוי \u0003חוץ לחומה — לא קדש הלחם.\u0004 שנאמר: \"והקריב על זבח התודה חלות מצות\" וגו'.","ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חוץ לחומה? ר' יוחנן אמר: חוץ לחומת בית פאגי\u0004 חוץ לחומת ירושלים החיצונית, \u0003אבל\u0004 אם היה רק \u0003חוץ לחומת העזרה — קדיש\u0004 \u0005[נתקדש]\u0006 הלחם \u0003ולא בעינן\u0004 \u0005[ואין אנו צריכים]\u0006 ש\u0003\"על\"\u0004 יהא דוקא \u0003בסמוך.\u0004 ואילו \u0003ר' שמעון בן לקיש אמר: אפילו\u0004 היה הלחם רק \u0003חוץ לחומת העזרה לא קדיש\u0004 \u0005[נתקדש].\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 שיטתו כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003\"על\" בסמוך.\u0004 וכיון שנחלקו כבר בבעיה זו מן הסתם לא חזרו וחלקו במקרים אחרים הנובעים מאותה שאלה עצמה.","\u0003אלא\u0004 תאמר כי \u0003בהתראת ספק קמיפלגי\u0004 \u0005[נחלקו],\u0006 כי כלל גדול הוא שאין בית הדין עונשים עונשי גוף אלא אם כן מתרים בעבריין לפני עשותו את העבירה. בין השאר דנים גם בשאלה האם עונשים גם כאשר היתה ההתראה רק התראת ספק שמא יעבור שמא לא יעבור, ואפשר להסביר על פי בעיה זו את המחלוקת בענין חמץ, שכיון שהיה החמץ מצוי בשעת האזהרה במקום אחר ואין למתרה ידיעה ברורה בכך, שמא התראה כזו על דבר שאינו נראה למתרה קרויה התראת ספק, ולשיטת ר' יוחנן אף שהיא התראת ספק — הריהי התראה. אולם \u0003בהא נמי הא פליגי בה חדא זימנא\u0004 \u0005[ב\u0006שאלה \u0005זו גם כן הרי נחלקו בה\u0006 כבר \u0005פעם אחת]\u0006","\u0003דאיתמר\u0004 \u0005[שנאמר]:\u0006 אמר אדם \u0003\"שבועה שאוכל ככר זו היום\" ועבר היום ולא אכלה, ר' יוחנן ור' שמעון בן לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 \u0003אינו לוקה,\u0004 אף שלא קיים שבועתו ועבר על מצות לא תעשה של \"לא תשא\" וכו'. אולם נחלקו בטעם הדין; \u0003ר' יוחנן אמר: אינו לוקה, משום דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה\u0004 שהרי העבירה שעשה בכך שנמנע מלאכול אינה מעשה, וכלל הוא ש\u0003כל לאו שאין בו מעשה — אין לוקין עליו, אבל התראת ספק — שמה התראה.\u0004","\u0003ור' שמעון בן לקיש אמר: אינו לוקה משום דהוה ליה\u0004 \u0005[שהרי זו]\u0006 \u0003התראת ספק, והתראת ספק לא שמה התראה\u0004 שהרי אם מתרים בו למשל באמצע היום: אם לא תאכל ככר זו ילקוך — אין התראה זו התראת ודאי, שכן יש לו עדיין זמן שבו יכול לאכול, ואין מקום להתראה זו שתחול. \u0003אבל לאו שאין בו מעשה — לוקין עליו.\u0004 ואם כן, אף בנושא זה כבר נחלקו ר' יוחנן וריש לקיש, ומה טעם שיחלקו שוב בדבר?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לכך: \u0003לעולם\u0004 אפשר לפרש כי \u0003ב\"על\" בסמוך קא מיפלגי\u0004 \u0005[נחלקו]\u0006 \u0003וצריכא\u0004 \u0005[ונצרכה]\u0006 להשמיענו מחלוקת נוספת זו בנוסף למחלוקת בלחמי תודה, לפי שאינן דומות בכל. \u0003דאי איפליגו\u0004 \u0005[שאילו נחלקו]\u0006 בדעותיהם \u0003לענין חמץ, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003בההוא הוא דקאמר\u0004 \u0005[ב\u0006מקרה \u0005זה הוא שאמר]\u0006 \u0003ר' יוחנן דלא בעינן\u0004 \u0005[שאין אנו צריכים]\u0006 \u0003\"על\" בסמוך — משום\u0004 ש\u0003איסור הוא, וכל היכא דאיתיה — איתיה\u0004 \u0005[ובכל מקום שישנו —\u0006 \u0005ישנו]\u0006 והרי אסור שיהא חמץ שלו מצוי בשעה זו בכל מקום שהוא.","\u0003אבל לענין מקדש\u0004 \u0005[קידוש]\u0006 \u0003לחם\u0004 שהרי \u0003לא קדיש\u0004 \u0005[אינו מתקדש]\u0006 \u0003אלא בפנים, אימא\u0004 \u0005[אמור]\u0006 שמא \u0003מודה ליה\u0004 \u0005[לו]\u0006 ר' יוחנן \u0003לר' שמעון בן לקיש דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003\"על\" בסמוך,\u0004 ונאמר: \u0003דאי איתיה גואי — קדיש, אי לא — לא קדיש\u0004 \u0005[אם ישנו בפנים —\u0006 \u0005קדש, אם אינו\u0006 בפנים \u0005—\u0006 \u0005לא קדש]\u0006 \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 ב\u0003כלי שרת\u0004 שקרבן, כגון מנחה, המתקדש בתוך כלי שרת אינו מתקדש אלא כשהוא בתוך הכלי ולא מבחוץ. על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר שבשני המקרים נחלקו.","ולצד שני; \u0003אי אשמעינן לענין מקדש לחם\u0004 \u0005[לו היה משמיע לנו\u0006 רק \u0005לענין קידוש הלחם]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003בהך\u0004 \u0005[בזו]\u0006 דווקא \u0003אמר ר' שמעון בן לקיש דבעינן\u0004 \u0005[שצריכים אנו]\u0006 \u0003\"על\" בסמוך, דאי איתיה גואי — קדיש, אי לא — לא קדיש,\u0004 \u0005[אם ישנו בפנים —\u0006 \u0005קדש, ואם אינו בפנים —\u0006 \u0005לא קדש],\u0006 \u0003אבל לענין חמץ מודה ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן דלא בעינן\u0004 \u0005[שאיננו צריכים]\u0006 \u0003\"על\" בסמוך,\u0004 כי \u0003איסורא\u0004 \u0005[איסור]\u0006 \u0003הוא, וכל היכא דאיתיה — איתיה\u0004 \u0005[וכל מקום שישנו\u0006 — \u0005ישנו]\u0006 על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 לומר שנחלקו בשני המקרים.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב אושעיא\u0004 את \u0003ר' אמי\u0004 שאלה זו: \u0003אין לו\u0004 חמץ \u0003לשוחט\u0004 אבל \u0003יש לו לאחד מבני חבורה מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"לא תשחט על חמצך\"?\u0004 כלומר, דווקא של השוחט, \u0003\"לא תשחט על חמץ\" כתיב\u0004 \u0005[נאמר]\u0006 (שמות לד, כה), משמע כל חמץ ולאו דוקא חמצו של השוחט.","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אפילו לאחד בסוף העולם נמי\u0004 \u0005[גם כן]\u0006 שאם אין כל הגבלה בענין זה, אפילו היה החמץ שייך לאחד שאינו קשור כלל לקרבן היה צריך לאסור. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \u0003\"לא תשחט\"\u0004 וכן נאמר בסוף הפסוק \u0003\"ולא ילין\u0004 לבוקר זבח חג הפסח \u0003\",\u0004 ומהשוואה זו יש ללמוד כך: \u0003\"לא תשחט על חמץ\"\u0004 מי מחוייב עליו \u0003הנך דקיימי עליה\u0004 \u0005[אותם שחייבים עליו]\u0006 \u0003משום \"לא ילין\"\u0004 והם בני החבורה, אבל מי שאינו קשור בקרבן זה, כשם שאינו ב\"לא ילין\" כך אינו ב\"לא תשחט\".","\u0003אמר רב פפא: הילכך\u0004 \u0005[על כן]\u0006 לפי טעם זה \u0003כהן המקטיר את החלב\u0004 של קרבן הפסח והיה ברשותו חמץ \u0003עובר בלא תעשה\u0004 של \"לא תשחט\" \u0003הואיל\u0004 והכהן שייך בדבר, כי \u0003ישנו בכלל הלנת אמורים,\u0004 שאף שאינו בין אוכלי קרבן זה, כיון שיש לו חלק באיסור של הלנת חלב הקרבן עד בקר חייב אף משום הקטרה על חמץ.","ומעירים כי אכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטת]\u0006 \u0003רב פפא,\u0004 ששנינו: \u0003השוחט את הפסח על החמץ — עובר בלא תעשה,\u0004 ו\u0003אימתי — בזמן שהוא\u0004 החמץ שייך \u0003לשוחט או לזורק או לאחד מבני חבורה. היה\u0004 החמץ שייך \u0003לאחד בסוף העולם — אין זקוק לו,\u0004 כלומר אין צורך לדון בו. \u0003ואחד השוחט ואחד הזורק ואחד המקטיר\u0004 את החלב — \u0003חייב. אבל המולק את העוף\u0004 שאינו קרבן פסח אלא עולה או חטאת העוף (לזב, זבה, יולדת ומצורע) \u0003בארבעה עשר\u0004 בניסן לאחר זמן איסור חמץ, והיה חמץ ברשותו — \u0003אינו עובר בלא כלום\u0004 על כך.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא אחרת: \u0003השוחט את הפסח על החמץ — עובר בלא תעשה. ר' יהודה אומר: אף\u0004 השוחט את \u0003התמיד\u0004 על חמץ בערב פסח. \u0003אמרו לו: לא אמרו\u0004 איסור זה \u0003אלא בפסח בלבד.\u0004 ו\u0003אימתי\u0004 עובר \u0003בזמן שיש לשוחט או לזורק או לאחד מבני חבורה. היה לאחד בסוף העולם — אין זקוק לו.\u0004","\u0003ואחד השוחט ואחד הזורק ואחד המולק\u0004 את העוף \u0003ואחד המזה\u0004 את דם חטאת העוף על המזבח \u0003חייב, אבל הקומץ את המנחה\u0004 ועדיין יש לו חמץ \u0003אינו עובר בלא תעשה\u0004 שהרי המנחה אינה כלולה בתוך הזבחים שבכתוב נאמר \"לא תשחט על חמץ\". \u0003המקטיר את האימורין\u0004 של הפסח בארבעה עשר בניסן, או של שאר הקרבנות ועדיין חמץ ברשותו — \u0003אינו עובר בלא תעשה,\u0004"],["\u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003מליקה\u0004 על \u0003מליקה, קשיא\u0004 \u0005[קשה]\u0006 \u0003הקטרה\u0004 על \u0003הקטרה,\u0004 שבברייתא אחת שנינו שמליקה אין עוברים עליה ובאחרת שנינו שעוברים, וכן לגבי הקטרת הקרבן, יש סתירה בין הברייתות!","ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולשיטתך]\u0006 שאתה משוה את שתי הברייתות שלדעתך שתיהן עוסקות באותו נושא, \u0003תיקשי לך היא גופא\u0004 \u0005[תקשה לך היא,\u0006 הברייתא \u0005עצמה].\u0006 \u0003דקתני\u0004 \u0005[ששנינו]\u0006 בה: \u0003לא אמרו אלא בפסח בלבד,\u0004 משמע: רק בקרבן זה. \u0003והדר תני\u0004 \u0005[וחזר ושנה]\u0006 \u0003אחד השוחט ואחד הזורק ואחד המולק ואחד המזה\u0004 עוברים. ומליקה והזיה אלו ודאי שאינם בקרבן פסח אלא בקרבן מן העוף!","\u0003אלא\u0004 יש לומר: \u0003הא והא\u0004 \u0005[\u0006ברייתא \u0005זו וזו]\u0006 שיטת \u0003ר' שמעון\u0004 היא. \u0003מליקה\u0004 על \u0003מליקה לא קשיא\u0004 \u0005[אינה קשה]\u0006 כי \u0003כאן\u0004 שנאמר שאין עוברים על המליקה — מדובר \u0003בארבעה עשר\u0004 בניסן, כאן שאמר שעוברים אף על העוף — מדובר \u0003בחולו של מועד\u0004 בפסח. \u0003ואידי ואידי\u0004 \u0005[וזו וזו]\u0006 שיטת \u0003ר' שמעון היא\u0004 הפוטר בשאר קרבנות ביום ארבעה עשר ומחייב עליהם בתוך המועד, כמבואר במשנתינו.","ואילו \u0003הקטרה\u0004 על \u0003הקטרה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה]\u0006 כי \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 על פי שיטת ר' שמעון. \u0003איכא דמקיש הקטרה לשחיטה\u0004 \u0005[יש מי שמקיש\u0006 משוה, דין \u0005הקטרה ל\u0006דין \u0005שחיטה]\u0006 וכרב פפא. \u0003ואיכא מאן דלא מקיש\u0004 \u0005[ויש מי שאינו מקיש,\u0006 משוה\u0005]\u0006 ושלא כדברי רב פפא.","שנינו במשנה ש \u0003ר' יהודה אומר: אף\u0004 על \u0003תמיד\u0004 של בין הערבים חייבים בערב פסח אם שוחטים אותו על החמץ. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהודה?\u0004 ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 נאמר \"לא תשחט על חמץ דם זבחי\" (שמות לד, כה), \u0003\"זבחי\" — זבח המיוחד לי, ומאי ניהו\u0004 \u0005[ומה הוא]?\u0006 זה קרבן \u0003התמיד,\u0004 שהוא קרבן עולה הבא בכל יום כחלק מעבודת המקדש.","ועוד שנינו במשנה ש\u0003ר' שמעון אומר: הפסח\u0004 אם קרב על חמץ ביום \u0003ארבעה עשר\u0004 בניסן, אם זבחו לשמו חייבים רק עליו אבל לא על שאר הזבחים, ובמועד חייבים על כל קרבן שנשחט על חמץ. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון?\u0004 ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"זבחי\" \"זבחי\" תרי זמני\u0004 \u0005[שתי פעמים]\u0006 שנאמר \"לא תזבח על חמץ דם זבחי\" (שמות כג, יח), וגם \"לא תשחט על חמץ דם זבחי\" (שמות לד, כה) \u0003קרי ביה\u0004 \u0005[קרא בו],\u0006 שאם תצרף את שני הכתובים ואת שתי המלים \"זבחי\" יחד יכול אתה לצרף את אותיותיהם בצורה שונה ולכתבן כך: \u0003\"זבח, זבחיי\"\u0004 שדין זה נאמר גם בזבח פסח וגם בשאר זבחים.","ואז \u0003למאי הלכתא פלגינהו רחמנא מהדדי\u0004 \u0005[ל\u0006צורך \u0005איזו הלכה חלקם הכתוב זה מזה]\u0006 \u0003ולא כתב \"זבחיי\"\u0004 במפורש \u0003למימר\u0004 \u0005[\u0006כדי \u0005לומר]\u0006 על ידי כך: \u0003בזמן דאיכא\u0004 \u0005[שיש]\u0006 \u0003זבח\u0004 הוא זבח הפסח האמור בהמשך הכתוב \u0003לא מחייב\u0004 \u0005[אינו חייב]\u0006 על \u0003זבחיי\u0004 האחרים, שבערב הפסח, זמן קרבן הפסח, אין חייבים אם שוחטים שאר קרבנות על החמץ. אולם \u0003בזמן דליכא\u0004 \u0005[שאין]\u0006 \u0003זבח\u0004 הפסח — \u0003מחייב אזבחיי\u0004 \u0005[חייב על הזבחים]\u0006 כולם אם שחטם על החמץ.","שנינו במשנה כי לדעת ר' שמעון אם הקריב את הפסח בחול \u0003המועד\u0004 על החמץ \u0003לשמו פטור\u0004 אף שהקריבו על החמץ, כיון שהוא קרבן פסול. שלא לשמו — חייב, שפסח שנשחט שלא בזמנו הריהו שלמים וכשר. ומדקדקים: \u0003טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 \u0003ששחטו\u0004 ופירש \u0003שלא לשמו, הא סתמא\u0004 \u0005[הרי סתם]\u0006 אם שחטו ולא פירש — \u0003פטור\u0004 לפי שהקרבן פסול, שסתמו עומד עדיין לשם פסח.","ותוהים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 צריך לפרש שלא לשמו הוא קרב? הלוא אומרים אנו שסתם \u0003פסח בשאר ימות השנה שלמים הוי\u0004 \u0005[הוא],\u0006 ואם כן אין צורך לומר במפורש שמקריבים אותו שלא לשמו! ולכאורה \u0003שמעת מינה\u0004 \u0005[שומע אתה מכאן]\u0006 כי \u0003פסח\u0004 שמקריבים אותו \u0003בשאר ימות השנה\u0004 כדי שייעשה לקרבן שלמים \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 כלומר, שיאמר במפורש שהוא מקריב אותו לשם שלמים ולא לשם פסח!","\u0003אמר ר' חייא בר גמדא: נזרקה מפי חבורה\u0004 כלומר, חבורת הלומדים שישבה ועסקה בנושא זה, אמר אחד מהם שלא זכרו מיהו, כיון שהסכימו כולם בסברה זו, \u0003ואמרו: כגון שהיו בעלים\u0004 של אותו קרבן \u0003טמאי מת\u0004 בפסח ראשון, \u0003ונדחין לפסח שני, דסתמיה לשום פסח קאי\u0004 \u0005[שמן הסתם\u0006 קרבן זה \u0005לשם פסח עומד]\u0006 ואם לא עקרוהו במפורש מתורת פסח אינו נעשה מעצמו כשלמים. מה שאין כן בשאר קרבנות פסח שעבר זמנם.","\u0003הפסח נשחט בשלש כתות\u0004 שמחלקים את המקריבים לשלוש קבוצות כמו \u0003שנאמר \"ושחטו אתו כל קהל עדת ישראל\u0004 בין הערבים\u0003\"\u0004 (שמות יב, ו), ונזכר כאן שלוש קבוצות: \u0003קהל, ועדה, וישראל\u0004 ולכן מחלקים את ישראל לשלוש כתות. וסדר הקרבתו: \u0003נכנסה כת הראשונה\u0004 של מקריבים ו\u0003נתמלאה העזרה\u0004 מהם, \u0003נעלו דלתות העזרה, תקעו הריעו ותקעו\u0004 הכהנים בשופרות, כשם שעושים בשעת הקרבת כל קרבן,","היו \u0003הכהנים עומדים שורות שורות\u0004 בין מקום השחיטה עד המזבח \u0003ובידיהם\u0004 בזיכים, לקבל בהם את דם הקרבן, \u0003בזיכי כסף ובזיכי זהב.\u0004 היתה \u0003שורה שכולה\u0004 כהנים המחזיקים בזיכי \u0003כסף כסף ושורה שכולה\u0004 כהנים המחזיקים בזיכי \u0003זהב זהב, ולא היו מעורבים\u0004 שלא היו בזיכי כסף וזהב באותה שורה. \u0003ולא היו לבזיכים שוליים\u0004 (תחתית רחבה) שיהיה אפשר להניחם, שאם היתה להם \u0003שמא\u0004 ישכחו ו\u0003יניחום ויקרש הדם\u0004 בינתים ויפסל מזריקה.","\u0003שחט ישראל\u0004 את הקרבן \u0003וקבל הכהן\u0004 את הדם \u0003נותנו\u0004 מיד \u0003לחבירו\u0004 העומד לידו \u0003וחבירו\u0004 מעבירו \u0003לחבירו,\u0004 ובינתיים \u0003מקבל\u0004 החבר \u0003את\u0004 הבזיך \u0003מלא\u0004 דם \u0003ומחזיר\u0004 לאחר \u0003את\u0004 הבזיך \u0003הריקן\u0004 שכבר זרקו את הדם שבו. \u0003כהן הקרוב אצל המזבח זורקו\u0004 על קיר המזבח \u0003זריקה אחת\u0004 ומקפיד שיהא זורק \u0003כנגד היסוד\u0004 במקום שהיה למזבח יסוד.","\u0003יצתה כת ראשונה\u0004 כאשר נגמר כל מעשה השחיטה \u0003ונכנסה כת שניה, יצתה שניה נכנסה שלישית, כמעשה הראשונה כך מעשה השניה והשלישית. קראו את הלל\u0004 כל ישראל העומדים בעזרה במשך זמן שחיטת הפסחים, ו\u0003אם גמרו\u0004 לקרוא את כל ההלל לפני שחיטת כל הקרבנות \u0003שנו\u0004 וקראו, \u0003ואם שנו\u0004 ולא נסתיימה שחיטת כל הפסחים \u0003שלשו\u0004 (בפעם שלישית), \u0003אף על פי ש\u0004למעשה \u0003לא שלשו מימיהם\u0004 שהיו הכהנים זריזים והספיקו לסיים את הכל קודם לכן. \u0003ר' יהודה אומר: מימיהם של כת שלישית לא הגיעו\u0004 אפילו בפעם הראשונה לאמירת \u0003\"אהבתי כי ישמע ה'\u0004 את קולי תחנוני\u0003\"\u0004 (תהילים קטז, א) שבראש פרק רביעי שבהלל, \u0003מפני שעמה מועטין\u0004 ועד שהיו קוראים שלושה פרקים כבר גמרו לשחוט.","\u0003כמעשהו\u0004 של קרבן הפסח \u0003בחול כך מעשהו בשבת, אלא שהכהנים\u0004 היו \u0003מדיחים את העזרה\u0004 בשבת מן הדם \u0003שלא ברצון חכמים\u0004 ולא רצו לשנות לענין זה ממנהג יום חול. \u0003ר' יהודה אומר:\u0004 לפני ההדחה \u0003כוס היה ממלא מדם התערובת\u0004 שהיה על הרצפה, \u0003זרקו זריקה אחת על גבי המזבח. ולא הודו לו חכמים\u0004 לר' יהודה בענין זה.","\u0003כיצד\u0004 היו \u0003תולין ומפשיטין\u0004 את הפסח בבית המקדש? \u0003אונקליות\u0004 (ווים) \u0003של ברזל היו קבועים בכתלים ובעמודים שבהן\u0004 היו \u0003תולין\u0004 את הפסח \u0003ומפשיטין\u0004 אותו. \u0003כל מי שאין לו מקום\u0004 באונקליות של עזרה \u0003לתלות ולהפשיט — מקלות דקים וחלקים\u0004 (מחולקים, מפוצלים לשנים) \u0003היו שם\u0004 בעזרה והיה \u0003מניח על כתפו ועל כתף חבירו ותולה\u0004 את הפסח על המקל ומפשיט. \u0003ר' אליעזר אומר: ארבעה עשר\u0004 בניסן"],["\u0003שחל להיות בשבת\u0004 ואסור לטלטל את המקלות (רמב\"ם), לכן היה \u0003מניח ידו על כתף חבירו ויד חבירו על כתיפו ותולה ומפשיט. קרעו\u0004 את בשר הפסח \u0003והוציא את אימוריו\u0004 (החלב ושאר חלקים שמקריבים על המזבח) \u0003נתנו במגיס\u0004 (כעין קערה גדולה) \u0003והקטירן\u0004 לאימורים \u0003על גבי המזבח.\u0004","ואם היה הדבר בשבת שיש איסור טלטול בו \u0003יצתה כת הראשונה וישבה לה בהר הבית, שניה\u0004 שיצאה ישבה \u0003בחיל\u0004 שהוא מחיצה שלפני עזרת נשים, \u0003והשלישית במקומה עומדת\u0004 בתוך המקדש, ומחכים הכל עד חשיכה, כשהגיעה \u0003חשיכה — יצאו וצלו את פסחיהן\u0004 כל אחד במקומו.","\u0003אמר ר' יצחק: אין הפסח נשחט אלא בשלש כתות של שלשים שלשים בני אדם\u0004 בכל אחת. \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של \u0005דבר]?\u0006 נאמר \u0003\"קהל\" ו\"עדה\" ו\"ישראל\",\u0004 והמספר הקטן ביותר שחל עליו כל אחד ממושגים אלה הוא עשרה אנשים, ו\u0003מספקא לן\u0004 \u0005[מסופק לנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בבת אחת\u0004 כל אלה \u0003אי\u0004 \u0005[אם]\u0006 \u0003בזה אחר זה,\u0004","\u0003הלכך\u0004 (לכן) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 כדי לצאת ידי שתי הסברות \u0003שלש כתות של שלשים שלשים בני אדם. דאי\u0004 \u0005[שאם]\u0006 תאמר שצריכים שיהיו כולם \u0003בבת אחת — הא איכא\u0004 \u0005[הרי יש],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003בזה אחר זה — הא איכא\u0004 \u0005[הרי יש],\u0006 \u0003הלכך\u0004 (לכן) בשעת הדחק שאין אנשים מצויים \u0003בחמשין נמי סגיא\u0004 \u0005[בחמישים גם כן מספיק]\u0006 ואין צריך דווקא לתשעים בני אדם. וכיצד? \u0003דעיילי תלתין ועבדי\u0004 \u0005[שנכנסים שלושים ועושים\u0006 את המוטל עליהם\u0005],\u0006 \u0003עיילי\u0004 \u0005[נכנסים]\u0006 \u0003עשרה\u0004 אחרים \u0003ונפקי\u0004 \u0005[ויוצאים]\u0006 \u0003עשרה\u0004 והרי הם נחשבים לכת שניה, \u0003ועיילי\u0004 \u0005[ונכנסים]\u0006 שוב \u0003עשרה\u0004 אחרים \u0003ונפקי\u0004 \u0005[ויוצאים]\u0006 \u0003עשרה\u0004 והם כת שלישית, ונמצא הפסח נשחט בשלוש כתות של שלושים אף שכולם יחד רק חמישים איש.","שנינו במשנה \u0003שנכנסה כת ראשונה\u0004 ונעלו את העזרה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדיוק הלשון. \u0003אביי אמר: ננעלו\u0004 דלתות העזרה מאליהן בנס \u0003תנן\u0004 \u0005[שנינו].\u0006 \u0003רבא אמר: נועלים תנן\u0004 \u0005[שנינו],\u0006 כלומר: דואגים לנעול את הדלתות בזמנן.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה ההבדל ביניהם\u0006 למעשה\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לענין \u0003למסמך אניסא\u0004 \u0005[לסמוך על הנס].\u0006 \u0003אביי אמר: ננעלו תנן\u0004 \u0005[שנינו],\u0006 \u0003כמה דעיילו — מעלו, וסמכינן אניסא\u0004 \u0005[שנכנסים —\u0006 \u0005נכנסים, וסומכים על הנס]\u0006 שיינעלו הדלתות מעצמן, כדי שלא יכנסו יותר מדי ויגיעו לידי סכנה (ר\"ח). ו\u0003רבא אמר: נועלין תנן\u0004 \u0005[שנינו],\u0006 \u0003ולא סמכינן אניסא\u0004 \u0005[ואין סומכים על הנס]\u0006 שלא יכנסו יותר מדי.","\u0003והא דתנן\u0004 \u0005[וזו ששנינו\u0006 במשנה אחרת\u0005]\u0006 שהזכירו שנידו את עקביא בן מהללאל על שאמר דברים קשים על שמעיה ואבטליון, \u0003אמר ר' יהודה: חס ושלום שעקביא בן מהללאל נתנדה, שאין עזרה ננעלת על כל אדם מישראל\u0004 כשבאים כל ישראל בשעת הרגל, ובכל זאת לא היה שם אדם שמלא \u0003בחכמה וביראת חטא כעקביא בן מהללאל\u0004 אלא אדם אחר הוא שנתנדה. את הלשון \"שאין עזרה ננעלת\" \u0003אביי מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ורבא מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003אביי מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003אין בעזרה בשעה שננעלה על כל אדם בישראל בחכמה וביראת חטא כעקביא. רבא מתרץ לטעמיה\u0004 \u0005[מסביר לטעמו,\u0006 לשיטתו\u0005]:\u0006 \u0003אין בעזרה בשעה שנועלים אותה על כל ישראל בחכמה וביראת חטא כעקביא בן מהללאל.\u0004","ולעצם הענין מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מעולם לא נתמעך אדם בעזרה\u0004 על אף ריבוי הקהל, \u0003חוץ מפסח אחד שהיה בימי הלל, שנתמעך בו זקן אחד, והיו קוראים אותו\u0004 פסח \u0003\"פסח מעוכין\".\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פעם אחת ביקש אגריפס המלך ליתן עיניו באוכלוסי ישראל\u0004 לדעת מה מניינם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לכהן גדול: תן עיניך בפסחים\u0004 שימנה את מספר פסחיהם ויקבל מושג ידוע ממספר התושבים. \u0003נטל כוליה\u0004 \u0005[כליה]\u0006 \u0003מכל אחד\u0004 שאת הכליות מקריבים על המזבח \u0003ונמצאו שם ששים ריבוא זוגי כליות\u0004 שהם \u0003כפלים כיוצאי מצרים.\u0004 ומעירים שמנין זה אינו מנין כל ישראל כי הרי זה חוץ ממי שהיה \u0003טמא\u0004 וחוץ ממי \u0003שהיה בדרך רחוקה\u0004 שלא באו להקריב. ועוד, שהרי לא נמנו האנשים אלא הפסחים, \u0003ואין לך כל פסח ופסח שלא נמנו עליו יותר מעשרה בני אדם.\u0004 ופסח זה \u0003היו קוראין אותו \"פסח מעובין\"\u0004 משום שהיה מרובה מאוד באוכלוסין.","על סיפור זה תוהים: כיצד \u0003נטל כוליא\u0004 \u0005[כליה]?\u0006 \u0003הא בעי אקטורה\u0004 \u0005[הרי צריך להקטירה]\u0006 על המזבח? ומשיבים: \u0003דהדר מקטיר להו\u0004 \u0005[שחוזר ומקטיר אותם].\u0006 ומקשים: והרי נאמר \u0003\"והקטירו\u0004 הכהן המזבחה לחם אשה לה'\u0003\"\u0004 (ויקרא ג, יא), ללמדנו \u0003שלא יערב חלביו של\u0004 קרבן \u0003זה בזה,\u0004 אלא כל אחד לעצמו!","ומשיבים: \u0003דהדר מקטיר להו חדא חדא\u0004 \u0005[שאחר כך\u0006 היה \u0005מקטיר אותם אחד אחד]\u0006 ולא בתערובת. ומקשים עוד: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]\u0006 על הכתוב \u0003\"והקטירם\u0004 הכהן המזבחה לחם אשה לריח ניחוח כל חלב לה'\u0003\"\u0004 (ויקרא ג, טז), משמע \u0003שיהא כולו\u0004 (כל האימורים מן הקרבן) קרב \u0003כאחד! אלא\u0004 יש לפרש שנטל את הכליות לספור אותן \u0003רק תפיסה בעלמא\u0004 \u0005[בלבד],\u0006 \u0003דשקיל מינייהו עד דיהבין ליה מידי אחרינא\u0004 \u0005[שנטל מהם\u0006 מכל אחד \u0005עד\u0006 שהיו \u0005נותנין לו דבר אחר]\u0006 לסימן, ואותם החפצים נמנו אחר כך.","שנינו במשנה שהיו ה \u0003כהנים עומדים\u0004 ב\u0003שורות,\u0004 והיו שורות כהנים שבידם בזיכי כסף ושורות שבידם בזיכי זהב, ולא עירבו אותם. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעמו\u0006 של דבר\u0005]\u0006 שלא עירבו את הבזיכים? \u0003אילימא דילמא שקלי דדהבא ומעיילי דכספא\u0004 \u0005[אם תאמר\u0006 שחששו \u0005שמא יקחו\u0006 הכהנים בזיך \u0005של זהב\u0006 ויגנבוהו \u0005ויכניסו\u0006 תחתיו בזיך \u0005של כסף],\u0006 אולם אם חוששים אנו לרמאים הלוא לא כל הבזיכים שוים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בשורה אחת של כלי זהב \u0003דילמא שקלי בר מאתן ומעיילי בר מאה\u0004 \u0005[שמא יקחו\u0006 בזיך \u0005בן מאתיים\u0006 דינר \u0005ומכניסים\u0006 בזיך \u0005בן מאה]\u0006 (רי\"ד), \u0003אלא\u0004 לא זה הטעם, כי אם \u0003דהכי שפיר טפי\u0004 \u0005[שכך יפה יותר]\u0006 שבכל שורה יש כלים מצבע אחד.","במשנה שנינו ש\u0003לא היו לבזיכים שוליים,\u0004 ומוסיפים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל הבזיכים שבמקדש לא היו להן שוליים\u0004 מאותו טעם — כדי שלא יניחום ויקרש הדם שבהם, \u0003חוץ מבזיכי לבונה\u0004 שהיו מניחים על \u0003לחם הפנים\u0004 שלהם עשו תחתית רחבה, שאם היו הבזיכים מחודדים בתחתיתם \u0003שמא יניחום על הלחם ויפרוס\u0004 (וישבר) \u0003הלחם.\u0004 שלחם הפנים היה עשוי בצורה מורכבת ועדינה, ובזיך שקצהו חד היה יכול לנקבו או לשברו.","שנינו במשנה: \u0003שחט ישראל וקבל הכהן\u0004 ונתנו לחבירו. ותוהים: \u0003לא סגיא\u0004 \u0005[די]\u0006 שמי \u0003דלאו\u0004 \u0005[שאינו]\u0006 \u0003ישראל\u0004 ישחט? וכי מצוה בישראל דווקא ולא בלוי או כהן?! ומשיבים: \u0003היא גופא קא משמע לן\u0004 \u0005[\u0006הלכה \u0005זו עצמה משמיע לנו\u0006 התנא\u0005]\u0006 ללמדנו ש\u0003שחיטה בזר כשירה\u0004 ואפילו ישראל רשאי לשחוט. ומה ששנינו במשנה: \u0003וקבל הכהן, הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]\u0006 ש\u0003מקבלה ואילך מצות כהונה\u0004 וזר אסור לו לעשות זאת.","שנינו שהיה הכהן לוקח את הבזיך ו\u0003נותנו לחבירו.\u0004 ולכאורה \u0003שמעת מינה\u0004 \u0005[שומע אתה מכאן]\u0006 כי \u0003הולכה שלא ברגל\u0004 בלא ללכת ממש אלא בהעברת החפץ מיד ליד בלבד — \u0003הויא\u0004 \u0005[הרי היא\u0006 נחשבת\u0005]\u0006 \u0003הולכה\u0004 ונפתרה על ידי כך בעיה זו שנחלקו בה במסכת זבחים (יד, ב) ולא נפתרה! ודוחים: \u0003דילמא הוא נייד פורתא\u0004 \u0005[שמא הוא\u0006 היה \u0005זז מעט\u0006 ברגליו\u0005]\u0006 תוך כדי העברת הכלי כדי לקיים מצות הולכה ברגל, ואין מכאן איפוא פתרון לשאלה. ושואלים: אם כן, \u0003אלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בסיפור זה על דרך הולכת הדם? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 שעושים שורות אלה כדי שיהיו כהנים רבים עסוקים בעבודה ויהיה בכך כדי לקיים \u0003\"ברב עם הדרת מלך\"\u0004 (משלי יד, כח).","שנינו במשנה שהכהן מ\u0003קבל את\u0004 הבזיך \u0003המלא ומחזיר את הריקן,\u0004 ואומרים: \u0003אבל איפכא\u0004 \u0005[להיפך]\u0006 \u0003לא,\u0004 שלא היה נותן קודם לחבירו את הריקן ואחר כך מקבל את המלא. \u0003מסייע ליה\u0004 \u0005[לו]\u0006 לשיטת \u0003ר' שמעון בן לקיש,\u0004 ש\u0003אמר ר' שמעון בן לקיש: אין מעבירים על המצו‍ת\u0004 שאם נזדמנה לו לאדם מצוה — חייב הוא לעשותה מיד ולא לדחותה (להעבירה) מפני דבר אחר. כמו כאן, שכיון שיש מצוה בהולכת הדם — צריך לקיים קודם מצוה זו שבאה לידו, ואחר כך להחזיר את הבזיך הדרוש לקבלה מחודשת של דם הזבחים שהיא מצוה העתידה לבוא מאוחר יותר.","שנינו עוד במשנה כי \u0003כהן הקרוב אצל המזבח\u0004 זורק את הדם למזבח. ושואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 הסבור שדם קרבן \u0003הפסח בזריקה\u0004 למזבח ולא די בשפיכתו שם? \u0003אמר רב חסדא:\u0004 שיטת \u0003ר' יוסי הגלילי היא\u0004","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר:\u0004 נאמר \"אך בכור שור או בכור כשב או בכור עז לא תפדה קודש הם \u0003את דמם תזרק על המזבח ואת חלבם תקטיר\u0004 אשה לריח ניחוח לה'\" (במדבר יח, יז), ומדייק: \u0003\"דמו\"\u0004 של הבכור \u0003לא נאמר אלא \"דמם\",\u0004 וכן \u0003\"חלבו\" לא נאמר אלא \"חלבם\". למד\u0004 על ידי כך על הקרבנות הדומים זה לזה בקדושתם על ה\u0003בכור\u0004 שנאמר בו כן במפורש \u0003ומעשר\u0004 בהמה \u0003ופסח,\u0004 שלא נתפרש כיצד נוהגים בהם במקדש בשעת הקרבה \u0003שהן טעונין\u0004 כמו הבכור גם \u0003מתן דמים\u0004 וגם הקרבת \u0003אימורין לגבי מזבח,\u0004 אף שלא נאמר הדבר במפורש במקומו.","ושואלים: \u0003מנלן\u0004 \u0005[מנין\u0006 למד\u0005]\u0006 ש\u0003טעונין יסוד,\u0004 שזריקת דמים צריכה להיות על המזבח בצד שיש בו יסוד? \u0003אמר ר' אלעזר: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בדרך גזירה שווה, משויון המלים שנאמר \u0003\"זריקה\" \"זריקה\" מעולה, כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"את דמם תזרק על המזבח\", וכתיב התם\u0004 \u0005[וכתוב שם]\u0006 בדין קרבן העולה \u0003\"\u0004ושחט אותו על ירך המזבח צפונה לפני ה' \u0003וזרקו בני אהרן הכהנים את דמו על המזבח סביב\"\u0004 (ויקרא א, יא), \u0003מה עולה טעונה\u0004 זריקה במקום שיש בו \u0003יסוד — אף פסח נמי\u0004 \u0005[גם כן]\u0006 \u0003טעון\u0004 זריקה במקום שיש בו \u0003יסוד.\u0004"],["ושואלים: \u0003עולה גופה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שיש לזרוק דמו במקום שיש בו יסוד? ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"ואת כל דם הפר ישפוך \u0003אל יסוד מזבח העלה\u0004 אשר פתח אהל מועד\" (ויקרא ד, ז), \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003עולה טעונה יסוד\u0004 שהרי מייחסים את יסוד המזבח דוקא לקרבן העולה.","שנינו כי לאחר ש \u0003יצתה כת ראשונה\u0004 היתה באה כת שניה ושלישית. \u0003תנא\u0004 \u0005[שנה\u0006 בתוספתא\u0005]\u0006 על הכת השלישית: \u0003היא נקראת כת עצלנית\u0004 שמתוך עצלותה הריהי אחרונה בכתות. ושואלים: \u0003והא לא סגי דלאו הכי\u0004 \u0005[והרי אי אפשר בלא כך]\u0006 שהרי חייבים שיהיו שלוש כתות, \u0003מאי הוי להו למיעבד\u0004 \u0005[מה היה להם לעשות]?\u0006","ומשיבים: \u0003אפילו הכי איבעי להו לזרוזי נפשייהו\u0004 \u0005[כך היה להם לזרז עצמם]\u0006 שלא ישארו להיות כת אחרונה. ובדומה לרעיון זה \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003רבי אומר: אי אפשר לעולם בלא\u0004 שיהא בו \u0003בסם\u0004 (מוכר בשמים) \u0003ובלא בורסי\u0004 המעבד עורות שריחם רע ושניהם נחוצים איפוא לעולם, אולם \u0003אשרי מי שאומנתו בסם אוי לו למי שאומנתו בורסי.\u0004 וכן \u0003אי אפשר לעולם בלא זכרים ובלא נקבות. אשרי מי שבניו זכרים, אוי לו\u0004 ל\u0003מי שבניו נקבות.\u0004","במשנה שנינו כי \u0003כמעשהו\u0004 של קרבן הפסח \u0003בחול\u0004 כך מעשהו בשבת שאף בשבת היו הכהנים מדיחים ושוטפים את רצפת העזרה אלא שדבר זה היה שלא ברצון חכמים. ושואלים: \u0003שלא ברצון מאן\u0004 \u0005[מי]?\u0006 כלומר בניגוד לרצונו של איזה חכם עשו מעשה זה? \u0003אמר רב חסדא: שלא ברצון ר' אליעזר\u0004 האוסר את טיאטוא הריצפה בשבת באיסור חמור ובדומה לכך אף את הדחתה. \u0003דאי רבנן\u0004 \u0005[שאם\u0006 תאמר כשיטת \u0005חכמים]\u0006 החולקים עליו \u0003הא אמרי\u0004 \u0005[הרי\u0006 הם \u0005אומרים]\u0006 שטיאטוא רצפה רק \u0003שבות הוא\u0004 ואינו אסור אלא מתקנת חכמים בלבד, וכלל בידינו ש\u0003אין שבות במקדש,\u0004 ולפיכך לדעת חכמים מותר להדיח את רצפת המקדש.","ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 המקור למחלוקת זו? ומשיבים: שהמקור הוא ממה ששנינו בברייתא: \u0003אחד החולב\u0004 את הפרה או \u0003המחבץ\u0004 (העושה חמאה. ערוך) \u0003והמגבן\u0004 (העושה גבינה), — שיעורם כדי להתחייב על עשייתם בשבת הוא \u0003כגרוגרות.\u0004 וכן אמרו כי \u0003המכבד\u0004 (המטאטא) \u0003והמרבץ\u0004 רצפה במים \u0003והרודה חלות דבש\u0004 מן הכוורת \u0003בשוגג בשבת — חייב חטאת\u0004 שעשה מלאכה האסורה מן התורה, ואם \u0003הזיד ביום טוב — לוקה את הארבעים\u0004 כמחלל יום טוב, אלו \u0003דברי ר' אליעזר.\u0004","\u0003וחכמים אומרים\u0004 על הדברים האחרונים, מכבד ומרבץ ורודה, \u0003אחד זה ואחד זה אינו אלא משום שבות.\u0004 ולשיטת ר' אליעזר ככיבוד — כן אף הדחה, שאסורה בשבת אף במקדש, שלא הותרו בו מלאכות האסורות מן התורה שאינן לצורך הקרבן ובכללה אף ההדחה שלאחר הקרבת הקרבן.","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהכוונה היא \u0003שלא ברצון חכמים\u0004 הסבורים שאינה אלא שבות, ובכל זאת עשיית הדבר — בניגוד לשיטת \u0003ר' נתן היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' נתן אומר: שבות צריכה\u0004 (נחוצה) \u0003התירו\u0004 במקדש, \u0003שבות שאינה צריכה לא התירו,\u0004 ואף ההדחה היא שבות שאינה צריכה שהרי אפשר להמשיך בעבודת הקודש גם בלא הדחה.","שנינו במשנה ש \u0003ר' יהודה אומר כוס היה ממלא\u0004 מדם התערובת שנשפך על הריצפה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יהודה אומר: כוס היה ממלא מדם התערובות,\u0004 וטעמו: \u0003שאם ישפך\u0004 כל \u0003דמו של אחד מהן\u0004 מן הקרבנות \u0003נמצא זה,\u0004 אותה כוס שיש בה משהו מדם הקרבן שנשפך, \u0003מכשירו.\u0004","\u0003אמרו לו\u0004 חכמים \u0003לר' יהודה: והלא לא נתקבל בכלי\u0004 דם זה שהוא מן הדם שנשפך מצואר הבהמה לארץ, ואינו ראוי לזריקה על המזבח. ותוהים: כיצד אמרו חכמים דבר זה? \u0003מנא ידעי\u0004 \u0005[מנין הם יודעים]\u0006 בוודאות שדם זה לא נתקבל בכלי?! \u0003אלא הכי קאמרי ליה\u0004 \u0005[כך אמרו לו]:\u0006 \u0003שמא לא נתקבל\u0004 דם זה \u0003בכלי\u0004 ושוב אינו כשר לזריקה. \u0003אמר להן\u0004 ר' יהודה לחכמים: \u0003אף אני לא אמרתי אלא בנתקבל בכלי.\u0004","שוב תוהים לצד השני: \u0003מנא ידע\u0004 \u0005[מנין יודע]\u0006 שדם זה הנאסף מן הרצפה הוא מן הדם שהתקבל בכלי? ומשיבים: \u0003כהנים זריזין הן\u0004 ובוודאי הקפידו שכל הדם יתקבל בכלי ולא ישפך לרצפה. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003זריזין\u0004 הם — \u0003אמאי משתפיך\u0004 \u0005[מדוע,\u0006 איך \u0005נשפך\u0006 הדם\u0005]?\u0006 ומשיבים: \u0003אגב זריזותייהו דעבדי משתפיך\u0004 \u0005[מתוך זריזותם שעושים\u0006 במהירות \u0005נשפך\u0006 הדם\u0005]\u0006 ולכן צריך לזרוק מדם התערובת.","ושואלים: \u0003והלא דם התמצית מעורב בו,\u0004 שהרי חלק מן הדם שעל הרצפה הוא מן הדם שהמשיך לשתות מצווארה לאחר שנשחטה הבהמה, והוא הקרוי דם התמצית, ודם התמצית אינו ראוי כלל למזבח! ומשיבים: \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 בכלל: \u0003דם התמצית דם מעליא\u0004 \u0005[מעולה]\u0006 \u0003הוא\u0004 לכל ענין. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 האוכל מ\u0003דם התמצית\u0004 הרי הוא \u0003באזהרה\u0004 כלומר: עבר על מצות לא תעשה, אבל אין דינו חמור כאוכל דם ממש שהוא חייב כרת. \u0003ר' יהודה אומר:\u0004 אף האוכל דם התמצית הרי הוא \u0003בהיכרת,\u0004 \u0005הרי שדין דם התמצית כשאר דם.\u0006","על תירוץ זה מקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: מודה ר' יהודה לענין כפרה\u0004 לזריקה על המזבח שדם התמצית \u0003אינו מכפר, שנאמר: \"\u0004כי נפש הבשר בדם היא ואני נתתיו לכם על המזבח לכפר על נפשותיכם \u0003כי הדם הוא בנפש יכפר\"\u0004 (ויקרא יז, יא),"],["\u0003דם שהנפש יוצאה בו\u0004 כלומר, דם שחיטה הקולח מיד הוא הדם ה\u0003מכפר,\u0004 ואותו זורקים על המזבח. \u0003דם שאין הנפש יוצאה בו\u0004 ושותת לאחר מכן — \u0003אינו מכפר.\u0004 ואם כן, לשיטת ר' יהודה יש לחשוש שמא זורק לא מן הדם שהנפש יוצאת בו שנשפך אלא מדם התמצית. \u0003אלא ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: אין דם מבטל דם,\u0004 ואין אומרים שמיעוט דם כשר בטל ברוב דם התמצית, וכיון שכך אפילו יש רוב דם התמצית בכוס זו, כיון שיש בה גם מעט מהדם הראוי לזריקה — זורקו ויוצא בו ידי חובה.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003אמר להן ר' יהודה לחכמים: לדבריכם\u0004 שאין צורך למלא מדם זה, \u0003למה\u0004 היו \u0003פוקקין\u0004 בערבי פסחים \u0003את העזרה\u0004 שלא ישטף הדם מיד לתוך הביבים המצויים בעזרה? \u0003אמרו לו: שבח הוא לבני אהרן שילכו עד ארכובותיהם\u0004 (קרסוליהם) בתוך \u0003דם\u0004 הקדשים שהם מראים בכך את חיבתם לקדושת העבודה.","ושואלים לגופו של ענין: כיצד ילכו עד ארכובותיהם בדם \u0003והא קא חייץ\u0004 \u0005[והרי הוא חוצץ]\u0006 בין רגלי הכהן ורצפת המקדש ובכך נפסלת העבודה?! ומשיבים: דם זה \u0003לח הוא ואינו חוצץ. כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הדם\u0004 או \u0003הדיו\u0004 או \u0003החלב\u0004 או \u0003הדבש,\u0004 אם היו \u0003יבשים — חוצצין\u0004 לענין טבילה ולשאר עניינים, אם היו \u0003לחין — אין חוצצין.\u0004 ועוד שואלים: אם הולכים בדם \u0003הא קמתווסי מאנייהו\u0004 \u0005[והרי מתלכלכים בגדיהם],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003היו בגדיו\u0004 של כהן \u0003מטושטשין\u0004 (מלוכלכים) \u0003ועבד\u0004 בהם — \u0003עבודתו פסולה,\u0004 שחייבים בגדי כהונה להיות בגדי נוי והדר. \u0003וכי תימא דמדלו להו למאנייהו\u0004 \u0005[ואם תאמר שמרימים את בגדיהם]\u0006 שלא יתלכלכו — \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 אחרת הדורשת מה שנאמר \u0003\"\u0004ולבש הכהן \u0003מדו בד\"\u0004 (ויקרא ו, ג), \u0003מדו\u0004 משמע: שיהא הבגד \u0003כמדתו\u0004 בדיוק, \u0003שלא יחסר ולא יותיר\u0004 והמרים את בגדו — שוב אין הבגד בדיוק כמידתו! ומשיבים שהיו הכהנים הולכים ורגליהם בתוך הדם לא בעבודות הקודש עצמן אלא רק \u0003בהולכת האיברים לכבש דלאו\u0004 \u0005[שאינה]\u0006 \u0003עבודה\u0004 מעבודות הקודש \u0003היא\u0004 אלא רק הכנה לעבודה אחרת.","","ומקשים: ולא? וכי אין זו עבודה? \u0003והא מדבעי כהונה\u0004 \u0005[והרי ממה שצריך\u0006 שתיעשה עבודה זו \u0005בכהנים\u0006 דווקא\u0005]\u0006 משמע ש\u0003עבודה היא! דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב \u0003\"והקריב הכהן את הכל\u0004 והקטיר \u0003המזבחה\u0004 עולה הוא אישה ריח ניחוח לה'\u0003\"\u0004 (ויקרא א, יג) — \u0003זו הולכת האברים לכבש! אלא\u0004 צריך לומר שהכהנים היו הולכים ורגליהם בתוך הדם בשעת \u0003הולכת עצים למערכה דלאו\u0004 \u0005[שאין]\u0006 \u0003עבודה היא.\u0004","ושואלים: אולם אם המקדש מוצף בדם \u0003בהולכת אברים לכבש ובהולכת דם למזבח, מיהא היכי אזלי\u0004 \u0005[בכל אופן כיצד הולכים]\u0006 בלא שתהיה חציצה ובלא להתלכלך בדם? ומשיבים: \u0003דמסגי אאיצטבי\u0004 \u0005[שהם הולכים על איצטבאות].\u0006 שהיו בונים חלקים מוגבהים ברצפה, ועליהם היו הולכים ואין כאן איפוא חציצה ולכלוך.","שנינו במשנה: \u0003כיצד תולין ומפשיטין את הפסח, וכן כי לאחר הפשטה קרעו והוציאו את אמוריו ואחר כך נתנם המפשיט במגיס להקטירם.\u0004 ושואלים: \u0003אטו הוא גופיה\u0004 \u0005[וכי הוא עצמו]\u0006 דווקא זה שהפשיט את הבהמה ונתן את האימורים למגיש הוא \u0003הוה מקטר להו\u0004 \u0005[היה מקטיר אותם]\u0006 ולא אחר, והרי הפשט הפסח מותר אף בזר ואינו צריך שייעשה דווקא על ידי כהן, וזר הרי אינו ראוי להקטיר? ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]:\u0006 \u0003להקטירן על גבי המזבח\u0004 שהיה נותנן במגיס כהכנה להקטרת החלבים על גבי המזבח, ולא שהוא עצמו מקטירם.","ועוד שנינו: \u0003יצתה כת ראשונה\u0004 וקרבן הפסח עימה אל מחוץ לעזרה, \u0003תנא\u0004 \u0005[שנה\u0006 בתוספתא\u0005]:\u0006 \u0003כל אחד ואחד נותן פסחו\u0004 בתוך \u0003עורו ומפשיל\u0004 אותו ומטילו \u0003לאחוריו\u0004 ונושאו כך לביתו. \u0003אמר רב עיליש: טייעות\u0004 כלומר, נשאו אותו כמנהג הישמעאלים.","","\u0003אלו דברים\u0004 בקרבן ה\u0003פסח דוחים את השבת\u0004 אם חל ערב פסח בשבת: \u0003שחיטתו, וזריקת דמו, ומיחוי\u0004 (ניקוי) \u0003קרביו, והקטרת חלביו\u0004 על המזבח, שהן עבודות שצריכות להיעשות מבעוד יום. \u0003אבל צלייתו והדחת\u0004 (רחיצת) \u0003קרביו\u0004 שאינן צריכות להיעשות מבעוד יום — \u0003אינן דוחין את השבת\u0004 אלא ממתינים עד שתצא השבת ואז עושים מלאכות אלה. \u0003הרכבתו\u0004 של הפסח עצמו דרך רשות הרבים, שהרי קרבן הפסח היה בא מן הטלאים או הגדיים, והיו ביניהם קטנים מאד שאינם יכולים להלך בעצמם כל הדרך כולה, והיו נוהגים להרכיבם על כתפיהם, וכן \u0003הבאתו מחוץ לתחום, וחתיכת יבלתו\u0004 שאם היתה בבהמה יבלת הנחשבת כמום כל עוד היא בה, ואם תיחתך תהא הבהמה כשרה להקרבה — \u0003אין דוחין את השבת\u0004 משום שהיו יכולים להיעשות לפני השבת. \u0003ר' אליעזר אומר:\u0004 כל אלה \u0003דוחין\u0004 את השבת. \u0003אמר ר' אליעזר: והלא דין\u0004 (קל וחומר) \u0003הוא: מה אם שחיטה\u0004 לחולין \u0003שהיא\u0004 אסורה בשבת \u0003משום מלאכה\u0004 בכל זאת \u0003דוחה את השבת\u0004 לצורך קרבן הפסח, \u0003אלו\u0004 הרכבתו והבאתו מחוץ לתחום וכיוצא בהן, האסורים \u0003משום שבות\u0004 וגזירת חכמים בלבד, \u0003לא ידחו את השבת? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: יום טוב יוכיח שהתירו בו\u0004 בתורה דברים שהם \u0003משום מלאכה\u0004 כגון שחיטה, בישול ואפייה \u0003ואסור\u0004 לעשות \u0003בו\u0004 כל מה שאסרו חכמים \u0003משום שבות.\u0004 ואין איפוא ללמוד מן ההיתר בתורה לכל איסורי חכמים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר: מה זה יהושע?!\u0004 כיצד מוכיח אתה הוכחה פגומה כזו \u0003מה ראיה רשות למצוה?\u0004 וכיצד אפשר להוכיח מאיסור עשיית מלאכת שבות ביום טוב אף על פי שהותרה בו מלאכת הרשות (כגון שחיטה ובישול לאכילת הדיוט), לענין של עבירה על שבות כדי לקיים מצות פסח! \u0003השיב ר' עקיבא\u0004 כשיטת ר' יהושע, \u0003ואמר: הזאה\u0004 ממי חטאת על טמא מת כדי לטהרו \u0003תוכיח, שהיא משום מצוה\u0004 כדי לאפשר לאדם להקריב את הפסח, ואסורה \u0003משום שבות\u0004 שהרי אינה מלאכה גמורה \u0003ואינה דוחה את השבת,\u0004 שאם חל יום השביעי לטומאתו בערב פסח שחל להיות בשבת — אין להזות עליו. ו\u0003אף אתה אל תתמה על אלו\u0004 הרכבתו והבאתו מחוץ לתחום וחתיכת יבלתו, \u0003שאף על פי שהן משום מצוה והן\u0004 אסורים \u0003משום שבות — לא ידחו את השבת.\u0004 \u0003אמר לו ר' אליעזר:\u0004 אין אני מקבל ראיה זו כי \u0003עליה\u0004 על הזאה עצמה \u0003אני דן,\u0004 וטוען כי אף אותה יש להתיר. ומאותו טעם: \u0003מה אם שחיטה שהיא משום מלאכה דוחה את השבת — הזאה שהיא\u0004 אסורה \u0003משום שבות\u0004 בלבד \u0003אינו דין שדוחה את השבת?\u0004 ואין איפוא להקשות עלי מדבר שאיני מודה בו.","","",""],["\u0003אמר לו ר' עקיבא\u0004 לר' אליעזר: \u0003או חלוף,\u0004 ושמא נחליף את סדר הקל וחומר שלך ונאמר להיפך: \u0003מה אם הזאה שהיא\u0004 אסורה בשבת \u0003משום שבות\u0004 בלבד \u0003אינה דוחה את השבת\u0004 כפי המקובל בידינו, \u0003שחיטה שהיא\u0004 אסורה \u0003משום מלאכה, אינו דין שלא תדחה את השבת\u0004 ותהיה אסורה שחיטת הפסח כשחל ערב פסח להיות בשבת?! \u0003אמר לו ר' אליעזר:\u0004 כיצד אפשר לומר כך? \u0003עקיבא, עקרת מה שכתוב בתורה \"\u0004ויעשו בני ישראל את הפסח \u0003במועדו\"\u0004 (במדבר ט, ב), ובמועדו משמע \u0003בין בחול בין בשבת.\u0004","\u0003אמר לו\u0004 ר' אליעזר: \u0003רבי, הבא לי מועד\u0004 האמור בתורה \u0003לאלו\u0004 כלומר, להרכבתו ולהבאתו מחוץ לתחום, \u0003כמועד לשחיטה.\u0004 שהרי לשחיטה נאמר זמן קבוע ואין אפשרות לעשותה אלא בארבעה עשר בניסן ואין לדחותה לזמן אחר, אבל להבאת הבהמה לא נאמר זמן קבוע ולכך אין לעשותה אלא מלפני השבת. \u0003כלל אמר ר' עקיבא: כל מלאכה\u0004 הצריכה לקרבן \u0003שאפשר לעשותה מערב שבת — אינה דוחה את השבת, שחיטה שאי אפשר לעשותה מערב שבת — דוחה את השבת.\u0004","לעצם ההלכה היסודית בענין פסח שחל להיות בשבת \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הלכה זו נתעלמה מבני בתירא\u0004 שהיו ראשי הדור באותם הימים. \u0003פעם אחת חל ארבעה עשר\u0004 בניסן \u0003להיות בשבת, שכחו ולא ידעו אם פסח דוחה את השבת אם לאו. אמרו: כלום יש אדם שיודע אם פסח דוחה את השבת אם לאו? אמרו להם: אדם אחד יש\u0004 בירושלים \u0003שעלה מבבל והלל הבבלי שמו, ששימש\u0004 בשעתו את \u0003שני גדולי הדור שמעיה ואבטליון, ויודע\u0004 בוודאי \u0003אם פסח דוחה את השבת אם לאו. שלחו\u0004 בני בתירא \u0003וקראו לו, אמרו לו: כלום אתה יודע אם הפסח דוחה את השבת אם לאו? אמר להם: וכי פסח אחד\u0004 בלבד \u0003יש לנו בשנה שדוחה את השבת? והלא הרבה יותר ממאתים פסחים\u0004 (קרבנות) \u0003יש לנו בשנה שדוחין את השבת.\u0004","\u0003אמרו לו: מנין לך? אמר להם: נאמר \"מועדו\" בפסח, ונאמר \"מועדו\"\u0004 גם \u0003ב\u0004קרבן ה\u0003תמיד,\u0004 כאמור: \"צו את בני ישראל ואמרת אליהם את קרבני לחמי לאישי ריח ניחוחי תשמרו להקריב לי במועדו\" (במדבר כח, ב), הרי מפורש שמקריבים את קרבן התמיד אף בשבת, נמצא שביותר מחמישים שבתות השנה מקריבים קרבן תמיד של בוקר וקרבן תמיד של בין הערביים, וכן את שני הכבשים של מוספי השבת, נמצאו יותר ממאתים קרבנות בשנה הדוחים את השבת. \u0003מה \"מועדו\" האמור בתמיד דוחה את השבת, אף \"מועדו\" האמור בפסח דוחה את השבת.\u0004","\u0003ועוד, קל וחומר הוא: ומה\u0004 קרבן \u0003תמיד שאין ענוש כרת\u0004 אם לא הקריבו \u0003דוחה את השבת, פסח שענוש כרת\u0004 אם לא הקריבו \u0003אינו דין שדוחה את השבת.\u0004","כיון שהביא הלל ראיות אלה \u0003מיד הושיבוהו בראש ומינוהו נשיא עליהן והיה דורש כל היום כולו בהלכות הפסח. התחיל\u0004 בתוך דבריו \u0003מקנטרן\u0004 (מתגרה בהם) \u0003בדברים. אמר להן: מי גרם לכם שאעלה מבבל ואהיה נשיא עליכם — עצלות שהיתה בכם שלא שמשתם שני גדולי הדור\u0004 שהיו בארץ ישראל, \u0003שמעיה ואבטליון.\u0004","\u0003אמרו לו: רבי, שכח\u0004 אדם \u0003ולא הביא סכין מערב שבת,\u0004 ואינו יכול לשחוט את הפסח, \u0003מהו?\u0004 מה יעשה והלוא כיון שהיה יכול וצריך להביאו מערב שבת, שוב אינו יכול להביאו היום? \u0003אמר להן: הלכה זו שמעתי\u0004 מרבותי \u0003ושכחתי, אלא הנח להם לישראל, אם אין נביאים הן\u0004 שנגלה להם סוד ה' — \u0003בני נביאים הן\u0004 ובודאי יכוונו מעצמם לאמת.","\u0003למחר\u0004 בשבת בערב הפסח \u0003מי\u0004 שהיה \u0003פסחו טלה\u0004 היה לוקח את הסכין ו\u0003תוחבו בצמרו,\u0004 ו\u0003מי ש\u0004היה \u0003פסחו גדי\u0004 שאין לו צמר, \u0003תוחבו בין קרניו. ראה\u0004 הלל \u0003מעשה\u0004 שעשו \u0003ונזכר\u0004 ב\u0003הלכה. ואמר: כך\u0004 באמת \u0003מקובלני מפי שמעיה ואבטליון\u0004 שכן ראוי לעשות.","עד כאן לשון הברייתא, ומעתה באים לבררה בגמרא. \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003נאמר \"מועדו\" בפסח ונאמר \"מועדו\" בתמיד, מה \"מועדו\" האמור בתמיד דוחה את השבת, אף \"מועדו\" האמור בפסח דוחה\u0004 את ה\u0003שבת.\u0004 ושואלים: \u0003ותמיד גופיה\u0004 \u0005[עצמו]\u0006 \u0003מנלן דדחי\u0004 \u0005[מנין לנו ש\u0006הקרבתו \u0005דוחה]\u0006 את ה\u0003שבת? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003ב\"מועדו\" — פסח נמי הא כתיב ביה\u0004 \u0005[גם כן הרי נאמר בו]\u0006 \u0003\"מועדו\",\u0004 ואין די בכך שהרי אם היה אפשר ללמוד זאת מלשון \"מועדו\" בלבד לא היה צורך ללומדו בגזירה השווה!","\u0003אלא\u0004 על כרחך \u0003\"מועדו\"\u0004 שנאמר בפסח \u0003לא משמע ליה\u0004 \u0005[נשמע לו]\u0006 שאפשר ללמוד מזה שהקפיד עליו הכתוב עד כדי שידחה את השבת. אם כן \u0003הכא נמי\u0004 \u0005[כאן\u0006 בשבת \u0005גם כן]\u0006 \u0003\"מועדו\" לא משמע ליה\u0004 \u0005[נשמע לו]\u0006 ואינו למד מכאן. \u0003אלא\u0004 הטעם הוא כי \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בהמשך הדברים: \u0003\"עלת שבת בשבתו על עלת התמיד ונסכה\"\u0004 (במדבר כח, י), \u0003מכלל\u0004 \u0005[מכאן]\u0006 ש\u0003עולה\u0004 של \u0003תמיד\u0004 קריבה בשבת.","ועוד שואלים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003ועוד קל וחומר, ומה תמיד שאין ענוש כרת\u0004 על אי הקרבתו \u0003דוחה את השבת, פסח שענוש כרת\u0004 על אי הקרבתו \u0003אינו דין שדוחה את השבת.\u0004 ומעירים: \u0003איכא למיפרך\u0004 \u0005[יש מקום לשבור]\u0006 את תוקפו של הקל וחומר: \u0003מה לתמיד\u0004 שהוא חמור מצד אחר \u0003שכן\u0004 הוא \u0003תדיר\u0004 ודבר התדיר בכל יום יש לו דין קדימה, ועוד שהוא \u0003כליל\u0004 שהוא עולה כולו למזבח, לא כפסח שרובו נאכל להדיוטות. ומסבירים, כך היה; \u0003קל וחומר אמר להו ברישא ופרכוה\u0004 \u0005[להם בתחילה ופרכוהו]\u0006 כפי שאמרנו, והוכיחו שאין לסמוך עליו. \u0003והדר אמר להו\u0004 \u0005[ואחר\u0006 כך \u0005אמר להם]\u0006 \u0003גזירה שוה,\u0004 וגזירה שוה היא מסורת עד למשה מסיני ומחייבת.","ושואלים: \u0003וכי מאחר\u0004 (מכיון) \u0003דגמר\u0004 \u0005[שלמד]\u0006 מרבותיו \u0003גזירה שוה\u0004 לענין זה, \u0003קל וחומר למה לי?\u0004 לשם מה להוסיף לימוד משל עצמו, כאשר יש בידו מסורת מוחלטת שכך היא ההלכה! ומשיבים: \u0003אלא לדידהו קאמר להו\u0004 \u0005[להם\u0006 לשיטתם \u0005אמר להם]\u0006 להראות שלא טרחו דיים בבירור הלכה זו. \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גזירה שוה לא גמריתו\u0004 \u0005[למדתם\u0006 בעצמכם\u0005]\u0006 משום שנהגתם לפי הכלל ש\u0003אין אדם דן גזירה שוה מעצמו\u0004 שאין סוף לדברים שאפשר להוציא בדרך זו, ואין לה תוקף אלא אם קיבלה מפי רבו והם לא קיבלוה מרבותיהם. \u0003אלא קל וחומר\u0004 ש\u0003אדם דן מעצמו איבעי לכו למידן\u0004 \u0005[צריך היה לכם לדון]\u0006 והייתם יודעים לפתור בעיה זו! \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003קל וחומר פריכא הוא\u0004 \u0005[שבור,\u0006 מפוקפק] שהרי אפשר לסתרו מיד כפי שאמרנו.","\u0003אמר מר\u0004 בברייתא: \u0003למחר מי ש\u0004היה \u0003פסחו טלה — תוחב לו\u0004 סכין \u0003בצמרו,\u0004 ומי שהיה פסחו \u0003גדי\u0004 — \u0003תוחב לו\u0004 סכין \u0003בין קרניו\u0004 וכך לא עבר על טלטול הסכין בשבת."],["\u0003והא קא עביד\u0004 \u0005[והרי הוא עושה]\u0006 \u0003עבודה בקדשים,\u0004 שהוא משתמש בטלאים ובגדיים האלו שהוקדשו כקרבן לצורך הובלת משא, ואסור להשתמש בקדשים! ומשיבים שנהגו בענין זה \u0003כהלל. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמרו עליו על הלל: מעולם לא מעל אדם בעולתו.\u0004 וכיצד היה הדבר — שהיה נזהר שלא להקדישה תחילה \u0003אלא מביאה חולין לעזרה\u0004 ושם היה \u0003מקדישה, וסומך ידו עליה ושוחטה\u0004 מיד. ובאותו יום עשו כך גם מביאי הפסח שהקדישו את הטלאים כקרבן רק כשהגיעו לעזרה.","ושואלים: אם כך היה, \u0003בשבת היכי מצי מקדיש ליה\u0004 \u0005[כיצד יכול להקדישו],\u0006 והרי כאן מדובר בערב פסח שחל להיות בשבת. \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין מקדישין ואין מעריכין\u0004 (מין נדר שאדם נודר לתת את ערכו למקדש. ויקרא כז) \u0003ואין מחרימין, ואין מגביהין\u0004 (מפרישים) \u0003תרומה ומעשרות.\u0004 ו\u0003כל\u0004 איסורים \u0003אלו ביום טוב אמרו, קל וחומר בשבת\u0004 שגזרו חכמים שלא יעשו כן משום שנראה כמקח וממכר ומעשי חול!","ומשיבים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין מקדישים נאמרו \u0003בחובות שאין קבוע להן זמן\u0004 כלומר, באותם קרבנות שאין זמן קבוע להקרבתם, אותם אסרו להקדיש בחג ובשבת. \u0003אבל בחובות שקבוע להן זמן\u0004 כגון פסח — \u0003מקדישין\u0004 אף בשבת. שכן \u0003אמר ר' יוחנן: מקדיש אדם את פסחו בשבת\u0004 ואת \u0003חגיגתו ביום טוב,\u0004 שכיון שקרבנות אלה יש חובה להקריבם דווקא ביום זה מותר להקדישם לכך אף בשבת, שלא עמדו חכמים על גזירתם במקרה זה.","ומקשים עוד: כיצד יכלו לעשות זאת? \u0003והלא מחמר!\u0004 שהרי המוליך את הטלה שעליו הסכין הוא כמחמר אחר בהמת משא, ואסור בשבת! ומשיבים: \u0003מחמר כלאחר יד,\u0004 שלא היו נוהגים בטלה כדרך שעושה מחמר אלא עושים בשינוי כלאחר יד. ומקשים: \u0003מחמר כלאחר יד נמי\u0004 \u0005[גם כן]\u0006 \u0003נהי דאיסורא דאורייתא ליכא\u0004 \u0005[אמנם איסור מהתורה אין כאן]\u0006 אבל \u0003איסורי מדרבנן מיהא איכא\u0004 \u0005[איסור\u0006 מדברי \u0005סופרים מכל מקום יש\u0006 כאן\u0005],\u0006 שאמנם העושה מלאכה בשינוי פטור מן התורה, אבל אסור מדברי סופרים משום שבות.","ומשיבים: \u0003היינו דקא בעי מיניה \u0004\u0005[זהו \u0006הספק\u0005 ששאלו אותו]\u0006 בני בתירא את הלל. וזוהי הגדרתה הכללית של השאלה: \u0003דבר שיש לו היתר מן התורה, ודבר שבות עומד לפניו\u0004 ומונע מלעשותו \u0003לעקרו כלאחר יד במקום מצוה מאי \u0004\u0005[מה]\u0006 דינו?! שהרי הבאת הקרבן היא מצוה והנהגת הטלה שיש עליו משא — שבות, ועושה כלאחר יד, האם מותר הדבר? \u0003אמר להן: הלכה זו שמעתי ושכחתי אלא\u0004 יש לסמוך על ישראל ש\u0003אם אין נביאים הן בני נביאים הן\u0004 שימצאו את הפתרון מעצמם.","על המעשה שהיה בהלל \u0003אמר רב יהודה אמר רב: כל המתיהר\u0004 (מתגאה), \u0003אם חכם הוא — חכמתו מסתלקת ממנו, אם נביא הוא — נבואתו מסתלקת ממנו.\u0004 ומפרט: \u0003אם חכם הוא חכמתו מסתלקת ממנו\u0004 — למדים \u0003מהלל,\u0004 שכן \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא זו: \u0003התחיל\u0004 הלל \u0003מקנטרן בדברים,\u0004 וכיון שהתגאה עליהם \u0003קאמר להו\u0004 \u0005[אמר להם]\u0006 אחר כך \u0003הלכה זו שמעתי ושכחתי,\u0004 שנענש בשיכחה משום יוהרה. \u0003אם נביא הוא נבואתו מסתלקת ממנו\u0004 — למדים אנו \u0003מדבורה\u0004 הנביאה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כיון שאמרה \u0003\"חדלו פרזון בישראל חדלו עד שקמתי דבורה שקמתי אם בישראל\"\u0004 (שופטים ה, ז), שיש בכך משום דברי התפארות על עצמה, נענשה שנסתלקה ממנה נבואתה, \u0003וכתיב\u0004 \u0005[ו\u0006כפי ש\u0005נאמר]\u0006 אחר כך שהיה צריך לומר לה \u0003\"עורי עורי דבורה עורי עורי דברי שיר\"\u0004 (שופטים ה, יב), כיון שפסקה מנבואתה.","\u0003ריש לקיש אמר\u0004 בדומה לדברי רב: \u0003כל אדם שכועס, אם חכם הוא — חכמתו מסתלקת ממנו, אם נביא הוא — נבואתו מסתלקת ממנו.\u0004 ומפרש: \u0003אם חכם הוא חכמתו מסתלקת ממנו\u0004 — למדים אנו \u0003ממשה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקצף משה על פקודי החיל\u0004 שרי האלפים ושרי המאות הבאים מצבא המלחמה\u0003\"\u0004 (במדבר לא, יד), ומה ענשו — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 אחר כך: \u0003\"ויאמר אלעזר הכהן אל אנשי הצבא הבאים למלחמה זאת חקת התורה אשר צוה ה' את משה\"\u0004 (במדבר לא, כא), \u0003מכלל דמשה איעלם מיניה\u0004 \u0005[מכאן שמשה\u0006 עצמו \u0005נעלם ממנו]\u0006 ששכח הלכות אלו משום שכעס.","\u0003אם נביא הוא נבואתו מסתלקת ממנו\u0004 — נלמד \u0003מאלישע, דכתיב\u0004 שנאמר שכעס על מלך ישראל ואמר לו: \u0003\"לולי פני יהושפט מלך יהודה אני נשא אם אביט אליך ואם אראך\"\u0004 (מלכים ב' ג, יד), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 אחר כך: \u0003\"ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה'\"\u0004 (מלכים ב' ג, טו), שכיון שכעס על מלך ישראל נסתלקה ממנו נבואתו, והיה צריך למנגן שיעורר בו רוח נבואה.","\u0003אמר ר' מני בר פטיש: כל שכועס, אפילו פוסקין\u0004 (קובעים) \u0003עליו גדולה מן השמים — מורידין אותו\u0004 מגדולתו. \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003מאליאב\u0004 אחיו הגדול של דוד, \u0003שנאמר: \"ויחר אף אליאב בדוד ויאמר למה זה ירדת ועל מי נטשת מעט הצאן ההנה במדבר אני ידעתי את זדנך ואת רע לבבך כי למען ראות המלחמה ירדת\"\u0004 (שמואל א' יז, כח), הרי שכעס. \u0003וכי אזל\u0004 \u0005[וכאשר הלך]\u0006 \u0003שמואל לממשחינהו\u0004 \u0005[למשוח אותם]\u0006 שאמר לו ה' שראה מלך מבני ישי, \u0003בכלהו\u0004 \u0005[בכולם],\u0006 בכל האחים נאמר: \u0003\"לא בזה בחר ה'\"\u0004 (שמואל א' טז, ח), \u0003ובאליאב כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ויאמר ה' אל שמואל אל תבט אל מראהו ואל גבה קומתו כי מאסתיהו\"\u0004 (שמואל א' טז, ז), \u0003מכלל דהוה רחים ליה עד האידנא\u0004 \u0005[מכאן שהיה אוהב אותו עד עכשיו]\u0006 ואחר כך נמאס, שלולא היה כעסן היה ראוי לגדולה, ובגלל פגם זה מאס בו הקדוש ברוך הוא.","אגב הדיון בהוכחה שהפסח דוחה את השבת, דנים אנו בשאלה נוספת. \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 ראיות ש\u0003תמיד ופסח דדחו\u0004 \u0005[דוחים]\u0006 את ה\u0003שבת, דדחו\u0004 \u0005[שהם דוחים]\u0006 גם את ה\u0003טומאה מנא לן\u0004 \u0005[מנין לנו]?\u0006 שמקובל בידינו כי אם הכל טמאים בכל זאת מקריבים קרבנות ציבור ופסח. \u0003אמרי\u0004 \u0005[אומרים]\u0006 \u0003כי היכי דיליף\u0004 \u0005[כפי שלומד]\u0006 \u0003פסח מתמיד לענין שבת\u0004 שהשבת נדחית מפני הקרבן, \u0003הכי נמי יליף\u0004 \u0005[כך גם כן לומד]\u0006 \u0003תמיד מפסח לענין טומאה,\u0004 שכשם שהפסח דוחה את טומאת הכלל כן קרבן התמיד דוחה את טומאת הכלל.","ושואלים: \u0003ופסח גופיה מנלן\u0004 \u0005[עצמו מנין לנו]\u0006 שאם רוב העם טמאים בכל זאת הוא קרב? \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 \"דבר אל בני ישראל לאמר \u0003איש איש כי יהיה טמא לנפש\u0004 או בדרך רחוקה לכם או לדורותיכם ועשה פסח לה', בחודש השני בארבעה עשר יום בין הערבים יעשו אותו על מצות ומרורים יאכלוהו\" (במדבר ט, י-יא), ונדייק מכאן: \u0003איש\u0004 אחד או אנשים מעטים \u0003נדחה לפסח שני\u0004 אם היה טמא, \u0003ואין ציבור נידחין לפסח שני, אלא עבדי\u0004 \u0005[עושים]\u0006 פסח \u0003בטומאה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן:\u0004 מפסוק זה אין הוכחה, \u0003אימא\u0004 \u0005[אמור]\u0006 ודייק כך: \u0003איש נדחה לפסח שני, ציבור — לית להו תקנתא\u0004 \u0005[אין להם תקנה]\u0006 כלל \u0003לא בפסח ראשון ולא בפסח שני!\u0004","\u0003אלא אמר ר' שמעון בן לקיש\u0004 יש לדחות ראיה זו ולהביא ראיה אחרת \u0003מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"\u0004צו את בני ישראל \u0003וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\"\u0004 (במדבר ה, ב), \u0003יאמר\u0004 הכתוב רק שמשלחין \u0003טמאי מתים ואל יאמר זבין ומצורעין, ואני אומר\u0004 ולמד מעצמי את הדין בקל וחומר: \u0003אם טמאי מתים\u0004 שאין טומאתם חמורה כל כך שהרי רק קיבלו טומאה מאחר, בכל זאת \u0003משתלחין, זבין ומצורעין\u0004 שטומאתם נובעת מתוך עצמן — \u0003לא כל שכן\u0004 שמשלחים אותם מן המחנה? ואם כן יש יתור דברים בפסוק זה."],["\u0003אלא\u0004 ללמדך ש\u0003יש לך שעה שזבין ומצורעין משתלחין\u0004 מן העזרה \u0003ואין טמאי מתים משתלחין, ואיזה זה — פסח הבא בטומאה\u0004 שבו הותרה טומאת מת, אבל לא הותרה טומאת זבים ומצורעים, ומכאן למדנו דין פסח הבא בטומאה כשרוב העם טמאים, אבל זב ומצורע נדחים ואינם מקריבים בטומאה.","\u0003אמר אביי: אי הכי\u0004 \u0005[אם כך]\u0006 יש לדרוש את הכתוב \u0003לימא נמי\u0004 \u0005[שיאמר גם כן]\u0006 \u0003יאמר\u0004 בפסוק \u0003זב וטמאי מתים ואל יאמר מצורע, ואני אומר: זב משתלח, מצורע לא כל שכן\u0004 שטומאת מצורע חמורה מטומאת זב. \u0003אלא\u0004 כך נצטרך לומר: \u0003יש לך שעה שמצורעין\u0004 בלבד \u0003משתלחין ואין זבין וטמאי מתים משתלחין, ואיזה זה — פסח הבא בטומאה.\u0004","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן]\u0006 שבאמת כך יש לדקדק בפסוק, ואף זבים כטמאי מתים מותר להם להשתתף בפסח הבא בטומאה, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003פסח הבא בטומאה לא יאכלו ממנו זבים וזבות נדות ויולדות\u0004 שכולם טומאתם מעין טומאת זיבה, \u0003ואם אכלו — פטורין.\u0004 נמצא לפי זה שאי אפשר ללמוד מפסוק זה כדיוקו של ריש לקיש.","\u0003אלא אמר אביי: לעולם\u0004 יש ללמוד \u0003מקרא קמא\u0004 \u0005[מן הפסוק הראשון]\u0006 שהביא ר' יוחנן \"איש איש כי יהיה טמא לנפש\". וכך יש ללמוד: \u0003אם כן\u0004 שבא הכתוב ללמדנו שרק לאיש פרטי, ולא לציבור, יש תקנה בפסח שני, \u0003ניכתוב רחמנא\u0004 \u0005[שיכתוב המקרא]:\u0006 \u0003\"איש איש כי יהיה טמא\",\u0004 והמילה \u0003\"לנפש\" למה לי?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003האי\u0004 \u0005[אותה]\u0006 מילה \u0003\"לנפש\" להכי הוא דאתא\u0004 \u0005[ל\u0006דבר \u0005זה הוא בא]\u0006 ללמד: \u0003טמא מת הוא\u0004 ש\u0003נדחה לפסח שני, אבל שאר טמאין לא\u0004 נדחים לפסח שני. אולם אין ללמוד כן, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 היפך הדבר: \u0003יכול לא יהו עושין פסח שני אלא טמאי מתים\u0004 או מי \u0003שהיה בדרך רחוקה, זבין ומצורעין ובעלי נדות\u0004 שהיו טמאים לפסח ראשון ונטהרו בפסח שני \u0003מניין\u0004 שאף הם עושים פסח שני? \u0003תלמוד לומר: \"איש איש\"\u0004 לרבות כל איש ואיש ובכלל זה אלו, ואם כן \u0003\"לנפש\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003למה לי?\u0004 שלכאורה אינו מלמד כלום!","\u0003אלא הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003איש\u0004 פרטי או בודדים \u0003נדחה לפסח שני ואין\u0004 רוב \u0003ציבור\u0004 כשהוא טמא \u0003נדחה לפסח שני, אלא עבדי\u0004 \u0005[עושים]\u0006 את הפסח כולם \u0003בטומאה, וכי עבדי\u0004 \u0005[וכאשר עושים]\u0006 ה\u0003ציבור בטומאה\u0004 הרי זה דוקא כשהיה הציבור \u0003טמא\u0004 בטומאת \u0003מת\u0004 כאמור \"טמא לנפש\", \u0003אבל שאר\u0004 סוגי \u0003טומאות לא עבדי\u0004 \u0005[אינם עושים]\u0006 בטומאה אפילו היה רוב הציבור טמא.","כיון שהבאנו מן המקראות העוסקים בשילוח הטמאים מן המחנה, דנים בכמה הלכות השייכות לכך. \u0003אמר רב חסדא: מצורע\u0004 שדינו להיות משולח מחוץ לכל המחנות, אף ממחנה ישראל, \u0003שנכנס לפנים ממחיצתו\u0004 (למקום שאסור לו להיכנס אליו) בכל זאת \u0003פטור\u0004 מעונש מלקות. כי אמנם נאמר בטמאים \"מזכר עד נקבה תשלחו, אל מחוץ למחנה תשלחום ולא יטמאו את מחניהם אשר אני שוכן בתוכם\" (במדבר ה, ג), ומכאן למדים שהטמא הנכנס למחנה לוקה על שעבר על מצות לא תעשה של \"לא יטמאו\". מכל מקום המצורע פטור, שכן \u0003נאמר\u0004 בו: \u0003\"\u0004כל ימי אשר הנגע בו יטמא טמא הוא \u0003בדד ישב מחוץ למחנה מושבו\"\u0004 (ויקרא יג, מו),","וכך נדרשים הדברים: \u0003\"בדד ישב\" — לבדו ישב\u0004 גם לא בחברת טמאים אחרים, \u0003\"מחוץ למחנה מושבו\" הכתוב נתקו לעשה\u0004 כלומר, הכתוב קבע שיש גם צד חיובי במעשה שילוחו, ועל ידי כך ניתק את תוקפה הגמור של מצות לא תעשה שיש בו, וכל איסור לא תעשה שנתקו הכתוב לעשה — אין לוקים עליו.","\u0003איתיביה\u0004 \u0005[הקשה לו],\u0006 שנינו: \u0003מצורע\u0004 שאסור להיכנס אף למחנה ישראל ו\u0003נכנס לפנים ממחיצתו\u0004 — דינו שלוקה \u0003בארבעים\u0004 ככל העובר על מצות לא תעשה שבתורה. \u0003זבין וזבות שנכנסו לפנים ממחיצתן\u0004 שאסור להם להיכנס למחנה הלויים — \u0003בארבעים. וטמא מת מותר ליכנס\u0004 אפילו \u0003למחנה לויה\u0004 שהיה בזמן המשכן, שכנגדו בארץ ישראל הוא הר הבית.","\u0003ולא טמא מת בלבד אמרו\u0004 שמותר לו להיכנס לשם, \u0003אלא אפילו מת עצמו\u0004 אין איסור להכניסו למחנה לויה, \u0003שנאמר: \"ויקח משה את עצמות יוסף עמו\"\u0004 (שמות יג, יט), ואנו מדייקים: \u0003\"עמו\"\u0004 משמע \u0003במחיצתו\u0004 כלומר, שארונו של יוסף היה מצוי באותו מקום בו התגורר משה. והרי משה לוי היה ומקום מושבו במחנה הלויים, משמע שאפשר להכניס מת אפילו למחנה הלויים. ומכל מקום למדנו שמצורע לוקה בכניסתו!","ומשיבים: \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא אחרת\u0005]:\u0006 \u0003\"בדד ישב\" המצורע — לבדו ישב,\u0004 כוונתו \u0003שלא יהו טמאים אחרים\u0004 כגון זבים וטמאי מתים \u0003יושבין עמו,\u0004 ועוד אמרו: \u0003יכול יהו זבין וטמאי מתים משתלחין למחנה אחת\u0004 ויהיו באותו מקום עצמו — \u0003תלמוד לומר:\u0004 \"מזכר עד נקבה תשלחו אל מחוץ למחנה תשלחום \u0003ולא יטמאו את מחניהם\u0004 אשר אני שוכן בתוכם\" (במדבר ה, ג), משמע שיש לטמאים מחנות שונים, \u0003ליתן מחנה לזה ומחנה לזה\u0004 אלו \u0003דברי ר' יהודה.\u0004 הרי שלדבריו ישנם שלושה סוגי מחנות: למצורע, לזב ולטמא מת.","\u0003ר' שמעון אומר: אינו צריך\u0004 ללמוד מלשון ריבוי זו, אלא \u0003הרי הוא אומר: \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\"\u0004 (במדבר ה, ב), ויש כאן יתור לשון, ש\u0003יאמר טמאי מת ואל יאמר טמאי זב, ואני אומר\u0004 ולומד בקל וחומר: אם \u0003טמאי מתים משתלחין, זבין לא כל שכן\u0004 שישתלחו ואם כן \u0003למה נאמר זב — ליתן לו מחנה שניה,\u0004 ללמדנו שצריכים להחמיר בו ולהרחיק אותו מחנה נוסף.","ועוד: \u0003יאמר זב ואל יאמר מצורע, ואני אומר\u0004 קל וחומר מעצמי: אם \u0003זבין משתלחין, מצורעין לא כל שכן? למה נאמר מצורע — ליתן לו מחנה שלישית, כשהוא אומר\u0004 במצורע \u0003\"בדד ישב\" — הכתוב נתקו לעשה,\u0004 ללמד שהמצורע שנכנס לפנים מן המחנה שלו אינו לוקה על שעבר במצות לא תעשה, והוא כדברי רב חסדא.","ושואלים על שיטתו של ר' שמעון: כאן בדיון זה רואים כי ברור לו שהזב חמור מטמא מת והמצורע חמור מזב, אבל \u0003מאי חומריה\u0004 \u0005[מה חומרתו]\u0006 של \u0003זב מטמא מת?\u0004 ומסבירים: \u0003שכן טומאה\u0004 של הזב \u0003יוצאה עליו מגופו\u0004 ואינה באה לו מדבר אחר כטמא מת, אולם \u0003אדרבה\u0004 אפשר לומר ש\u0003טמא מת חמור, שכן טעון הזאה\u0004 של מי חטאת \u0003שלישי ושביעי\u0004 לפני שיטהר, מה שאין כן בזב, שאין צריך הזאה כזו אף שגם טומאתו בת שבעה ימים.","ומשיבים: לכן \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לא רק \u0003\"טמא\"\u0004 לנפש אלא גם \u0003\"וכל טמא\",\u0004 ובא ביטוי זה \u0003לרבות טמא שרץ,\u0004 שאף הוא משתלח מן המחנה כטמא מת וברור כי \u0003זב חמור מטמא שרץ.\u0004","ושואלים: \u0003ומאי חומריה\u0004 \u0005[ומה חומרתו]\u0006 של טמא זב? ומשיבים: \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 שטומאתו באה מגופו, שלא כטומאת הנטמא משרץ. אולם \u0003אדרבה\u0004 אפשר לומר שהנטמא ב\u0003שרץ חמור, שכן מטמא באונס.\u0004 שהזב אינו מטמא בזיבה אלא אם כן נתברר שלא ראה את הזיבה מחמת אונס מחלה או אונס אחר, ואילו בנטמא בשרץ — אין בודקים אם נטמא לרצונו או שלא לרצונו! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בישוב שאלה זו:"],["\u0003כי האי גוונא\u0004 \u0005[כעין זה]\u0006 כלומר, אם משוים את הדברים באופן זה — \u0003זב נמי טמויי מטמי\u0004 \u0005[גם כן מטמא]\u0006 \u0003באונס\u0004 באופן שביאר \u0003רב הונא.\u0004 ש\u0003אמר רב הונא: ראיה ראשונה של זב מטמאה באונס,\u0004 שכדי שיחשב אדם לזב על כל חומרותיו צריך שיראה זיבה לפחות שתי פעמים, ואם ראה פעם אחת בלבד — הוא טמא טומאה קלה עד הערב, כבעל קרי. ובפעם הראשונה הזו מיטמא גם באונס, ואין בודקים אם היה פה גורם נוסף.","ועוד שואלים: \u0003מאי חומריה\u0004 \u0005[מה חומרתו]\u0006 של \u0003מצורע מזב? שכן\u0004 מצורע \u0003טעון פריעה ופרימה,\u0004 שמצורע מוחלט צריך לגדל שערו ולפרום את בגדיו, וגם \u0003אסור בתשמיש המטה,\u0004 מה שאין כן בזב. אולם \u0003אדרבה\u0004 יש מקום לומר כי \u0003זב חמור\u0004 יותר, \u0003שכן\u0004 הזב \u0003מטמא משכב ומושב\u0004 שמהווים לו משען גם אם אינו נוגע בגופם, ועוד \u0003שמטמא כלי חרס בהיסט,\u0004 שאם הוא מזיז כלי חרס, ואפילו כשהוא באופן שאינו מטמאו במגעו וכגון שנגע בכלי מבחוץ (וכלי חרס אינו מקבל טומאה אלא מתוכו) ואפילו כשלא נגע בכלי עצמו — נטמא.","ומשיבים: \u0003אמר קרא\u0004 \u0005[המקרא]\u0006 לא רק \u0003\"זב\",\u0004 אלא אמר \u0003\"וכל זב\",\u0004 ולשון הריבוי \"כל\" באה \u0003לרבות בעל קרי,\u0004 שטומאתו היא מסוג טומאת הזב, וברור ש\u0003מצורע חמור מבעל קרי.\u0004 ונלמד בקל וחומר שאם בעל קרי הקל טעון שילוח מחוץ למחנה, מצורע החמור לא כל שכן.","שואלים: \u0003ומאי חומריה\u0004 \u0005[ומה חומרתו]\u0006 של המצורע — \u0003כדאמרן\u0004 \u0005[כפי שאמרנו]\u0006 שטעון פריעה ופרימה ואסור בתשמיש המיטה. אך יש להקשות: \u0003אדרבה,\u0004 לכאורה אפשר לומר גם ש\u0003בעל קרי חמור\u0004 שכן \u0003מטמא במשהו,\u0004 שלא נתנה התורה שיעור לטומאתו ומטמא אפילו בכלשהו, ואילו לצרעת יש שיעור מסוים, שבפחות ממנו אינו טמא!","ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' נתן. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' נתן אומר משום ר' ישמעאל: זב\u0004 כדי שיהיה טמא \u0003צריך\u0004 שתהא שיעור הזיבה \u0003כחתימת\u0004 (סתימת) \u0003פי האמה\u0004 (אבר המין הזכרי) \u0003ולא הודו לו חכמים.\u0004 הרי שבכל אופן לדברי ר' נתן אף בזיבה יש שיעור מסויים. \u0003ואיתקש ליה\u0004 \u0005[והושוו לו]\u0006 \u0003בעל קרי לזב\u0004 שאף בטומאת קרי יש שיעור כמו בזב, הרי שאין זו פירכה וממילא קל וחומר זה נותר בעינו, ולפיו נמצא שמצורע חמור מבעל קרי.","ושואלים: לשונות אלה \"כל זב\" ו\"כל טמא לנפש\" באים ללמד ולרבות, \u0003\"וכל צרוע\" למה לי?\u0004 מה בא \"וכל\" זה להוסיף? ומשיבים: \u0003איידי\u0004 \u0005[על ידי,\u0006 משום\u0005]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"כל זב\", כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003\"כל צרוע\",\u0004 משום שיגרת הלשון.","ושואלים לגוף מדרש הלכה זו על שיטת \u0003ר' יהודה:\u0004 הלוא \u0003שפיר קאמר\u0004 \u0005[יפה אמר]\u0006 \u0003ר' שמעון,\u0004 שלמד את דבר שלושת המחנות לשלושת סוגי הטומאות מהפסוק \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\", ומה יש בפי ר' יהודה להשיב?","ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[\u0006פסוק \u0005זה נחוץ לו\u0006 למה \u0005ששנויה\u0006 בברייתא אחרת\u0005],\u0006 \u0003ר' אליעזר אומר: יכול דחקו זבין ומצורעין ונכנסו לעזרה\u0004 שבמקדש \u0003בפסח הבא בטומאה\u0004 של רוב העם למת, \u0003יכול יהו חייבין\u0004 משום כניסת טמאים למקום הקודש, שהרי להם לא הותרה כניסה, \u0003תלמוד לומר: \"וישלחו מן המחנה כל צרוע וכל זב וכל טמא לנפש\"\u0004 (במדבר ה, ב), ללמדנו: \u0003בשעה שטמאי מתים משתלחין — זבין ומצורעין משתלחין\u0004 וחייבים כרת על שהייתם שם, אבל כאשר \u0003אין טמאי מתים משתלחין\u0004 כשרוב הציבור טמאים — \u0003אין זבין ומצורעין משתלחין,\u0004 ואינם חייבים כרת על כך.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 קודם לכן: \u0003\"זב\", \"וכל זב\"\u0004 — בא \u0003לרבות בעל קרי.\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 לימוד זה \u0003לר' יוחנן.\u0004 ש\u0003אמר ר' יוחנן: מחילות\u0004 שמתחת למקדש \u0003לא נתקדשו\u0004 בקדושת מקדש, וכן נאמר ש\u0003בעל קרי משתלח חוץ לשתי מחנות\u0004 כשם שמשתלח הזב, ודרשה שהזכרנו מסייעת לר' יוחנן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו במשנה: \u0003בעל קרי\u0004 דינו \u0003כמגע\u0004 הטהור ב\u0003שרץ, מאי לאו\u0004 \u0005[האם לא\u0006 הכוונה\u0005]\u0006 \u0003למחנותם,\u0004 שלמקום שמשלחין את טמא השרץ משלחין גם את זה? משמע שיכול בעל קרי להיכנס אף למחנה לויה! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003לטומאתם\u0004 שהטמא לשתיהן אינו טמא אלא טומאת ערב.","ותוהים: \u0003לטומאתם?!\u0004 לשם מה צריך להודיענו דבר זה במשנה? \u0003האי\u0004 \u0005[זה,\u0006 טמא שרץ\u0005]\u0006 \u0003טומאת ערב כתיב ביה\u0004 \u0005[כתובה בו]\u0006 במפורש, שהוא טמא ביום שנטמא עד הערב ויטבול ויטהר, \u0003והאי\u0004 \u0005[וזה,\u0006 בעל קרי\u0005]\u0006 \u0003טומאת ערב כתיב ביה\u0004 \u0005[כתובה בו]\u0006 במפורש, שנאמר: \"ואיש כי תצא ממנו שכבת זרע ורחץ במים את כל בשרו וטמא עד הערב\" (ויקרא טו, טז)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003למחנותם,\u0004 שדבר זה לא נתפרש במקרא!","ודוחים: \u0003לא, לעולם\u0004 אפשר לומר שההשוואה היא אכן \u0003לטומאתם, והא קמשמע לן\u0004 \u0005[ו\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003בעל קרי\u0004 דינו \u0003כמגע שרץ\u0004 לענין אחר: \u0003מה מגע שרץ מטמא באונס\u0004 שגם אם נגע בשרץ שלא ברצונו — הריהו טמא, \u0003אף בעל קרי מטמא באונס\u0004 שגם אם ראה קרי לאונסו — הריהו טמא, ואין דינו לענין זה כזב.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006"],["בהמשך אותה משנה שנינו: \u0003בועל נדה\u0004 דינו \u0003כטמא מת\u0004. ונברר: \u0003למאי\u0004 \u0005[למה\u0006 לאיזה ענין\u0005]\u0006 אמרו השוואה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לטומאתם\u0004 ששניהם טמאים שבעה ימים, הרי \u0003האי\u0004 \u0005[זה,\u0006 בועל נדה\u0005]\u0006 \u0003טומאת שבעה כתיב ביה\u0004 \u0005[כתובה בו]\u0006 במקרא במפורש, \u0003והאי\u0004 \u0005[וזה,\u0006 טמא מת\u0005]\u0006 \u0003טומאת שבעה כתיב ביה\u0004 \u0005[כתובה בו]\u0006 במפורש, ואין צורך למשנה להודיענו דבר זה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 לענין \u0003מחנותם\u0004 שלמחנה שטמא מת משתלח אף בועל נדה משתלח. \u0003ומדסיפא\u0004 \u0005[ו\u0006כיון \u0005שסופה\u0006 של המשנה\u0005]\u0006 השוואה זו כוונתה \u0003למחנותם, רישא\u0004 \u0005[תחילתה]\u0006 שהשוותה בעל קרי למגע שרץ \u0003נמי\u0004 \u0005[גם כן]\u0006 להשוותם \u0003למחנותם,\u0004 ולא כפי שאמרנו קודם! ודוחים: \u0003מידי איריא\u0004 \u0005[וכי\u0006 הדבר \u0005שייך]?!\u0006 ומה מחייבנו לומר ששתי ההשוואות הן מענין אחד? \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זו כפי שהיא וזו כפי שהיא]\u0006 וכל קטע עניינו בהשוואה מיוחדת.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מצורע חמור מזב וזב חמור מטמא מת\u0004 לענין המחנות, \u0003יצא בעל קרי שטמא מת חמור ממנו,\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 משמעות הלשון \u0003יצא\u0004 בעל קרי? \u0003לאו\u0004 \u0005[האם לא]\u0006 הכוונה: \u0003יצא מכלל זב ובא לכלל טמא מת, דהא\u0004 \u0005[שהרי]\u0006 בכלל \u0003טמא מת חמור ממנו\u0004 שטומאתו טומאת שבעה ובכל זאת \u0003מותר במחנה לויה,\u0004 ומכאן נלמד שגם בעל קרי מותר במחנה לויה!","ודוחים: \u0003לא,\u0004 הכוונה \u0003יצא\u0004 בעל קרי \u0003ממחנה טמא מת ונכנס למחנה זב\u0004 וטעון שילוח גם ממחנה לויה כמו הזב, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003טמא מת חמור ממנו ומותר במחנה לויה,\u0004 ולכאורה היה עלינו לומר שגם בעל קרי יהיה מותר — בכל זאת \u0003למאי דדמי ליה מדמינן ליה\u0004 \u0005[למה שדומה לו מדמים אותו],\u0006 ובעל קרי דומה מבחינת מהות טומאתו לזב ולא לטמא מת.","\u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב יצחק בר אבדימי:\u0004 \"כי יהיה בך איש אשר לא יהיה טהור מקרה לילה ויצא אל \u0003מחוץ למחנה\u0004 לא יבוא אל המחנה\" (דברים כג, יא), ודרש \u0003\"ויצא אל מחוץ למחנה\"\u0004 — \u0003זו מחנה שכינה, \"לא יבא אל תוך המחנה\"\u0004 — \u0003זו מחנה לויה, מכאן לבעל קרי שיצא חוץ לשתי מחנות.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יצחק לשונה המשניות: משהו אינו כראוי בסגנון ברייתא זו, \u0003אכתי לא עיילתיה אפיקתיה\u0004 \u0005[עדיין לא הכנסת אותו\u0006 כבר \u0005הוצאת אותו]\u0006 כלומר, כיצד אפשר לומר \"לא יבוא אל תוך המחנה\" שכוונתו למחנה לויה? הלוא צריך להוכיח תחילה שהיה במחנה זה, כדי לומר שיצא מתוכו! \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 שעניינה כמעט זהה ונבדלת בניסוח בלבד: \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003לא אפיקתיה עיילתיה\u0004 \u0005[הוצאת אותו\u0006 וכבר \u0005הכנסת אותו]\u0006 כלומר, כיצד אפשר לומר מצד אחד \"לא יבוא אל תוך המחנה\" שהוא מחנה לויה, הרי לא למדנו עדיין שיצא מאותו מחנה! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 תקן הלשון כך: \u0003\"מחוץ למחנה\" — זו מחנה לויה, \"לא יבא אל תוך המחנה\"\u0004 — \u0003זו מחנה שכינה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על דרשה זו\u0005]\u0006 \u0003רבינא: אימא אידי ואידי\u0004 \u0005[אמור שזה וזה]\u0006 בא לענין \u0003מחנה שכינה\u0004 שחייב לצאת מתוכו, ואסור לו להיכנס אליו, וכפל הדברים ללמד \u0003לעבור עליו\u0004 במצות \u0003עשה\u0004 של יציאה, \u0003ולא תעשה\u0004 של איסור כניסה! ודוחים: \u0003אם כן לימא קרא\u0004 \u0005[\u0006ש\u0005יאמר המקרא]\u0006 רק \u0003\"ויצא אל מחוץ למחנה ולא יבא אל תוך\"\u0004 או \"אל תוכו\", חזרה נוספת על המלה \u0003\"המחנה\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003ליתן לו מחנה אחרת,\u0004 שמדובר כאן לא באותו מחנה שיצא ממנו אלא במחנה אחר.","שנינו במשנה ש\u0003מיחוי קרביו\u0004 של הפסח דוחה את השבת. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מיחוי קרביו? רב הונא אמר: שמנקבן בסכין\u0004 כדי שיצא הפרש מתוכם. \u0003רב חייא בר רב אמר:\u0004 הכוונה היא \u0003שירקא דמעייא דנפקא אגב דוחקא דסכינא\u0004 \u0005[ליחה שבמעיים שיוצאת על ידי דחיקת הסכין]\u0006 עליה, שאם ישאירו לכלוך זה בתוך המעיים יתקלקל ויסריח כל הקרבן.","\u0003אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה טעמו]\u0006 של \u0003חייא בר רב\u0004 בהסברו זה? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ורעו כבשים כדברם \u0003וחרבות מחים גרים יאכלו\"\u0004 (ישעיה ה יז), \u0003מאי משמע\u0004 \u0005[מה משמעו\u0006 של כתוב זה\u0005]\u0006 ומה הקשר שלו לענייננו? \u0003כדמתרגם\u0004 \u0005[כפי שמתרגם]\u0006 \u0003רב יוסף\u0004 פסוק זה \u0003\"ונכסיהן דרשיעיא צדיקיא יחסנון\"\u0004 \u0005[ואת נכסי הרשעים ירשו הצדיקים],\u0006 ומכאן שלשון מחים הוא לשון ביזוי וגנאי, ומתוך כך הגיע חייא בר רב לפרש שמיחוי קרביים הוא הוצאת הדבר המאוס.","כיון שמבואר חלק מפסוק זה מבארים גם את תחילתו. \u0003\"ורעו כבשים כדברם\", אמר מנשיא בר ירמיה אמר רב: כמדובר בם\u0004 לאמור כפי שהבטיח הנביא. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 מובן\u0005]\u0006 לאיזו הבטחה התכוון כשאמר \u0003כמדובר בם? אמר אביי:\u0004 הוא שנאמר \u0003\"וחרבות מחים גרים יאכלו\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אין לומר כן; \u0003בשלמא אי כתיב\u0004 \u0005[נניח אם היה כתוב]\u0006 \u0003\"חרבות\u0004 מחים \u0003\"\u0004אפשר היה לומר \u0003כדקאמרת\u0004 \u0005[כפי שאמרת]\u0006 ופירשת, אבל \u0003השתא דכתיב\u0004 \u0005[עכשיו שכתוב]\u0006 \u0003\"וחרבות\",\u0004 משמע \u0003מילתא אחריתי קאמר\u0004 \u0005[דבר אחר אמר]\u0006 ויש כאן שתי נבואות נבדלות.","\u0003אלא אמר רבא:\u0004 יש לפרש זאת כדברי \u0003רב חננאל אמר רב,\u0004 ש\u0003אמר רב חננאל אמר רב: עתידין צדיקים שיחיו את המתים. כתיב הכא\u0004 \u0005[כתוב כאן]:\u0006 \u0003\"ורעו כבשים כדברם\"\u0004 כבשים אלה כינוי הם לצדיקים, \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 גם במקום אחר לשון רעיה: \u0003\"\u0004רעה עמך בשיבטך צאן נחלתך שוכני לבדד יער בתוך כרמל \u0003ירעו בשן וגלעד כימי עולם\"\u0004 (מיכה ז, יד),","\u0003\"בשן\"\u0004 — זה רמז לנביא \u0003אלישע הבא מן הבשן.\u0004 ומנין יודעים אנו שאלישע בא מן הבשן, \u0003שנאמר: \"\u0004יואל הראש ושפם המשנה \u0003ויעני ושפט בבשן\"\u0004 (דברי הימים א' ה, יב), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שם אביו של אלישע במקום אחר: \u0003\"פה אלישע בן שפט אשר יצק מים על ידי אליהו\"\u0004 (מלכים ב' ג יא). \u0003\"גלעד\" זה\u0004 רמז ל\u0003אליהו, שנאמר: \"ויאמר אליהו התשבי מתושבי גלעד\"\u0004 (מלכים א' יז א). ומתוך דמיון הלשון בפסוקים נלמד גזירה שווה שיהיו הצדיקים לעתיד כאליהו ואלישע שהחיו את המתים.","כענין זה ממקור אחר, \u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: עתידים צדיקים שיחיו מתים, שנאמר: \"עד ישבו זקנים וזקנות ברחבות ירושלים ואיש משענתו בידו מרב ימים\"\u0004 (זכריה ח, ד), וענינה של משענת זו — כפי שנאמר בדברי אלישע לגיחזי בבואו להחיות את בן השונמית המת: \u0003\"ושמת משענתי על פני הנער\"\u0004 (מלכים ב' ד, כט).","כיון שדובר בתחיית המתים ובחיים לעתיד לבוא מביאים עוד בענין זה. \u0003עולא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 בין שני מקראות, נאמר במקרא אחד: \u0003\"בלע המות לנצח\u0004 ומחה ה' אלקים דמעה מעל כל פנים וחרפת עמו יסיר מעל כל הארץ כי ה' דיבר\u0003\"\u0004 (ישעיה כה, ח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"\u0004לא יהיה משם עוד עול ימים וזקן אשר לא ימלא את ימיו, \u0003כי הנער בן מאה שנה ימות\"\u0004 (ישעיה סה, כ), הרי שבכל זאת לא יבולע לגמרי המוות! והשיב: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן בישראל\u0004 שלא ימותו כלל, \u0003כאן בגוים\u0004 שרק יאריכו ימיהם מאד. ושואלים: \u0003וגוים מאי בעו התם\u0004 \u0005[מה הם צריכים שם]\u0006 ומה מקומם לעתיד לבוא? ומשיבים: \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועמדו זרים ורעו צאנכם ובני נכר אכריכם וכרמיכם\"\u0004 (ישעיה סא, ה).","\u0003רב חסדא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וחפרה הלבנה ובושה החמה\u0004 כי מלך ה' צבאות בהר ציון ובירושלים ונגד זקניו כבוד\u0003\"\u0004 (ישעיה כד, כג), משמע שלעתיד לא יהא כלל אור שמש וירח, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"והיה אור הלבנה כאור החמה ואור החמה יהיה שבעתים כאור שבעת הימים\u0004 ביום חבוש ה' את שבר עמו ומחץ מכתו ירפא\u0003\"\u0004 (ישעיה ל, כו), משמע שיאירו לבנה וחמה, ואף אורם יגדל! ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003כאן\u0004 שחפרה הלבנה לגמרי מזיו השכינה, הרי זה \u0003לעולם הבא\u0004 שהוא עולם שונה לחלוטין, \u0003כאן\u0004 שיגדל אורה \u0003לימות המשיח.\u0004","ושואלים: ולשיטת \u0003שמואל\u0004 ש\u0003אמר: אין בין העולם הזה לימות המשיח אלא שיעבוד מלכיות בלבד,\u0004 אבל בשאר הדברים ובכלל זה אור החמה עולם כמנהגו נוהג, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בהסבר הדברים? ומשיבים; יש לומר: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 יתקיימו \u0003לעולם הבא, ולא קשיא\u0004 \u0005[קשה];\u0006 \u0003כאן\u0004 שחפרה הלבנה לגמרי \u0003במחנה שכינה, כאן\u0004 שיהיה אורה פי כמה — \u0003במחנה צדיקים.\u0004","ובדומה לכך \u0003רבא רמי\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005],\u0006 נאמר: \u0003\"אני אמית ואחיה\" וכתיב\u0004 \"מחצתי ואני ארפא\" (דברים לב, לט), \u0003השתא אחויי מחיי\u0004 \u0005[עכשיו\u0006 שנאמר שהוא \u0005מחיה\u0006 את המתים\u0005],\u0006 \u0003מרפא\u0004 את החיים \u0003לא כל שכן\u0004 שיכול הוא לרפא, ואין כל הוספה בביטוי שני על הראשון! \u0003אלא\u0004 פסוק זה בא להבהיר את תוכן הדבר, \u0003אמר הקדוש ברוך הוא מה שאני ממית\u0004 כלומר, אותם אנשים שאני ממית \u0003אני מחיה, כמו\u0004 שאת האנשים שאני \u0003מחצתי אני ארפא,\u0004 שמדבר באותם אנשים ולא כפי שהיה מקום להבין גם אחרת.","ובדומה לזה בברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"אני אמית ואחיה\" יכול\u0004 שהכוונה היא \u0003מיתה\u0004 באדם \u0003אחד וחיים\u0004 (לידה) \u0003באחד, כדרך שהעולם נוהג, תלמוד לומר \"מחצתי ואני ארפא\", מה מכה ורפואה\u0004 האמורה כאן מדברת בודאי באדם \u0003אחד, אף מיתה וחיים באחד. מכאן תשובה לאומרים אין תחיית המתים מן התורה,\u0004 שהרי נאמר פסוק זה במפורש בתורה. \u0003דבר אחר\u0004 בפירוש הפסוק: \u0003בתחלה מה שאני ממית אני מחיה\u0004 שיחיו המתים ויקומו במומם שמתו בו, \u0003והדר\u0004 \u0005[ואחר כך]\u0006 \u0003מה שמחצתי ואני ארפא,\u0004 כלומר שיתרפאו ממומיהם אחר כך."],["שנינו במשנה כי כשחל ערב פסח להיות בשבת \u0003הקטר חלביו\u0004 של קרבן הפסח דוחה את השבת. בענין זה מביאים הערה מן התוספתא. \u0003תניא\u0004 \u0005[שנויה בתוספתא]\u0006 \u0003אמר ר' שמעון: בא וראה כמה חביבה מצוה בשעתה, שהרי הקטר חלבים ואברים ופדרים\u0004 (החלב הפנימי) \u0003כשרים כל הלילה,\u0004 ואפשר היה להמתין עד יציאת השבת ולהקטירם בלילה, ובכל זאת \u0003אין ממתינים להם עד שתחשך\u0004 אלא מקטירים אותם מיד אף שהדבר כרוך בחילול שבת.","שנינו עוד במשנה כי \u0003הרכבתו והבאתו\u0004 וחתיכת יבלתו של הפסח אינם דוחים את השבת. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממשנה אחרת במסכת עירובין, ששנינו בה: \u0003חותכין\u0004 בשבת \u0003יבלת\u0004 של בהמת הקרבן \u0003במקדש אבל לא במדינה\u0004 (בכל מקום חוץ למקדש), \u0003ואם\u0004 לחתוך \u0003בכלי — כאן וכאן אסור.\u0004 הרי ברור מכאן שבמקדש מותר לחתוך יבלת בשבת!","בתירוץ קושיה זו נחלקו שני אמוראים, \u0003ר' אלעזר ור' יוסי בר חנינא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אידי ואידי\u0004 \u0005[זו וזו],\u0006 גם במסכת פסחים וגם במסכת עירובין מדובר כשחותך את היבלת \u0003ביד,\u0004 אלא \u0003הא\u0004 \u0005[זה\u0006 שאסור\u0005]\u0006 הוא ביבלת לחה שהיא כבשר ואיסורה הוא משום שבות, וכיון שיכול היה לעשות כן לפני השבת גזרו בו אף על פי שאין שבות במקדש. \u0003הא\u0004 \u0005[זה\u0006 שמותר\u0005]\u0006 \u0003ביבשה\u0004 הנפרכת מעצמה ואין בה אפילו משום שבות. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003בלחה, ולא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שמותר במקדש — שמורידה \u0003ביד\u0004 ואין בכך אלא משום שבות והתירוה במקדש, \u0003הא\u0004 \u0005[זו\u0006 שאסור\u0005] —\u0006 \u0003בכלי,\u0004 שהיא מלאכת שבת גמורה ואסורה בכל מקום.","ושואלים: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]\u0006 ש\u0003אמר הא\u0004 \u0005[זו]\u0006 \u0003ביד הא\u0004 \u0005[זו]\u0006 \u0003בכלי מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 כחבירו: \u0003אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003ביד ולא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003בלחה הא\u0004 \u0005[זו]\u0006 \u0003ביבשה? אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 יבלת \u0003יבשה מפרך פריכא\u0004 \u0005[נפרכת\u0006 מעצמה\u0005]\u0006 ולא היה צורך ללמדנו שמותר, אלא ודאי מדובר ביבלת לחה, וההבדל הוא בין הסרה ביד להסרה בכלי.","ועל הדעה האחרת שואלים: \u0003ולמאן\u0004 \u0005[ול\u0006שיטת \u0005מי]\u0006 ש\u0003אמר אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003ביד ולא קשיא\u0004 \u0005[קשה]\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 \u0003בלחה הא\u0004 \u0005[זו]\u0006 \u0003ביבשה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר אידי ואידי\u0004 \u0005[זו וזו]\u0006 \u0003בלחה ולא קשיא\u0004 \u0005[קשה];\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003ביד והא\u0004 \u0005[וזו]\u0006 \u0003בכלי\u0004 ולא תירץ כתירוץ שני? \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003כלי — הא קתני התם\u0004 \u0005[הרי שנינו שם]\u0006 באותה משנה \u0003\"אם בכלי — כאן וכאן\u0004 גם במדינה וגם במקדש — \u0003אסור\",\u0004 ומה טעם להוסיף ולשנות בשנית אותו דבר עצמו כאן, והרי כבר נכתב שם במפורש במשנה!","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 כיצד מסביר הוא לפי דבריו את כפל הדברים במשנה? \u0003הא דקתני\u0004 \u0005[זה ששנינו]\u0006 \u0003כלי הכא\u0004 \u0005[כאן]\u0006 יש בו צד חידוש, כי \u0003פלוגתא\u0004 \u0005[מחלוקתם]\u0006 של \u0003ר' אליעזר ור' יהושע אתא לאשמועינן\u0004 \u0005[באה להשמיענו]\u0006 שהרי לפי משנתנו מתיר ר' אליעזר לחתוך יבלת לחה אף בכלי כדי להכשיר את שה הפסח.","בתוך הויכוח של ר' אליעזר ור' יהושע במשנה \u0003אמר ר' אליעזר ומה אם שחיטה וכו'\u0004 שאין להוכיח מיום טוב לקרבן פסח, משום שאין להוכיח מדבר של רשות כהכנת אוכל ליום טוב לדבר מצוה (קרבן). ומעירים: כי \u0003ר' יהושע\u0004 החולק על כך הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 כי \u0003שמחת יום טוב נמי\u0004 \u0005[גם כן]\u0006 \u0003מצוה היא,\u0004 ולכן כל מה ששייך לעונג יום טוב הוא צורך מצוה, כמוהו כהקרבת הקרבנות.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 שנחלקו שני תנאים אלה במצוה זו. \u0003ר' אליעזר אומר: אין לו לאדם ביום טוב אלא\u0004 שיבחר \u0003או אוכל ושותה או יושב ושונה\u0004 כל היום כולו, אבל אין מצוה מסויימת לאכול ביום טוב. ואילו \u0003ר' יהושע אומר: חלקהו, חציו לאכילה ושתיה וחציו לבית המדרש,\u0004 שהוא סבור כי אכילה ושתיה הן מחובת היום.","\u0003ואמר ר' יוחנן:\u0004 בביאור דבריהם: \u0003ושניהם מקרא אחד דרשו\u0004 כלומר, שניהם תירצו בצורות שונות אותה בעיה עצמה, \u0003כתוב אחד אומר: \"עצרת לה' אלהיך\u0004 לא תעשה מלאכה\u0003\"\u0004 (דברים טז, ח), משמע שהוא יום המקודש לעבודת ה', \u0003וכתוב אחד אומר: \"עצרת תהיה לכם\u0004 כל מלאכת עבודה לא תעשו\u0003\"\u0004 (במדבר כט, לה), שהוא עצרת שמחה לקהל ישראל. \u0003ר' אליעזר סבר\u0004 כי את שני הכתובים יש להבין כברירה: \u0003או כולו לה' או כולו לכם. ור' יהושע סבר\u0004 שאפשר לקיים את שני המקראות, \u0003חלקהו\u0004 את היום \u0003חציו לה' וחציו לכם.\u0004","\u0003עב\"ם סימן. אמר ר' אלעזר: הכל מודים בעצרת\u0004 (בחג השבועות) \u0003דבעינן נמי\u0004 \u0005[שצריכים גם כן]\u0006 שתהיה \u0003\"לכם\",\u0004 שמצוה לאכול ולשתות ולשמוח בו. \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — \u0003יום שניתנה בו תורה הוא\u0004 וצריך להראות שמחה על שניתנה תורה לישראל. \u0003אמר רבה: הכל מודים בשבת דבעינן נמי\u0004 \u0005[שצריכים גם כן]\u0006 שתהיה \u0003\"לכם\", מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005] —\u0006 שכן נאמר: \u0003\"וקראת לשבת ענג\u0004 לקדוש ה' מכובד\u0003\"\u0004 (ישעיה נח, יג). \u0003אמר רב יוסף: הכל מודים בפורים דבעינן נמי\u0004 \u0005[שצריכים גם כן]\u0006 שיהיה \u0003\"לכם\". מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 — שכן נאמר: \u0003\"\u0004לעשות אותם \u0003ימי משתה ושמחה\"\u0004 (אסתר ט, כב).","מסופר: \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא כולה שתא הוה יתיב בתעניתא\u0004 \u0005[כל השנה היה יושב בתענית],\u0006 שלא היה אוכל כל היום אלא מעט בערב, \u0003לבר מעצרתא ופוריא ומעלי יומא דכיפורי\u0004 \u0005[חוץ מעצרת,\u0006 שבועות, \u0005ופורים וערב יום הכיפורים].\u0006 וטעמו: \u0003עצרת — יום שניתנה בו תורה\u0004 ומצוה להראות שהוא שמח בה, \u0003פוריא\u0004 \u0005[פורים] —\u0006 \u0003\"ימי משתה ושמחה\" כתיב\u0004 \u0005[נאמר]\u0006 בהם, \u0003מעלי יומא דכיפורי\u0004 \u0005[ערב יום הכיפורים]\u0006 על פי דרשתו של \u0003חייא בר רב מדפתי,\u0004 שתמה על הכתוב \u0003\"ועניתם את נפשתיכם בתשעה לחדש\u0004 בערב, מערב עד ערב תשבתו שבתכם\u0003\"\u0004 (ויקרא כג, לב), \u0003וכי בתשעה\u0004 בתשרי \u0003הם מתענין? והלא בעשירי\u0004 בו \u0003מתענין! אלא לומר לך\u0004 ברמז: \u0003כל האוכל ושותה בתשעה בו — מעלה עליו הכתוב כאילו מתענה\u0004 גם יום \u0003תשיעי\u0004 וגם יום \u0003עשירי.\u0004","מסופר: \u0003רב יוסף ביומא דעצרתא\u0004 \u0005[ביום השבועות]\u0006 \u0003אמר: עבדי לי עגלא תלתא\u0004 \u0005[עשו לי עגל משולש,\u0006 מובחר\u0005]\u0006 \u0003אמר: אי\u0004 \u0005[אם]\u0006 \u0003לא האי יומא דקא גרים\u0004 \u0005[יום זה\u0006 של חג עצרת, מתן תורה \u0005שגרם\u0006 שיש תורה\u0005] —\u0006 \u0003כמה יוסף איכא בשוקא\u0004 \u0005[יש בשוק]\u0006 ורק משום חשיבות לימוד התורה נעשיתי ראש לישראל, וחייב אני לשמוח במיוחד ביום זה.","סיפור דומה במקצת מסופר על \u0003רב ששת; כל תלתין יומין מהדר ליה תלמודיה\u0004 \u0005[שלושים יום היה חוזר על תלמודו]\u0006 שלמד באותם ימים, \u0003ותלי וקאי בעיברא דדשא\u0004 \u0005[והיה עומד ונשען על בריח הדלת]\u0006 \u0003ואמר: חדאי נפשאי, חדאי נפשאי, לך קראי לך תנאי\u0004 \u0005[שמחי נפשי, שמחי נפשי, בשבילך קראתי\u0006 במקרא, \u0005בשבילך שניתי].\u0006 ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]\u0006 שלימוד התורה הוא רק לתועלת נשמתו של הלומד עצמו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: אלמלא תורה\u0004 ולימודה \u0003לא נתקיימו שמים וארץ, שנאמר \"אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי\"\u0004 (ירמיהו לג, כה), שהתורה, שהיא ברית נצחית שלימודה קיים גם ביום וגם בלילה, היא הצדקת קיומו של העולם! ומשיבים: באמת כן הדבר, אלא \u0003מעיקרא כי עביד איניש אדעתא דנפשיה קא עביד\u0004 \u0005[מתחילה כאשר עושה אדם\u0006 מצוה זו, \u0005למען עצמו הוא עושה]\u0006 ובתוך כך באה תועלת לכל העולם.","\u0003אמר רב אשי: ולמאי דקאמר\u0004 \u0005[ולמה שאמר]\u0006 \u0003ר' אליעזר נמי\u0004 \u0005[גם כן]\u0006 כלומר, אפילו על פי שיטתו, שסבר ששמחת \u0003יום טוב רשות\u0004 היא, \u0003אית ליה פירכא\u0004 \u0005[יש לו שבירה]\u0006 יש מקום לשבור את דבריו כך: \u0003ומה יום טוב שהתיר בו מלאכה\u0004 גמורה (שחיטה, בישול ואפיה) שהיא \u0003של רשות\u0004 גמורה לשיטת ר' אליעזר, בכל זאת \u0003לא התיר שבות שעמה,\u0004 ואין אומרים שמשום שהתירו דבר של רשות התירו הכל, קל וחומר \u0003שבת שלא התיר בה אלא מלאכה של מצוה אינו דין שלא תתיר שבות שעמה\u0004 ואף שבות של מצוה לא תהא מותרת, בניגוד לשיטת ר' אליעזר!"],["\u0003ור' אליעזר\u0004 דוחה פירכה זו, כי לדעתו \u0003שבות\u0004 של \u0003מצוה עדיף ליה\u0004 \u0005[עדיפה לו\u0006 בעיניו\u0005],\u0006 שאין ללמוד קל וחומר משבות של רשות שנאסרה ביום טוב לענין שבות שבעשיית מצוה, שמפני חשיבות המצוה יתכן שהתירו שבות זו, אף שלא התירו שבות של רשות.","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003אמר ר' אליעזר: ומה לי אם דחו מכשירי מצוה שלאחר שחיטה את השבת,\u0004 כגון מיחוי הקרביים, שלדעת הכל מותר אף כי כבר \u0003איתעביד ליה\u0004 \u0005[שכבר נעשתה]\u0006 ה\u0003מצוה,\u0004 וכיצד אפשר לומר כי \u0003לא ידחו מכשירי מצוה שלפני שחיטה\u0004 אף הם \u0003את השבת!\u0004","\u0003אמר לו ר' עקיבא\u0004 ש\u0003מה לי\u0004 כלומר, כיצד יכול אתה לעשות השוואה כזו, שכן \u0003אם דחו מכשירי מצוה שלאחר שחיטה את השבת, שהרי\u0004 כבר \u0003דחתה שחיטה את השבת,\u0004 ושבות הנעשית לאחר מכן נעשית לאחר שנדחתה כבר השבת מפני הקרבן, \u0003תאמר ידחו מכשירי מצוה שלפני שחיטה את השבת\u0004 — שהרי \u0003לא דחתה\u0004 עדיין \u0003שחיטה את השבת. דבר אחר,\u0004 נימוק אחר לר' עקיבא: \u0003שמא ימצא זבח פסול\u0004 במום \u0003ונמצא מחלל את השבת למפרע,\u0004 שהרי שחט בשבת ולא קיים מצוה.","נימוק זה דוחה ר' אליעזר: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם חושש אתה לכך — \u0003משחט נמי לא נשחט\u0004 \u0005[לשחוט\u0006 גם כן לא נשחוט\u0005]\u0006 \u0003שמא ימצא זבח פסול ונמצא מחלל את השבת למפרע. אלא\u0004 יש להסביר את מהלך הדברים באופן זה: \u0003הא אמר ליה ברישא\u0004 \u0005[\u0006נימוק \u0005זה\u0006 האחרון \u0005אמר לו\u0006 ר' עקיבא \u0005בתחילה]\u0006 \u0003ופרכיה\u0004 \u0005[ושברו]\u0006 ר' אליעזר כפי שהוכחנו שאין זו ראיה. \u0003והדר אמר ליה הך\u0004 \u0005[ואחר כך אמר לו\u0006 את הנימוק \u0005הזה]\u0006 של \u0003מה לי אם דחו.\u0004","במשנה \u0003השיב ר' עקיבא ואמר\u0004 כתשובה לר' אליעזר שאפשר לעשות קל וחומר הפוך: שתהא השחיטה אסורה על ידי קל וחומר מ\u0003הזאה\u0004 ש\u0003תוכיח\u0004 שהיא אסורה. \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר לו ר' אליעזר: עקיבא, בשחיטה השבתני\u0004 ודחית את דברי בדרך גיחוך ורצית להביא קל וחומר שיש לו פירכה, \u0003בשחיטה תהא מיתתו,\u0004 שכעונש על כך תמות בידי אדם בשחיטה. \u0003אמר לו:\u0004 ר' עקיבא לר' אליעזר: \u0003רבי, אל תכפירני בשעת הדין,\u0004 אל תסתור את ההלכה שבידי בשעה שאנחנו דנים על הדבר, שהרי \u0003כך מקובלני ממך: הזאה שבות היא ואינה דוחה את השבת,\u0004 ולכך אף לשיטתך דברי נכונים וחזור בך ממה שאמרת \"ועליה אני דן\" וכו'.","ושואלים: אם כן, \u0003וכי מאחר\u0004 ש\u0003הוא\u0004 עצמו \u0003אגמריה\u0004 \u0005[לימד אותו]\u0006 הלכה זו שאין הזאה דוחה את השבת \u0003מאי טעמא קא הדר ביה\u0004 \u0005[מה טעם חזר בו]?\u0006 \u0003אמר עולא: ר' אליעזר כי אגמריה\u0004 \u0005[כאשר לימד אותו]\u0006 לר' עקיבא \u0003הזאה\u0004 של \u0003תרומה אגמריה\u0004 \u0005[למד אותו]\u0006 כלומר, שאין מזים על הטמא בשבת כדי להכשירו לאכול בתרומה, וטעמו של דבר — ש\u0003תרומה גופה\u0004 אפילו הפרשת התרומה \u0003לא דחיא\u0004 \u0005[דוחה]\u0006 \u0003שבת.\u0004 אבל לא לימדו בענין הזאה לקרבן.","ומעירים: \u0003ר' עקיבא נמי\u0004 \u0005[גם כן]\u0006 \u0003כי אותביה\u0004 \u0005[כאשר הקשה לו]\u0006 באמת — מענין \u0003הזאה\u0004 של \u0003תרומה אותביה\u0004 \u0005[הקשה לו].\u0006 וכך יש להבין קושייתו: הרי אכילת תרומה \u0003שהיא מצוה\u0004 ואסור להזות על הטמא בשבת כדי שיוכל לאוכלה רק \u0003משום שבות\u0004 ובכל זאת לא התירוה, ומכאן קל וחומר לשחיטה שהיא מלאכה גמורה ותהא אסורה בשבת! \u0003והוא,\u0004 ר' אליעזר, \u0003סבר: הזאה\u0004 של \u0003פסח קא מותיב ליה\u0004 \u0005[מקשה לו],\u0006 משום כך אמר שאף בהזאה זו חולק הוא.","\u0003מתיב\u0004 \u0005[הקשה]\u0006 \u0003רבה\u0004 על הסבר זה של עולא, מתוך ברייתא אחרת: \u0003השיב ר' עקיבא ואמר: הזאת טמא מת תוכיח\u0004 כ\u0003שחל\u0004 יום \u0003שביעי שלו\u0004 לאחר שנטמא \u0003להיות בשבת, ובערב הפסח שהיא מצוה,\u0004 שהרי אם יזה עליו יטהר ויוכל לאכול מן הפסחים \u0003והיא\u0004 ההזאה \u0003אסורה משום שבות\u0004 בלבד, ובכל זאת \u0003אינה דוחה את השבת.\u0004 ומכאן ברור שהזאה שדיברו בה היתה הזאה לקרבן פסח, ואם כן מובן שר' עקיבא דן בהזאה לצורך קרבן.","\u0003אלא\u0004 יש לחזור מדברי עולא, ולומר \u0003וודאי הזאה\u0004 של \u0003פסח אגמריה\u0004 \u0005[למדו],\u0006 ומה ששאלנו \u0003וכי מאחר דאגמריה\u0004 \u0005[שלמדו]\u0006 ר' אליעזר עצמו \u0003מאי טעמא קא פריך ליה\u0004 \u0005[מה טעם דוחה אותה]\u0006 \u0003ר' אליעזר?\u0004 ומשיבים כי \u0003ר' אליעזר גמריה איתעקר ליה\u0004 \u0005[לימודו נעקר\u0006 ונשכח \u0005ממנו],\u0006 \u0003ואתא\u0004 \u0005ובא\u0006 \u0003ר' עקיבא לאדכורי גמריה\u0004 \u0005[להזכיר את לימודו]\u0006 ולכן עשה לו קל וחומר זה כדי להזכירו מה שהוא עצמו לימדו. ושואלים: אם כן, \u0003ונימא ליה בהדיה\u0004 \u0005[ושיאמר לו במפורש]\u0006 שכך לימדו! ומשיבים: \u0003סבר, לאו אורח ארעא\u0004 \u0005[אין זו דרך ארץ]\u0006 לומר לרבו ששכח, וניסה תחילה להזכירו בדרך עקיפין.","ושואלים לגופם של דברים: ובאמת \u0003הזאה מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא דחיא\u0004 \u0005[דוחה]\u0006 \u0003שבת, מכדי טלטולי בעלמא\u0004 \u0005[הרי טלטול בלבד]\u0006 \u0003הוא\u0004 מהכלי שבידו לגופו של הטמא, ומה טעם לאסור דבר זה בשבת? \u0003תדחי\u0004 \u0005[תדחה]\u0006 את ה\u0003שבת\u0004 לפחות \u0003משום\u0004 מצות \u0003פסח! אמר רבה:\u0004 איסור ההזאה \u0003גזירה\u0004 הוא \u0003שמא יטלנה\u0004 את כלי ההזאה \u0003ויעבירנה ארבע אמות ברשות הרבים,\u0004 ונמצא עובר על איסור מן התורה ממש, ולכן אסרו כל הזאה. וכשיטת רבה בכמה מקומות שאסרו אף מצוות מסויימות מפני חשש זה.","ומקשים: ולפחות לשיטת \u0003ר' אליעזר ניעבריה\u0004 \u0005[נעביר אותם]\u0006 את מי החטאת, אפילו ברשות הרבים! \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אמר ר' אליעזר\u0004 ככלל: \u0003מכשירי מצוה\u0004 כלומר, דברים הנועדים כדי להביא ולסייע לעשיית מצוה אף כשאין בעשייתם מצוה לעצמה, \u0003דוחין את השבת\u0004 אף שהם מלאכה גמורה! \u0003אמרי\u0004 \u0005[אומרים]\u0006 שיש לחלק בדברים: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמכשירי מצוה דוחים את השבת אמורים \u0003היכא דגברא גופיה חזי ורמי חיובא עליה\u0004 \u0005[כאשר האיש עצמו ראוי\u0006 למצוה \u0005ומוטל החיוב עליו],\u0006 \u0003אבל הכא\u0004 \u0005[ כאן],\u0006 \u0003דגברא גופיה לא חזי\u0004 \u0005[שהאיש עצמו אינו ראוי\u0006 לקרבן פסח\u0005]\u0006 שהרי הוא טמא — \u0003לא רמי חיובא עליה\u0004 \u0005[אין מוטל החיוב עליו]\u0006 ואין בכך כל מצוה, ולכך אין לדבר אז על מכשירי מצוה.","\u0003אמר רבה\u0004 בהתאם לשיטה זו לפי \u0003דברי ר' אליעזר: קטן בריא מחמין\u0004 \u0005[מחממים]\u0006 \u0003לו\u0004 מים \u0003חמין להברותו\u0004 כדי שיהיה חזק יותר כדי \u0003למולו בשבת, דהא חזי ליה\u0004 \u0005[שהרי\u0006 עכשיו \u0005ראוי לו]\u0006 להימול, אבל \u0003קטן חולה — אין מחמין\u0004 \u0005[מחממים]\u0006 \u0003לו\u0004 מים \u0003חמין להברותו ולמולו, דהא\u0004 \u0005[שהרי]\u0006 מאחר שהוא חולה כעת \u0003לא חזי ליה\u0004 \u0005[ראוי לו]\u0006 עתה להימול, ומתוך שאין בו עתה משום מצוה אינו אלא מכשירו למצוה, ואין מכשירי מצוה דוחים שבת.","\u0003אמר רבא: ואי\u0004 \u0005[ואם]\u0006 \u0003בריא הוא\u0004 התינוק \u0003למה ליה\u0004 \u0005[לו]\u0006 \u0003חמין להברותו? אלא אמר רבא: הכל חולים הן אצל מילה,\u0004 שכל תינוק זקוק לרחיצה בחמין ולכן מבחינה זו כל התינוקות נחשבים כחולים, ו\u0003אחד קטן בריא ואחד קטן חולה — אין מחמין לו חמין להברותו ולמולו בשבת\u0004 אפילו לדברי ר' אליעזר, \u0003דהא לא חזי\u0004 \u0005[שהרי אינו ראוי].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 לרבה על החילוק שעשה בין ראוי ואינו ראוי, ששנינו: \u0003ערל\u0004 מבוגר \u0003שלא מל\u0004 לפני הפסח \u0003ענוש כרת\u0004 משום שביטל בזדון את מצות הפסח, שהרי לערל אסור לאכול ממנו, אלו \u0003דברי ר' אליעזר. והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003דגברא גופיה לא חזי\u0004 \u0005[שהאיש עצמו אינו ראוי]\u0006 שהרי כל עוד הוא ערל אינו חייב בקרבן פסח, ובכל זאת \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003ענוש כרת, אלמא: רמי חיובא עליה\u0004 \u0005[מכאן\u0006 ש\u0005מוטל החיוב עליו]\u0006 אפילו כשאינו ראוי לפי שעה!","\u0003אמר רבה\u0004 תירוץ לקושיה זו: \u0003קסבר\u0004 \u0005[סבר]\u0006 \u0003ר' אליעזר\u0004 בכלל: \u0003אין שוחטין\u0004 את הפסח \u0003וזורקין\u0004 את דם הפסח \u0003על\u0004 (לצורך) \u0003טמא שרץ\u0004 שכן לפי שעה טמא הוא, ואף על פי שביכולתו לטבול במקוה ולהיות טהור גמור בליל הפסח."],["\u0003וכל שאילו ביחיד נדחה\u0004 שכל טומאה שאם נטמא בה אדם יחיד הריהו נדחה לפסח שני, אם ארע מעין זה \u0003בציבור עבדי\u0004 \u0005[עושים]\u0006 כולם את הפסח \u0003בטומאה.\u0004 וכלל נוסף: \u0003וכל מילתא דאיתא\u0004 \u0005[דבר שישנו]\u0006 \u0003בציבור\u0004 שיש בו כדי לחייבו, \u0003איתא\u0004 \u0005[ישנו]\u0006 \u0003ביחיד. וכל מילתא דליתא\u0004 \u0005[דבר שאינו]\u0006 \u0003בציבור, ליתא\u0004 \u0005[אינו]\u0006 \u0003ביחיד.\u0004","ועל פי עקרונות אלה, הרי לענין \u0003ערילות, דאי כוליה ציבור ערלים נינהו\u0004 \u0005[שאם\u0006 יקרה \u0005שכל הציבור ערלים הם]\u0006 \u0003אמרינן להו: קומו מהולו נפשייכו ועבידי פסחא\u0004 \u0005[אומרים אנו להם: קומו מולו עצמכם ועשו פסח]\u0006 ואין אומרים שיעשה כל הציבור כולו בערלות. \u0003יחיד נמי\u0004 \u0005[גם כן]\u0006 \u0003אמרינן ליה קום מהול ועביד פסחא\u0004 \u0005[אומרים אנו לו: קום מול ועשה פסח],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא מהיל ועביד\u0004 \u0005[מל ועשה] —\u0006 \u0003ענוש כרת.\u0004","ואילו ב\u0003טומאה דאי כוליה ציבורא\u0004 \u0005[שאם כל הציבור]\u0006 \u0003טמאין נינהו\u0004 \u0005[הם] —\u0006 \u0003לא מדינן עלייהו\u0004 \u0005[מזים עליהם]\u0006 מי חטאת, \u0003אלא עבדי\u0004 \u0005[עושים]\u0006 את הפסח \u0003בטומאה, יחיד נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור\u0004 מהזאה וכיון שנפטר ממנה שוב אינה דוחה את השבת. ואם כן יש מקום לחלק בין ערלות וטומאה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרבא:\u0004 וכי אפשר לקיים כללים אלה? \u0003והרי פסח שני דליתיה\u0004 \u0005[שאינו]\u0006 \u0003בציבור ואיתיה\u0004 \u0005[וישנו]\u0006 \u0003ביחיד! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דהא עבד ליה ציבורא\u0004 \u0005[שהרי עשה אותו\u0006 את הפסח \u0005הציבור]\u0006 כבר \u0003ב\u0004פסח ה\u0003ראשון\u0004 בטומאה, ולכן אין להשוות לכך פסח שני.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 שנינו: \u0003יכול לא יהא ענוש כרת\u0004 מי שלא הקריב קרבן פסח \u0003אלא\u0004 דווקא זה \u0003שהיה טהור ושלא היה בדרך רחוקה\u0004 שהטמא והעובר בדרך רחוקה נאמר במפורש בתורה שפטורים מפסח ראשון וחייבים בשני. מי שהיה \u0003ערל\u0004 שלא נימול לפני הפסח או \u0003טמא שרץ ושאר כל הטמאים\u0004 שלא נטמאו במת, ולא נטהרו לפני הפסח \u0003מנין\u0004 שגם הם חייבים כרת? — \u0003תלמוד לומר:\u0004 \"והאיש אשר הוא טהור ובדרך לא היה וחדל לעשות הפסח ונכרתה הנפש ההיא מעמיה\" (במדבר ט, יג) ולשון הכתוב \u0003\"והאיש\"\u0004 באה לרבות את כל היכולים להטהר ולהיות ראויים.","ומעתה נדקדק: \u0003מדקא מהדר אטמא שרץ\u0004 \u0005[כיון שהוא מחזר\u0006 לרבות מהפסוק אף \u0005טמא שרץ]\u0006 \u0003קסבר\u0004 \u0005[\u0006מכאן \u0005שסבר]\u0006 \u0003אין שוחטין וזורקין על טמא שרץ, דאי\u0004 \u0005[שאם]\u0006 \u0003שוחטין וזורקין על טמא שרץ — למה ליה\u0004 \u0005[לו]\u0006 לשם מה \u0003לאהדוריה עליה\u0004 \u0005[לחזור עליו\u0006 ולרבותו\u0005]\u0006 \u0003היינו\u0004 \u0005[הריהו]\u0006 \u0003טהור\u0004 כשאר הטהורים שלא עשו פסח. שהרי יכול לשלוח קרבנו בידי אחר ובערב יאכל מן הפסח. אלא ודאי אין שוחטים וזורקים לצורכו, ועם כל זה אם ביטל מצות הפסח חייב כרת \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא חזי\u0004 \u0005[ראוי]\u0006 באותה שעה להקרבת קרבן \u0005—\u0006 \u0003חיובא עליה\u0004 \u0005[החיוב\u0006 מוטל \u0005עליו]\u0006 מכל מקום. \u0003ואף על גב דליתא\u0004 \u0005[ואף על פי שאינו]\u0006 \u0003בציבור איתיה\u0004 \u0005[ישנו]\u0006 \u0003ביחיד,\u0004 שציבור הטמא בשרץ עושה כולו בטומאה אבל ביחיד נדחה.","\u0003אלא אמר רבא:\u0004 יש לחזור מן הדברים הקודמים ולומר: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 \u0003ר' אליעזר: שוחטין וזורקין על טמא שרץ, והוא הדין\u0004 ששוחטים וזורקים על \u0003טמא מת בשביעי שלו.\u0004 ואם תקשה אם כן הוא \u0003והזאה למאי\u0004 \u0005[ל\u0006צורך \u0005מה]?\u0006 שאם אפשר לשחוט ולזרוק הדם בשבילו, הלוא אין בהזאה זו אלא צורך \u0003אכילה\u0004 שיוכל לאכול את הפסח אולם \u0003אכילת פסחים לא מעכבא\u0004 \u0005[אינה מעכבת]\u0006 שאדם שנזרק דם הפסח עבורו בהיתר אם לאחר מכן אינו יכול לאכול את הפסח, כגון שנטמא או אבד — הריהו יוצא ידי חובתו ופטור מכרת! ואם כן אין ההזאה כמכשירי מצוה שמחללים שבת עליהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אבא לרבא: אם כן\u0004 ששוחטים על טמא שרץ \u0003נמצא פסח נשחט שלא לאוכליו\u0004 שהרי אדם זה בשעת שחיטת הפסח עדיין אינו ראוי לאכול ממנו מפני טומאתו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שלא לאוכליו\u0004 משמעו \u0003לחולה ולזקן,\u0004 ש\u0003לא חזי\u0004 \u0005[ראוי]\u0006 להם כלל, \u0003אבל האי\u0004 \u0005[זה]\u0006 הטמא, בעצם \u0003מיחזא חזי\u0004 \u0005[ראוי]\u0006 הוא לאכול, אבל \u0003תקוני\u0004 \u0005[תיקון]\u0006 \u0003הוא\u0004 ש\u0003לא מתקן\u0004 \u0005[מתוקן]\u0006 עתה לאכילה, ולפיכך הוא נחשב מן הראויים לאכול, אלא שחיסרון חיצוני הוא המעכבו מאכילה.","במשנה שנינו \u0003כלל אמר ר' עקיבא\u0004 שמלאכה שאפשר לעשותה בקרבן הפסח מערב שבת כדי להכשירו לשחיטה ולהקרבה אין עושים אותה בשבת, אבל מה שאי אפשר לעשות מבעוד יום כן עושים בשבת. \u0003אמר רב יהודה אמר רב: הלכה כר' עקיבא\u0004 לענין קרבן הפסח. ומעירים, \u0003ותנן נמי\u0004 \u0005[ושנינו\u0006 במשנה \u0005גם כן]\u0006 \u0003גבי מילה כי האי גוונא\u0004 \u0005[כעין זה],\u0006 \u0003כלל אמר ר' עקיבא: כל מלאכה\u0004 שצריכים לשם המילה \u0003שאפשר לעשותה מערב שבת\u0004 משום שלא נקבע זמנה בו ביום \u0003אינה דוחה את השבת, מילה\u0004 עצמה \u0003שאי אפשר לעשותה מערב שבת\u0004 שהרי לא הגיע זמנה \u0003דוחה את השבת. ואמר רב יהודה אמר רב: הלכה כר' עקיבא.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שיפסקו הלכה זו בשני המקרים. \u0003דאי אשמעינן גבי\u0004 \u0005[שאם היה משמיע לנו לענין]\u0006 קרבן \u0003פסח\u0004 בלבד, היינו אומרים כי \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 הדין שדברים הנחוצים לצורך \u0003מכשירי\u0004 (הכנת) \u0003מצוה לא דחו\u0004 \u0005[דוחים]\u0006 את ה\u0003שבת,\u0004 כיון שאין קרבן הפסח חשוב כמילה, \u0003משום\u0004 ש\u0003לא נכרתו עליה שלש עשרה בריתות\u0004 כבמילה. \u0003אבל מילה\u0004 ש\u0003נכרתו עליה שלש עשרה בריתות\u0004 שכן בפרשה המדברת בה נאמר שלש עשרה פעמים הלשון \"ברית\" (בראשית פרק יז), שהמילה היא ברית בין ה' ועם ישראל, \u0003אימא לידחי\u0004 \u0005[אמור\u0006 שחשובה \u0005ותדחה\u0006 שבת\u0005].\u0006","ולהיפך \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 \u0003מילה\u0004 בלבד שהיא דוחה את השבת, היינו אומרים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 הדין ש\u0003מכשירי מצוה לא דחו\u0004 \u0005[דוחים]\u0006 \u0003שבת,\u0004 שאסור לעשות בשבת את מכשירי המילה היכולים להיעשות מבעוד יום משום \u0003דליכא\u0004 \u0005[שאין]\u0006 בהם חיוב \u0003כרת,\u0004 שאם אין מלים את התינוק ביום השמיני, אם מלים אותו לאחר מכן אין חייבים כרת וחיוב כרת שבמילה חל רק כשאינו רוצה למול כלל, ולכך אינו דוחה, \u0003אבל פסח דאיכא\u0004 \u0005[שיש]\u0006 \u0003כרת\u0004 אם אין עושים אותו בזמנו, \u0003אימא לידחי\u0004 \u0005[אמור שידחה]\u0006 את השבת, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להיאמר בשני המקרים גם דברי ר' עקיבא ווכן שהלכה כמותו.","\u0003אימתי מביא\u0004 קרבן \u0003חגיגה עמו,\u0004 עם קרבן הפסח? שהיו מוסיפים קרבן מיוחד ביום ארבעה עשר בניסן עם קרבן הפסח \u0003בזמן שהוא\u0004 (הפסח) \u0003בא\u0004 ביום \u0003חול\u0004 ולא בשבת, וכשבא \u0003בטהרה\u0004 ולא כשעושים אותו הקהל כשרובו טמא ובזמן שהיה קרבן הפסח \u0003מועט\u0004 ולא כדי שביעה לכל המשתתפים וקרבן החגיגיה היה נאכל תחילה ולאחריו הפסח לגמר שביעה. אבל \u0003בזמן\u0004 שקרבן הפסח \u0003בא בשבת\u0004 או שבא \u0003במרובה\u0004 כלומר שהיו מנוייו מועטים והרי הם יכולים לאכול הרבה ממני \u0003ובטומאה — אין מביאין עמו חגיגה.\u0004","ולעצם הקרבן: \u0003חגיגה היתה באה מן הצאן מן הבקר, מן הכבשים ומן העזים מן הזכרים ומן הנקבות\u0004 שאין בחגיגה כל אותן הגבלות שיש בקרבן פסח שהוא בא רק מקטני הצאן (גדיים, טלאים) ודווקא מן הזכרים, \u0003ונאכלת\u0004 החגיגה \u0003לשני ימים ולילה אחד\u0004 כשאר קרבנות שלמים.","על עצם הבאתו של דין זה כאן שואלים: \u0003מאי תנא\u0004 \u0005[מה שנה]\u0006 ענין קרבן במשנה קודם לכן \u0003דקתני\u0004 \u0005[ששנה]\u0006 \u0003חגיגה,\u0004 בלא קשר למשניות הקודמות? ומשיבים: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003הרכבתו והבאתו\u0004 ש\u0003לא דחי\u0004 \u0005[דוחה]\u0006 \u0003שבת, קתני נמי\u0004 \u0005[שנה גם כן]\u0006 אגב כך גם דין קרבן \u0003חגיגה\u0004 ש\u0003לא דחי\u0004 \u0005[דוחה]\u0006 \u0003שבת. והכי קאמר\u0004 \u0005[וכך אמר,\u0006 כך יש להבין\u0005]:\u0006 \u0003אימתי מביאין עמו\u0004 עם קרבן הפסח גם קרבן \u0003חגיגה — בזמן שהוא בא בחול, בטהרה ובמועט.\u0004","\u0003אמר רב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מהלכות אלה כי \u0003חגיגת ארבעה עשר\u0004 בניסן, הבאה עם הפסח שמדובר בה במשנתנו (להבדיל מחגיגה הבאה בכל יום של חג, בפסח כבחגים אחרים, שקרויה חגיגת חמשה עשר)"],["\u0003לאו חובה היא\u0004 כלומר, אין חובה אמורה בתורה לעשותה. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר ש\u0003חובה היא\u0004 — אם כן \u0003תיתי\u0004 \u0005[תבוא]\u0006 אף \u0003בשבת, ותיתי\u0004 \u0005[ותבוא]\u0006 אף \u0003במרובה, ותיתי\u0004 \u0005[ותבוא]\u0006 אף \u0003בטומאה.\u0004","ושואלים: אם כן שאין הבאת החגיגה חובה, \u0003במועט מיהו\u0004 \u0005[בכל אופן]\u0006 \u0003מאי טעמא אתיא\u0004 \u0005[מה הטעם באה]\u0006 חגיגה זו? הרי די בפסח כדי שביעת מנוייו! ומסבירים שהטעם הוא \u0003כדתניא\u0004 \u0005[כפי ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003חגיגה הבאה עם הפסח\u0004 היא \u0003נאכלת תחילה,\u0004 והטעם הוא \u0003כדי שיהא פסח נאכל על השבע.\u0004 ואף שיש בו כדי להשביע את מנוייו, אינם נהנים מאכילתו אלא אם כן הריהם שבעים כבר והוא בא רק לגמר שביעה, ומתוך כך הצורך באכילת החגיגה אף במנויים מועטים.","שנינו במשנה שחגיגת ארבעה עשר בניסן \u0003נאכלת לשני ימים\u0004 ולילה אחד. ומעירים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 ש\u0003לא\u0004 כשיטת \u0003בן תימא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בן תימא אומר: חגיגה הבאה עם הפסח\u0004 ביום ארבעה עשר בניסן \u0003הרי היא כפסח, ואינה נאכלת אלא ליום ולילה\u0004 בלבד. \u0003וחגיגת חמשה עשר\u0004 כלומר, קרבן חגיגה שמביאים ביום טוב ראשון של פסח עצמו כפי שמביאים בכל חג אחר — דינה כשלמים, ו\u0003נאכלת לשני ימים ולילה אחד.\u0004","\u0003וחגיגת ארבעה עשר\u0004 אם עיכב את שחיטתה למחר \u0003יוצא בה משום\u0004 מצות \u0003שמחה\u0004 כאמור \"ושמחת בחגך\", ואולם \u0003אין יוצא בה משום\u0004 מצות הבאת \u0003קרבן\u0004 חגיגת חמישה עשר.","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003בן תימא\u0004 ומה ביסוס דבריו בתורה? ומסבירים: \u0003כדמתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]\u0006 את הפסוק \u0003\"ולא ילין לבקר זבח חג הפסח\"\u0004 (שמות לד, כה), \u0003\"זבח חג\" — זה\u0004 קרבן ה\u0003חגיגה, \"הפסח\" — כמשמעו, ואמר רחמנא\u0004 \u0005[הכתוב]:\u0006 \u0003\"לא ילין\",\u0004 הרי שגם החגיגה אסורה בהלנה לבוקר.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם \u0003ל\u0004פי שיטת \u0003בן תימא\u0004 חגיגה הבאה עם הפסח \u0003נאכלת צלי\u0004 בלבד כפסח \u0003או אין נאכלת צלי?\u0004 וצדדי השאלה: \u0003כי אקשיה רחמנא\u0004 \u0005[כאשר השווה אותה הכתוב]\u0006 \u0003לפסח\u0004 הריהו לענין \u0003לינה\u0004 בלבד שאסור להלינה עד הבקר, \u0003אבל\u0004 לענין מצות \u0003צלי — לא, או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 שההשוואה היא לכל, ואף החגיגה הבאה עם הפסח חייבת להיאכל צלי.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון: שבזמן שבית המקדש קיים היתה אחת משאלות התינוקות בליל חג הפסח: מה נשתנה הלילה הזה מכל הלילות, שבכל הלילות אנו אוכלים בין צלי, בין שלוק ובין מבושל, \u0003הלילה הזה כולו צלי. ואמר רב חסדא: זו דברי בן תימא,\u0004 משמע שאף החגיגה נאכלת צלי בלבד, \u0003שמע מינה\u0004.","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה\u0005]\u0006 \u0003ל\u0004דעת \u0003בן תימא:\u0004 חגיגת ארבעה עשר \u0003באה\u0004 אף \u0003מן הבקר או\u0004 שמא \u0003אינה באה מן הבקר\u0004 כפסח שבא מן הצאן; \u0003באה\u0004 אף \u0003מן הנקבות או\u0004 שמא \u0003אינה באה מן הנקבות\u0004 כפסח עצמו; \u0003באה\u0004 אף \u0003בת שתי שנים או אינה באה בת שתי שנים\u0004 אלא בת שנה בלבד בפסח עצמו?","ומשום אותה בעיה עקרונית: \u0003כי אקשיה רחמנא\u0004 \u0005[כאשר השוותה אותה התורה]\u0006 \u0003לפסח\u0004 הרי זה \u0003למידי\u0004 \u0005[לדברים]\u0006 שב\u0003אכילה\u0004 ולזמן אכילתה, \u0003אבל לכל מילי\u0004 \u0005[לכל דבר]\u0006 — \u0003לא, או דילמא\u0004 \u0005[שמא]\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 והשווה אותה לפסח לכל דבר.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלות אלו ממה ששנינו: \u0003חגיגה הבאה עם הפסח\u0004 ביום ארבעה עשר בניסן \u0003הרי היא כפסח\u0004 לכל דבריו, \u0003באה מן הצאן ואינה באה מן הבקר, באה מן הזכרים ואינה באה מן הנקבות, באה בת שנתה ואינה באה בת שתי שנים, ואינה נאכלת אלא ליום ולילה, ואינה נאכלת אלא צלי, ואינה נאכלת אלא למנויו\u0004 שנמנו קודם לכן לאכול מקרבן זה.","ומסבירים: \u0003מאן\u0004 \u0005[מי]\u0006 הוא ש\u0003שמעת ליה דאית ליה האי סברא\u0004 \u0005[אותו שיש לו\u0006 שמקבל \u0005סברא זו]\u0006 להשוות את החגיגה לפסח לכל דבריה — \u0003בן תימא, שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003כולהו מילתא בעינן\u0004 \u0005[כל הדברים צריכים אנו]\u0006 שכל הדינים האמורים בפסח אמורים אף בחגיגת ארבעה עשר. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 \u0003ל\u0004שיטת \u0003בן תימא: יש בה\u0004 בחגיגת ארבעה עשר איסור \u0003משום שבירת עצם\u0004 כבקרבן פסח שנתפרש בתורה שאין לשבור בו עצם, \u0003או אין בה משום שבירת העצם?\u0004 וצדדי שאלה זו: \u0003אף על גב דכי אקשיה רחמנא\u0004 \u0005[אף על פי שהשוותה אותה תורה]\u0006 \u0003לפסח,\u0004 הרי \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"בו\",\u0004 כאמור \"ועצם לא תשברו בו\" (שמות יב, מו), ולשון \"בו\" לשון צמצום ודיוק היא, ומשמעה \u0003\"בו\"\u0004 בלבד נאמר איסור זה — \u0003ולא בחגיגה\u0004 הבאה עמו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003האי\u0004 \u0005[זה]\u0006 \u0003\"בו\"\u0004 שנאמר כאן כוונתו לדיוק אחר: \u0003ב\u0004קרבן פסח \u0003כשר\u0004 קיים איסור זה \u0003ולא בפסול.\u0004","כדי לפתור את הדבר מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון ממה ששנינו: \u0003סכין שנמצאת ב\u0004יום \u0003ארבעה עשר\u0004 בניסן בירושלים \u0003שוחט בה מיד\u0004 ואינו צריך לחשוש לטהרתה, שמן הסתם סכין הראויה לשחיטה כבר דאגו לטהרה לצורך שחיטת קרבן פסח. ואם מצאה ביום \u0003שלשה עשר שונה\u0004 (חוזר) \u0003ומטביל\u0004 אותה מספק, שמא לא הספיקו להטבילה. \u0003קופיץ\u0004 שהיא סכין גדולה המשמשת לרוב לחיתוך עצמות \u0003בין בזה\u0004 בארבעה עשר \u0003ובין בזה\u0004 בשלושה עשר — \u0003שונה ומטביל.\u0004","ומעתה נברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003רבנן\u0004 \u0005[\u0006כשיטת \u0005חכמים]\u0006 המתירים לשבור עצמות החגיגה, \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003סכין\u0004 בשלושה עשר ש\u0003מטביל\u0004 כיון \u0003דחזיא\u0004 \u0005[שראויה]\u0006 \u0003לפסח, קופיץ נמי\u0004 \u0005[גם כן]\u0006 \u0003הא חזי\u0004 \u0005[הרי ראוי]\u0006 \u0003לחגיגה,\u0004 ולא היה צורך להטביל שנית את הקופיץ, שהרי מן הסתם גם אותו הטבילו לשבירת עצמות קרבן החגיגה.","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 כשיטת \u0003בן תימא היא, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שאף בחגיגה \u0003יש בה משום\u0004 איסור \u0003שבירת העצם,\u0004 ומשום כך קופיץ צריך תמיד להטבילו, שכיון שאסור לשבור כל עצם לא בפסח בחגיגה יתכן שהקופיץ לא נטהר כלל.","ודוחים: \u0003לא, לעולם\u0004 יכול אתה לפרש שיהיה זה כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 וכאן מדובר \u0003כגון שבא\u0004 זמן שחיטת הפסח \u0003בשבת.\u0004 שבמקרה כזה לדעת הכל אין מקריבים בו חגיגה אלא פסח בלבד, ואין איפוא צורך בקופיץ.","ומקשים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסופה\u0006 של אותה משנה\u0005]:\u0006 \u0003חל ארבעה עשר להיות בשבת\u0004 — \u0003שוחט בה\u0004 בסכין \u0003מיד\u0004 בלא להטבילה, ואם \u0003בחמשה עשר\u0004 ביום טוב עצמו מצאה — \u0003שוחט בה מיד,\u0004 שוודאי שהוטבלו מאתמול. \u0003נמצאת קופיץ קשורה לסכין\u0004 אף אם נמצאה בארבעה עשר שחל להיות ביום חול — \u0003הרי היא כסכין\u0004 משום שבודאי טבלום יחד. ואם בסוף המשנה מדובר כשחל ארבעה עשר בשבת, \u0003מכלל דרישא לאו בשבת עסקינן\u0004 \u0005[מכאן שבראשה\u0006 של המשנה \u0005לא בשבת אנו עוסקים],\u0006","\u0003ואלא\u0004 יש לדחות תירוץ זה ולומר שמדובר כאן \u0003שבא\u0004 קרבן פסח באותו מקרה"],["\u0003במרובה\u0004 שמנוייו מועטים ורב הבשר, וכיון שכך אין צורך בחגיגה, וממילא אף אין צורך בקופיץ. על הסבר זה מקשים: \u0003מנא ידעי\u0004 \u0005[מנין יודעים]\u0006 הבעלים שיהא השנה הפסח מרובה, שמא יתרבו הנמנים עליו עד שעת שחיטתו וימצא הפסח מועט.","\u0003אלא\u0004 צריכים לומר שמדובר כאן בפסח \u0003שבא בטומאה\u0004 של רוב ישראל, שאין מביאים עמו חגיגה. ומקשים: \u0003סוף סוף, מנא ידעי\u0004 \u0005[מנין יודעים]\u0006 הבעלים מראש כשמטבילים סכיניהם ביום שלושה עשר בניסן, שיבוא הפסח בטומאה? שמא יתברר שרוב ציבור טהור!","ומשיבים: מדובר \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003נשיא,\u0004 ולפי ההלכה צריכים הכל להיטמא לו. ושואלים: \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003נשיא אימת\u0004 \u0005[אימתי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003דמית\u0004 \u0005[שמת]\u0006 \u0003בשלשה עשר\u0004 והכל נטמאים לו — אם כן, \u0003סכין\u0004 מלכתחילה \u0003למה לי דמטבליה\u0004 \u0005[להטבילה]?\u0006 שהרי בכל אופן עתיד הוא להיטמא! \u0003ואלא דמית\u0004 \u0005[שמת]\u0006 \u0003בארבעה עשר,\u0004 ואין יודעים לפני כן אם יבוא הפסח בטומאה. ואם כן, \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 \u0003סכין\u0004 ש\u0003מטביל\u0004 אותה, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003קופיץ\u0004 ש\u0003לא מטביל לה\u0004 \u0005[אותה]?\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה ש\u0003נשיא גוסס בשלשה עשר. סכין\u0004 שיש בה רק \u0003חד ספיקא\u0004 \u0005[ספק אחד]\u0006 ספק ימות הנשיא וייעשה הפסח בטומאה, ספק לא ימות הנשיא לפני החג — הרי הוא \u0003מטביל\u0004 אותה, שאם לא ימות הנשיא צריך הוא סכין טהורה לשחוט בה. \u0003קופיץ\u0004 שיש בו \u0003תרי ספיקי\u0004 \u0005[שני ספיקות]\u0006 שמא ימות הנשיא ולא יצטרכו להטבילו, ועוד שמא יהא הפסח מרובה ולא יצטרכו לקרבן חגיגה — אינו \u0003מטביל.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 \u0003יהודה בן דורתאי פירש\u0004 מן החכמים \u0003הוא ודורתאי בנו, והלך וישב לו בדרום\u0004 כדי שלא תחול עליו החובה להקריב את הפסח וחגיגה (שהרי הוא בדרך רחוקה מירושלים) מפני שחלק על שיטת חכמים בדין חגיגה של יום ארבעה עשר, שלדבריהם אינה דוחה את השבת. ש\u0003אמר: אם יבוא אליהו ויאמר להם לישראל: מפני מה לא חגגתם חגיגה בשבת, מה הן אומרים לו? תמהני על שני גדולי הדור שמעיה ואבטליון שהן חכמים גדולים ודרשנין גדולים, ולא אמרו להן לישראל\u0004 שאף \u0003חגיגה\u0004 של יום ארבעה עשר \u0003דוחה את השבת.\u0004","\u0003אמר רב: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003בן דורתאי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזבחת פסח לה' אלהיך צאן ובקר\u0004 במקום אשר יבחר ה' לשכן שמו שם\u0003\"\u0004 (דברים טז ב), ויש לשאול: וכי בא פסח מן הבקר? \u0003והלוא אין פסח בא אלא מן הכבשים ומן העזים\u0004 כמבואר בספר שמות (יב, ה)! \u0003אלא\u0004 כך יש להבין: \u0003\"צאן\" — זה פסח, \"בקר\" — זו חגיגה\u0004 הבאה עמו. \u0003ואמר רחמנא\u0004 \u0005[הכתוב]\u0006 \u0003\"וזבחת פסח\"\u0004 ללמדנו ששניהם נזבחים כאחד. ומכאן למד שדינה של חגיגה כפסח לכל דבר!","\u0003אמר רב אשי:\u0004 וכי \u0003אנן\u0004 \u0005[אנחנו]\u0006 את \u0003טעמא\u0004 \u0005[הטעם]\u0006 של ה\u0003פרושים ניקו ונפרוש\u0004 \u0005[נעמוד ונפרש]?\u0006 שהרי בן דורתאי ובנו פרשו מכל חכמי ישראל, ואיננו צריכים לעסוק בפירוש שיטתם של אלה שהבדילו עצמם מכלל החכמים. \u0003אלא קרא\u0004 \u0005[הפסוק]\u0006 לצורך הסבר שיטתו של \u0003רב נחמן הוא דאתא\u0004 \u0005[שבא],\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: מניין למותר הפסח,\u0004 שהיא בהמה שהקדישוה לקרבן פסח ונאבדה והקריבו אחרת תחתיה, ולאחר מכן מצאוה. או שהפרישו מעות לפסח וחלה עליהם קדושת הפסח, ואחר כך הוזלו הבהמות ונותרו מעות, \u0003שקרב\u0004 בתור זבח \u0003שלמים —\u0004","\u0003שנאמר \"וזבחת פסח לה' אלהיך צאן ובקר\",\u0004 ונשאלה השאלה: \u0003וכי פסח מן הבקר בא? והלא אין פסח בא אלא מן הכבשים ומן העזים! אלא\u0004 בא הכתוב ללמד כי \u0003מותר הפסח יהא לדבר הבא מן הצאן ומן הבקר,\u0004 וקרבן שלמים הוא הקרבן שמותר להביא מכל מיני צאן ובקר, זכרים ונקבות.","לעצם הדברים שואלים: \u0003ורבנן\u0004 \u0005[ו\u0006לשיטת \u0005חכמים]\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שחגיגת ארבעה עשר וכן של חמישה עשר \u0003לא דחי\u0004 \u0005[דוחה]\u0006 את ה\u0003שבת? הא\u0004 \u0005[הרי]\u0006 \u0003ודאי קרבן ציבור הוא,\u0004 שהרי היא באה למנויים רבים, וכל קרבנות הציבור דוחים את השבת!","\u0003אמר ר' אילעא משום ר' יהודה בן ספרא: אמר קרא\u0004 \u0005[המקרא]\u0006 בענין חג הסוכות: \u0003\"וחגתם אתו חג לה' שבעת ימים בשנה\u0004 חוקת עולם לדורותיכם בחודש השביעי תחוגו אותו\u0003\"\u0004 (ויקרא כג, מא), וכי \u0003שבעה\u0004 ימים הוא חג הסוכות? הלוא \u0003שמונה הוו\u0004 \u0005[הם],\u0006 שהרי בסוף חג הסוכות חוגגים תמיד שמיני עצרת ושמונה ימים הם! \u0003אלא מכאן\u0004 לקרבן \u0003חגיגה\u0004 (שעליו נאמר \"וחגותם אותו\") \u0003שאינה דוחה את השבת.\u0004 שכיון שאין שמונה ימים בלא שבת באמצע, לכן אמרה התורה שחוגגים את החג (כלומר מקריבים בו קרבן חגיגה) רק שבעה ימים בלבד.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר: אמרתי לפני רבותי\u0004 והקשיתי על סברה אחרונה זו: \u0003פעמים שאי אתה מוצא אלא ששה\u0004 ימים שאפשר להקריב בהם חגיגה, \u0003כגון שחל יום טוב הראשון של חג בשבת\u0004 ואז גם יום השמיני חל להיות בשבת, ונמצא שרק ששה ימים מותרים בהקרבת חגיגה! \u0003אמר אביי: אבין תכלא לימא כי הא מילתא\u0004 \u0005[המשכל\u0006 את ילדיו \u0005יאמר דבר כזה]\u0006 ולא יזהר בלשונו שלא לשאול שאלה בלתי מבוססת? הלוא יש הבדל גדול: \u0003שמונה לא משכחת\u0004 \u0005[תמצא]\u0006 \u0003לה כלל\u0004 אפשרות שיהיו שמונה ימים בלא שבת בתוך החג, אבל \u0003שבעה איתא\u0004 \u0005[יש]\u0006 \u0003ברוב השנים\u0004 שאפשר להקריב בהם.","\u0003אמר עולא אמר ר' אלעזר: שלמים ששחטן מערב יום טוב\u0004 בבוקר, \u0003אינו יוצא בהן לא משום\u0004 שלמי \u0003שמחה ולא משום\u0004 קרבן \u0003חגיגה.\u0004 ומפרש: \u0003משום שמחה\u0004 אינו יוצא — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וזבחת\u0004 שלמים ואכלת שם \u0003ושמחת\u0004 לפני ה' אלהיך\u0003\"\u0004 (דברים כז, ז) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לפי כתוב זה שתהא ה\u0003זביחה\u0004"],["\u0003בשעת שמחה\u0004 ביום טוב עצמו, \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003משום חגיגה\u0004 אינו יוצא משום שקרבן חגיגה \u0003הוי\u0004 \u0005[הינו]\u0006 \u0003דבר שבחובה,\u0004 שהרי חייב כל אדם להביא קרבן זה, וכלל בידינו: \u0003כל דבר שבחובה אינו בא אלא מן החולין,\u0004 ואינו יכול להביא קרבן חובה מדבר המוקדש כבר לצורך אחר.","ומעירים: \u0003לימא מסייע ליה\u0004 \u0005[האם לומר\u0006 שאפשר \u0005לסייע לו]\u0006 מברייתא זו: שנינו על דברי הפסוק: \"שבעת ימים תחוג לה' אלוהיך במקום אשר יבחר ה' כי יברכך ה' אלוהיך בכל תבואתך ובכל מעשה ידיך והיית אך שמח\" (דברים טז, טו), ופסוק זה לכאורה מיותר שכבר נאמרה לשון דומה לזו לפני כן (\"ושמחת בחגך\". דברים טז, יד). ודורשים: \u0003\"והיית אך שמח\" בא לרבות לילי יום טוב האחרון\u0004 של חג, שאף בהם יש לדאוג שתהא \u0003שמחה\u0004 באכילת קרבנות שלמים הראויים. ודנים: \u0003אתה אומר\u0004 שהכוונה ל\u0003לילי יום טוב האחרון, או אינו\u0004 בא לרבות \u0003אלא לילי יום טוב הראשון? תלמוד לומר: \"אך שמח\"\u0004 לשון \"אך\" משמעו: \u0003חלק\u0004 שהוא לשון מיעוט וחלוקה, לומר שלא בכל פעם יש שמחה.","ומעתה נבוא לברר: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 למדים אנו מלשון מיעוט זו דוקא לגבי לילה ראשון שאינו שייך לשמחה. \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שבלילה ראשון \u0003אין לו במה ישמח?\u0004 שכפי שאמרנו קרבן שלמים שמקריב מערב החג, אינו יוצא בו חובת שמחה לפי שלא נזבח בשעת שמחה! אבל ביום טוב אחרון יכול לשמוח בשלמים שנזבחו מאתמול בחול המועד, שאף הוא זמן שמחה.","ודוחים: \u0003לא\u0004 מטעם זה, אלא \u0003כדקתני טעמא\u0004 \u0005[כפי ששנוי טעמו\u0006 של דבר\u0005]\u0006 בברייתא ששנינו: \u0003מה ראית לרבות לילי יום טוב אחרון\u0004 לשמחה \u0003ולהוציא לילי יום טוב ראשון,\u0004 שהרי אף ברמזי הכתוב לא נאמר דבר זה? ומסבירים: \u0003מרבה אני לילי יום טוב האחרון\u0004 לשמחה משום \u0003שיש שמחה\u0004 בימים ש\u0003לפניו\u0004 כל ימי החג, \u0003ומוציא אני לילי יום טוב ראשון שאין\u0004 יום \u0003שמחה לפניו,\u0004 ואין איפוא ראיה מכאן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על דברי עולא, שנינו: \u0003חגיגת ארבעה עשר יוצא בה משום שמחה, ואין יוצא בה משום חגיגה,\u0004 ומעתה יש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 לפי דברי עולא \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003זביחה בשעת שמחה, וליכא\u0004 \u0005[ואין\u0006 כאן\u0005]!\u0006 \u0003אמר רב אידי בר אבין: שעיכב ושחטה\u0004 לאחר מכן בימי החג, זמן שמחה.","\u0003אמר רב אשי: הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כן]\u0006 \u0003הא מתניתא, מאן קתני לה\u0004 \u0005[ברייתא זו, מי שנה אותה]?\u0006 הלוא \u0003בן תימא\u0004 הוא ששנאה! אולם לשיטת \u0003בן תימא הא פסלה לה\u0004 \u0005[הלוא נפסלה]\u0006 \u0003בלינה,\u0004 שלשיטתו חגיגה זו דינה כפסח ואסור לאוכלה למחר. \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאכן לא הקריבו אותה ביום ארבעה עשר, אלא לאחר מכן.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא,\u0004 שנינו: \u0003ההלל והשמחה\u0004 בחג הסוכות \u0003שמנה\u0004 ימים, \u0003ואי אמרת בעינן\u0004 \u0005[ואם אומר אתה שצריכים אנו]\u0006 שתהא \u0003זביחה בשעת שמחה,\u0004 הרי \u0003זמנין סגיאין\u0004 \u0005[פעמים הרבה]\u0006 ש\u0003לא משכחת לה\u0004 \u0005[מוצא אותה]\u0006 \u0003אלא שבעה\u0004 ימים, \u0003כגון שחל יום טוב הראשון להיות בשבת,\u0004 ובשבת אין מקריבים קרבן חגיגה! \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה: משמחו בשעירי הרגלים\u0004 כלומר, מקיימים אז מצות שמחה בבשר השעירים שמקריבים ברגלים לחטאת, ואותן חטאות נאכלות לכהנים.","\u0003אמר רבא: שתי תשובות בדבר\u0004 לדחות: \u0003חדא\u0004 \u0005[אחת]\u0006 ש\u0003שעירי הרגלים\u0004 בשבת \u0003חי — נאכלין, צלי — אין נאכלין,\u0004 שהרי אי אפשר לצלותם ביום השבת, שאין צליה זו מעיקר העבודה, ואפשר אם כן לאכלם רק כבשר חי, \u0003ושמחה בחי ליכא\u0004 \u0005[אין],\u0006 שאכילת בשר חי איננה יכולה להיקרא שמחה. \u0003ועוד,\u0004 אם אותם \u0003כהנים אוכלין, וישראל\u0004 אם כן \u0003במה\u0004 הם \u0003שמחים\u0004 ובמה מקיימים הם מצוה זו? \u0003אלא אמר רב פפא: משמחו בכסות נקיה ויין ישן.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר\u0004 בשם \u0003ר' אלעזר: שלמים ששחטן מערב יום טוב — יוצא בהן משום שמחה\u0004 אבל \u0003אין יוצא בהן משום חגיגה,\u0004 ומפרש: \u0003יוצא\u0004 בהם \u0003משום שמחה — כי לא בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא \u0003זביחה בשעת שמחה,\u0004 והעיקר הוא שיהא נאכל בשעת שמחה. \u0003ולא\u0004 יצא \u0003משום חגיגה,\u0004 כי חגיגה \u0003הוי\u0004 \u0005[היא]\u0006 \u0003דבר שבחובה, וכל דבר שבחובה אינו בא אלא מן החולין.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 הרי שנינו: \u0003\"והיית אך שמח\" לרבות לילי יום טוב האחרון לשמחה. אתה אומר לרבות לילי יום טוב האחרון\u0004 לשמחה, \u0003או אינו אלא לרבות לילי יום טוב הראשון? תלמוד לומר \"אך\"\u0004 — משמעו: \u0003חלק.\u0004","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 שסבורים אנו שלשון מיעוט זו באה דווקא למעט יום טוב ראשון, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003אין לו\u0004 ביום טוב הראשון \u0003במה ישמח,\u0004 משום שבקרבן השלמים שמקריב בערב החג אינו יוצא בו ידי חובת שמחה, לפי שלא נזבח בשעת שמחה! ודוחים: \u0003לא,\u0004 הטעם הוא \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]\u0006 בהמשך: \u0003מה ראית לרבות לילי יום טוב האחרון ולהוציא לילי יום טוב הראשון — מרבה אני לילי יום טוב האחרון שיש\u0004 ימים של \u0003שמחה לפניו,\u0004 ומטעם זה \u0003מוציא אני לילי יום טוב הראשון שאין\u0004 אף יום \u0003שמחה לפניו.\u0004","\u0003אמר רב כהנא: מנין לאימורי\u0004 (חלבי הקרבנות העולים למזבח) של \u0003חגיגת חמשה עשר\u0004 בניסן \u0003שנפסלין בלינה\u0004 כבר בלילה הראשון לאחר הקרבתם, ואין ממתינים להם עוד יום נוסף, אף שאת בשר הקרבן מותר לאכול עוד יום נוסף? משום \u0003שנאמר: \"\u0004לא תזבח על חמץ דם זבחי \u0003ולא ילין חלב חגי עד בקר\"\u0004 (שמות כג, יח), \u0003וסמיך ליה\u0004 \u0005[וסמוך לו]\u0006 המילה \u0003\"ראשית\"\u0004 כאמור: \"ראשית ביכורי אדמתך תביא בית ה' אלוהיך\" (שמות כג, יט), \u0003למימרא\u0004 \u0005[לומר]\u0006 לנו: \u0003דהאי בקר\u0004 \u0005[שבוקר זה]\u0006 שנאמר בכתוב הוא \u0003בקר ראשון\u0004 הבא לאחר הקרבת הקרבן.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב יוסף\u0004 על הוכחה זו: \u0003טעמא\u0004 \u0005[הטעם\u0006 דוקא\u0005]\u0006 ש\u0003כתב \"ראשית\", הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתב \"ראשית\" — הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \u0003בקר — בקר שני,\u0004 שהוא לאחר יום המחרת. ויש לשאול: \u0003מי איכא מידי\u0004 \u0005[האם יש דבר\u0006 מקרה\u0005]\u0006 כזה שה\u0003בשר\u0004 כבר \u0003איפסיל ליה מאורתא\u0004 \u0005[נפסל לו מהערב],\u0006 שהרי בשר החגיגה מותר לאוכלו רק שני ימים ולילה שביניהם, ואילו \u0003אימורין\u0004 יהיו מותרים \u0003עד צפרא\u0004 \u0005[הבוקר]\u0006 שלאחר מכן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלמה\u0004 \u0005[למה]\u0006 \u0003לא? והרי\u0004 קרבן \u0003פסח\u0004 לשיטת \u0003ר' אלעזר בן עזריה,\u0004 שלדעתו \u0003בשר איפסיל ליה\u0004 \u0005[נפסל לו]\u0006 מדין תורה כבר \u0003מחצות,\u0004 שלדעתו אין אוכלים את קרבן הפסח אלא עד חצות הלילה, ואילו \u0003אמורין\u0004 קרבים \u0003עד צפרא\u0004 \u0005[הבוקר]!\u0006","\u0003אמר רבא: רב יוסף הכי קא קשיא ליה\u0004 \u0005[כך היה קשה לו]:\u0006 \u0003מי איכא מידי\u0004 \u0005[האם יש דבר,\u0006 דוגמה\u0005]\u0006 ש\u0003אלו תנא לבשר\u0004 הקרבן עצמו \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003\"ראשית\",\u0004 שהתנא הדן בנושא זה בדין אכילת הבשר אינו נזקק לתוספת \"ראשית\", משום שהוא סבור שהיא מובנת מאליה, \u0003ורב כהנא\u0004 כדי ללמד לענין \u0003אימורין\u0004 שהוא פשוט יותר \u0003בעי\u0004 \u0005[צריך]\u0006 את המלה \u0003\"ראשית\"!?\u0004","ושואלים: \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 אותו מקור שרמז רבא עליו? ומסבירים: \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"ולא ילין מן הבשר אשר תזבח בערב ביום הראשון לבקר\"\u0004 (דברים טז, ד),"],["לימד בפסוק זה \u0003על חגיגת ארבעה עשר שנאכלת לשני ימים ולילה אחד.\u0004 והוא דן: \u0003או אינו אלא\u0004 שנאכלת \u0003ליום ולילה\u0004 בלבד? \u0003כשהוא אומר: \"ביום הראשון לבקר\"\u0004 ובכך נדע שכולו מותר באכילה, שדי היה לומר \"ביום הראשון\" (דברים טז, ד), וכשהוסיף \"לבוקר\" — \u0003הרי בקר שני אמור,\u0004","ועדיין יש לומר: \u0003או אינו אלא בקר ראשון, ומה אני מקיים\u0004 את האמור בתורה בקרבן \u0003חגיגה שנאכלת לשני ימים ולילה אחד\u0004 — בחגיגות אחרות \u0003חוץ מזו, כשהוא אומר\u0004 בקרבן שלמים \u0003\"ואם נדר או נדבה\u0004 זבח קרבנו ביום הקריבו את זבחו יאכל וממחרת והנותר ממנו יאכל\u0003\"\u0004 (ויקרא ז, טז), \u0003לימד\u0004 שכל קרבן שלמים בין נדר בין נדבה בין חובה, וגם \u0003חגיגת ארבעה עשר\u0004 בכלל, \u0003שנאכלת לשני ימים ולילה אחד.\u0004","ומעירים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא, \u0003\"או אינו אלא בקר ראשון\",\u0004 ותוהים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 כבר \u0003כשהוא אומר \"ביום הראשון לבקר\" — הרי בקר שני אמור,\u0004 ומה צורך לחזור ולהוכיח זאת? ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כך התכוון לומר\u0005]:\u0006 \u0003או אינו אלא\u0004 שהיא אכן נאכלת ליום ולילה, ומה שהוסיף הפסוק \"ביום הראשון לבוקר\" \u0003בשתי חגיגות הכתוב מדבר, אחת חגיגת ארבעה עשר ואחת חגיגת חמשה עשר.\u0004 ונאמר: \u0003זו לבוקרה\u0004 — חגיגת ארבעה עשר נאכלת ליום ולילה בלבד עד בוקר ראשון של החג, \u0003וזו\u0004 חגיגת חמישה עשר נאכלת ליום ולילה \u0003לבוקרה\u0004 — עד לבוקר יום ששה עשר בניסן.","\u0003הדר אמר\u0004 \u0005[חזר ואמר]\u0006 \u0003אלא דקיימא לן\u0004 \u0005[מה שמוחזק בידינו]\u0006 ש\u0003חגיגה הנאכלת לשני ימים ולילה אחד. אם כן,\u0004 פסוק זה המדבר בקרבנות השלמים ונאמר בו: \u0003\"ואם נדר או נדבה\" במאי\u0004 \u0005[במה]\u0006 באיזה מקרה הוא מדבר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003חגיגת ארבעה עשר, הא כתיב\u0004 \u0005[הוי כתוב]\u0006 \u0003בה\u0004 לפי הנחה זו שאינה נאכלת אלא ל\u0003יום ולילה\u0004 בלבד! \u0003אי\u0004 \u0005[אם]\u0006 \u0003חגיגת חמשה עשר, הא כתיב\u0004 \u0005[הרי כתוב]\u0006 \u0003בה\u0004 גם כן שאינה נאכלת אלא ל\u0003יום ולילה!\u0004","\u0003אלא,\u0004 ודאי יש לומר כי \u0003האי\u0004 \u0005[זה]\u0006 המקרא המדבר בנדר וכו' \u0003לחגיגת חמשה עשר, והאיך כוליה קרא\u0004 \u0005[וכל אותו מקרא]\u0006 של \"לא ילין\" בא רק \u0003לחגיגת ארבעה עשר,\u0004 וכך \u0003לימד על חגיגת ארבעה עשר שנאכלת לשני ימים ולילה אחד.\u0004","ונשוב מעתה למה שרצינו להוכיח בענין \"ראשית\", \u0003טעמא\u0004 \u0005[הטעם,\u0006 דוקא\u0005]\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ביום הראשון לבקר\", דמאי\u0004 \u0005[שמה\u0006 משמע\u0005]\u0006 \u0003\"בקר\" — בקר שני, הא\u0004 \u0005[הרי]\u0006 מכאן ש\u0003כל היכא\u0004 \u0005[מקום]\u0006 שכתוב \u0003בקר סתמא\u0004 \u0005[סתם]\u0006 בלא להוסיף בו פירוט — הכוונה היא ל\u0003בקר ראשון\u0004 הקרוב ביותר ליום ההקרבה, \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא כתב ביה\u0004 \u0005[ בו]\u0006 \u0003ראשית,\u0004 ואם כן לימוד זה מן המלה \"ראשית\" שלמד רב כהנא — מיותר היה.","\u0003הפסח ששחטו\u0004 מתוך אי ידיעת הדין \u0003שלא לשמו בשבת\u0004 ונפסל משום כך — \u0003חייב עליו חטאת,\u0004 שהרי נמצא שעשה בשוגג מלאכה האסורה בשבת שלא לצורך.","\u0003ושאר כל הזבחים\u0004 כגון שלמים \u0003ששחטן\u0004 בשבת בטעות \u0003לשם פסח, אם אינן ראויין\u0004 לצורך הפסח כגון שהיו נקבות, או שהיו בקר, או יותר מבני שנתיים, שלא היה מקום לטעות בכך — \u0003חייב\u0004 חטאת, שכיון שאינו יוצא בהם ידי חובת הפסח, הרי ששחיטתו שלא לצורך היתה. \u0003ואם ראויין הן — ר' אליעזר מחייב חטאת\u0004 אף באלה, \u0003ור' יהושע פוטר,\u0004 שכל זבח שזבחו שלא לשמו כשר. ולכן כיון שלא היתה מלאכתו לריק וקיים מכל מקום מצוה — אין לחייבו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר: מה אם הפסח שהוא מותר\u0004 לשוחטו בשבת \u0003לשמו,\u0004 בכל זאת \u0003כששינה את שמו — חייב,\u0004 שאר \u0003זבחים שהן אסורין\u0004 לשחטן בשבת אפילו \u0003לשמן, כששינה את שמן\u0004 ופסלן \u0003אינו דין שיהא חייב? אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: לא, אם אמרת בפסח\u0004 שנפסל כשנשחט שלא לשמו שהרי \u0003שינהו בדבר אסור,\u0004 שהרי אותו קרבן ששחט לשמו אסור היה לשחטו בשבת, \u0003תאמר\u0004 בשאר \u0003זבחים ששינן בדבר המותר,\u0004 שהרי חשב באותו זמן ששוחטו לצורך פסח שמותר לשחטו בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אליעזר: אימורי ציבור\u0004 (כגון: תמידים ומוספים) \u0003יוכיחו שהן מותרין\u0004 לשוחטן בשבת \u0003לשמן,\u0004 ואף על פי כן \u0003השוחט\u0004 קרבן אחר \u0003לשמן\u0004 שלא לצורך \u0003חייב.\u0004 משמע שאפילו כשמותרת שחיטה כזו לצורך עצמה — לא התירו שחיטה אחרת לצורך זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יהושע: לא, אם אמרת באימורי ציבור שיש להן קצבה,\u0004 שהרי יש מספר מסויים של קרבנות הדרושים לקרבן הציבור ואין צורך ביותר, ואין מקום לטעות בדבר ולשחוט קרבנות נוספים לאותה מטרה, \u0003תאמר בפסח שאין לו קצבה\u0004 ואין מספר מסויים וקבוע של פסחים, ויש עדיין מקום לטעות בדבר.","\u0003ר' מאיר אומר:\u0004 לדעתו \u0003אף השוחט\u0004 בשגגה \u0003לשם אימורי ציבור\u0004 ושחט יותר מהקיצבה הראויה — \u0003פטור,\u0004 ומאותו טעם שאמר ר' יהושע תחילה — ששינה בדבר המותר, שהתכוון לשם מצוה.","ועוד הלכה אחרת בפסח. \u0003שחטו\u0004 את הפסח בשבת, ונתכוון בטעות \u0003שלא לאוכליו\u0004 חולים וזקנים שאינם יכולים לאכול אותו \u0003ושלא למנויו,\u0004 לצורך \u0003ערלין,\u0004 ולצורך \u0003טמאין — חייב\u0004 חטאת. שהרי פסח זה פסול הוא, ונמצא שעשה מלאכה בשבת שלא לצורך מצוה. אבל אם שחטו \u0003לאוכליו ושלא לאוכליו, למנויו ושלא למנויו, למולין ולערלים, לטמאין ולטהורין — פטור,\u0004 שכיון שקרבן פסח שחשב בו שתי מחשבות מסוג זה כשר הוא, נמצא השחיטה ראויה.","\u0003שחטו ונמצא בעל מום — חייב\u0004 להביא קרבן חטאת, שהרי נמצא שעשה בשוגג (שהרי היה עליו לבודקו לפני השחיטה) מלאכה אסורה, שקרבן בעל מום פסול הוא. \u0003שחטו ונמצא טריפה בסתר,\u0004 שאי אפשר היה לדעת שהוא טריפה גם אם היו בודקים אותו תחילה כראוי — \u0003פטור\u0004 אף מחטאת, למרות שקרבנו פסול, שזו אינה קרויה שגגה אלא אונס.","\u0003שחטו ונודע שמשכו הבעלים את ידם\u0004 ממנו ונמנו על קרבן פסח אחר, ונמצא שנשחט הפסח שלא לצורך (שהרי אין לו בעלים), \u0003או\u0004 שנתברר \u0003שמתו או שנטמאו,\u0004 בכל אלו — \u0003פטור, מפני ששחט ברשות,\u0004 שהרי בשעת שחיטה לא ידע, ולא היה לו לחשוב שקרבן זה אינו ראוי."],["\u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים\u0006 כאן\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר במי שהיה \u0003טועה,\u0004 שסבור היה שקרבן זה אינו קרבן פסח אלא זבח אחר — \u0003שמעת מינה\u0004 \u0005[למד אתה ממנה]\u0006 ממה שהוא חייב לפי שהקרבן פסול, כי \u0003עקירה בטעות\u0004 אם עוקר ומשנה את הקרבן משמו ויעודו בטעות \u0003הויא\u0004 \u0005[הריהו]\u0006 \u0003עקירה\u0004 אף שלא נתכוון לעקור. ותמוה, שהדבר שנוי במחלוקת (תוספות). \u0003אלא\u0004 ודאי הכוונה \u0003בעוקר\u0004 מדעת, שאף שיודע שהוא קרבן פסח, משנה את שמו במזיד.","\u0003אימא סיפא\u0004 \u0005[אמור את סוף\u0006 אותה הלכה\u0005]\u0006 האמורה במשנה: \u0003ושאר כל הזבחים ששחטן לשום הפסח, אם אינן ראויין\u0004 לפסח — \u0003חייב,\u0004 ו\u0003אם ראויין הן ר' אליעזר מחייב חטאת ור' יהושע פוטר. ואי\u0004 \u0005[ואם]\u0006 מדובר \u0003בעוקר\u0004 במזיד ויודע שקרבן זה אינו פסח, אם כן \u0003מה לי ראויין, מה לי שאינן ראויין,\u0004 הלוא הוא מקריב במזיד קרבן שאינו ראוי, ולמה פוטרו ר' יהושע?","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 שמדובר \u0003בטועה.\u0004 ואם כן יש סתירה במשנה, \u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 מדברת \u0003בעוקר וסיפא\u0004 \u0005[וסופה]\u0006 מדברת \u0003בטועה! אמר ר' אבין: אין\u0004 \u0005[כן],\u0006 עליך לקבל הנחה זו, אף כי היא בלתי רגילה, ולומר: \u0003רישא\u0004 \u0005[תחילתה]\u0006 \u0003בעוקר וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בטועה.\u0004","מסופר: \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003ר' יצחק בר יוסף\u0004 את \u0003ר' אבהו דהוה קאי באוכלוסא דאינשי\u0004 \u0005[שהיה עומד בתוך קהל גדול של בני אדם],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתין מאי\u0004 \u0005[משנתנו מה],\u0006 כיצד יש להבינה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו בתשובה: \u0003רישא\u0004 \u0005[תחילתה]\u0006 מדברת \u0003בעוקר וסיפא\u0004 \u0005[וסופה]\u0006 \u0003בטועה. תנא מיניה ארבעין זימנין ודמי ליה כמאן דמנחא בכיסיה\u0004 \u0005[שנה ממנו\u0006 וחזר על שמועה זו \u0005ארבעים פעמים\u0006 עד \u0005שהיתה דומה לו כמי שמונחת בכיסו],\u0006 ששיננה פעמים כה רבות עד שנתבררה לו המשנה ונתפסה בזכרונו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003אמר\u0004 לו \u0003ר' אליעזר\u0004 לר' יהושע: \u0003מה אם פסח שמותר\u0004 לשחטו בשבת \u0003לשמו, כששינה את שמו\u0004 — \u0003חייב, זבחים\u0004 אחרים \u0003שהן אסורין\u0004 לשחטן בשבת \u0003לשמן\u0004 אם לא שזהו זמנם המיוחד, \u0003כששינה את שמן אינו דין שיהא חייב! ואם איתא\u0004 \u0005[יש\u0006 מקום\u0005]\u0006 לומר ששני חלקי המשנה אינם מדברים באותו אופן, אם כן \u0003הא\u0004 \u0005[הרי]\u0006 זה \u0003לא דמי\u0004 \u0005[דומה]\u0006 ואין להשוות, כי \u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 מדברת \u0003בעוקר\u0004 בכוונה שם הפסח ממנו, \u0003וסיפא\u0004 \u0005[וסופה]\u0006 מדברת \u0003בטועה!\u0004","ומשיבים: \u0003לר' אליעזר לא שני ליה\u0004 \u0005[שונה לו,\u0006 בעיניו\u0005]\u0006 שלדעתו גם מי שטעה, שנתכוון לעשות מצוה ולא עשאה — חייב חטאת, גם אם היתה זו טעות מסתברת. ולכן אינו מבדיל בין עקירה ביודעין לטעות. ושואלים: \u0003ולר' יהושע דשני ליה\u0004 \u0005[שעונה לו]\u0006 לר' אליעזר כי יש הבדל בין הפסח ששינה בו בדבר האסור לשאר זבחים ששינה את שמם לדבר המותר, \u0003לישני ליה הכי\u0004 \u0005[שיתרץ לו כך]\u0006 שבתחילה מדובר בעוקר ובסוף מדובר בטועה!","ומסבירים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003לדידי\u0004 \u0005[לשיטתי]\u0006 באמת זה \u0003לא דמי\u0004 \u0005[דומה],\u0006 כי \u0003רישא\u0004 \u0005[תחילת\u0006 המשנה\u0005]\u0006 מדברת \u0003בעוקר וסיפא\u0004 \u0005[סופה]\u0006 \u0003בטועה.\u0004 אולם אפילו \u0003לדידך\u0004 \u0005[לשיטתך]\u0006 שאינך מחלק בכך יש מקום לתרץ: \u0003לא אם אמרת בפסח ששינה את שמו לדבר האסור, תאמר בזבחים ששינה את שמן לדבר המותר.\u0004","עוד נאמר במשנה ש\u0003אמר\u0004\u0003 ר' אליעזר\u0004 לר' יהושע: \u0003אימורי ציבור יוכיחו שהן מותרין\u0004 לשוחטן בשבת \u0003לשמן, והשוחט לשמן\u0004 שלא לצורך — \u0003חייב,\u0004 ו\u0003אמר לו ר' יהושע לא אם אמרת באימורי ציבור שכן יש להן קצבה, תאמר בפסח שאין לו קצבה.\u0004","ושואלים: \u0003למימרא דכל היכא דאית ליה\u0004 \u0005[האם\u0006 יש \u0005לומר שבכל מקום שיש]\u0006 \u0003קצבה מחייב ר' יהושע\u0004 את הטועה במצוה זו? \u0003והרי\u0004 לענין מילת \u0003תינוקות\u0004 בשבת ש\u0003יש להן קצבה,\u0004 ובכל זאת \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי\u0004 (מוהל) \u0003שהיו לו שני תינוקות, אחד למולו אחר השבת ואחד למולו בשבת, ושכח ומל את\u0004 הילד שצריך למול \u0003אחר השבת בשבת\u0004 — הרי זה \u0003חייב\u0004 קרבן חטאת, שהרי לא קיים מצות מילה בילד זה, שכל זמן שאינו בן שמונה ימים עדיין אינו חייב במצוה זו, ועשה מלאכה שאין לה היתר.","אבל אם היה ילד \u0003אחד\u0004 שהיה צריך \u0003למולו בערב שבת, ואחד למול בשבת, ושכח ומל את של ערב שבת בשבת — ר' אליעזר מחייב חטאת,\u0004 שכיון שלא היה זה יום שמיני אין מילתו דוחה את השבת, וחילל שבת בשגגה. \u0003ור' יהושע פוטר\u0004 משום ששגג בדבר מצוה ועשה מצוה אחרת, ואם כן, אף שלתינוקות אלו יש קיצבה, מכל מקום פוטר ר' יהושע בטועה בהם!","\u0003אמר ר' אמי: הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במילה, \u0005במה אנו עוסקים]?\u0006 \u0003כגון שקדם\u0004 המוהל \u0003ומל את של ערב שבת בשבת,\u0004 שעדיין \u0003איכא הך\u0004 \u0005[יש אותו\u0006 תינוק\u0005]\u0006 שצריך למול ב\u0003שבת דטריד ביה\u0004 \u0005[שטרוד בו]\u0006 ומוטלת עליו עדיין חובת המילה, וסבור ר' יהושע כיון שטרוד בטירדה של מצוה ויודע שעליו למול תינוק — אין לחייב אותו. \u0003הכא\u0004 \u0005[כאן]\u0006 בענין הקרבנות, \u0003כגון שקדם ושחטינהו לאימורי ציבור ברישא\u0004 \u0005[ושחט את אימורי הציבור תחילה]\u0006 ולכן שוב אין צורך להקריב קרבנות ציבור, וכיון שקרבנות אלה הם דבר שיש בו קיצבה לא היה לו מקום לטעות בו.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 כיצד נבין את ההמשך? \u0003ר' מאיר אומר: אף השוחט לשם אימורי ציבור פטור,\u0004 ולפי ההסבר שלנו חייב אתה לומר שכן הדין \u0003אף על גב דקדים ושחטינהו לאימורי ציבור ברישא\u0004 \u0005[אף על פי שקדם ושחט את אימורי הציבור תחילה],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 \u0003ר' חייא\u0004 מהכפר \u0003אבל ערב אמר\u0004 בשם \u0003ר' מאיר: לא נחלקו ר' אליעזר ור' יהושע על\u0004 מוהל \u0003שהיו לו שני תינוקות, אחד למול ערב שבת ואחד למול בשבת, ושכח ומל את של ערב שבת בשבת — שחייב.\u0004","\u0003על מה נחלקו — על\u0004 מוהל \u0003שהיו לו שני תינוקות אחד למול אחר השבת ואחד למול בשבת, ושכח ומל את של אחר השבת בשבת,\u0004 ש\u0003ר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004","ויש לתמוה: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר לקיים ברייתא זו כלשונה, הלוא ההיפך מסתבר: \u0003מה התם\u0004 \u0005[שם]\u0006 כשמל של אחר השבת בשבת ש\u0003לא עביד\u0004 \u0005[עשה]\u0006 \u0003מצוה,\u0004 שהרי תינוק זה לא הגיע עדיין זמן מילתו לפני היום השמיני ולא עשה כלל מצוה במילתו, ובכל זאת \u0003פטר ר' יהושע\u0004 משום שטעה בתוך כדי עיסוק בדבר מצוה, \u0003היכא דקא עביד\u0004 \u0005[במקום שעושה]\u0006 \u0003מצוה\u0004 בילד שחל שמיני שלו בערב שבת, שכבר חלה עליו מצות מילה \u0003מחייב?!\u0004","\u0003אמרי דבי\u0004 \u0005[אמרו בני\u0006 בית מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 ב\u0003רישא\u0004 \u0005[תחילתה\u0006 של אותה ברייתא\u0005]\u0006 מדובר \u0003כגון שקדם ומל\u0004 את הילד הצריך להימול \u0003בשבת\u0004 עוד \u0003בערב שבת\u0004"],["\u0003שלא נתנה שבת לדחות,\u0004 ומכיון שכבר מל את הילד שהיה צריך למולו בשבת, צריך המוהל לדעת ששוב אין עליו כל חובת מילה בשבת, שהרי מילת הילד שחל שמיני שלו כבר בערב שבת אינה דוחה את השבת, שמכיון שנדחתה נדחתה, ולכן חייב. \u0003וסיפא\u0004 \u0005[וסופה\u0006 של הברייתא\u0005]\u0006 מדובר שעדיין \u0003נתנה שבת לדחות אצלו,\u0004 שהרי הילד שצריך למול בשבת עדיין לא נימול.","ועל פי הבנה זו, שהכל תלוי בשאלה אם ניתנה שבת להידחות או לא \u0003הרי הכא\u0004 \u0005[כאן]\u0006 \u0003נתנה שבת לדחות אצל קרבן ציבור,\u0004 וכיון שהוא יודע שקרבנות אלה יש צורך להקריבם בשבת — יש לו כעין צידוק לטעות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לרב כהנא: הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אפשר לומר: \u0003הרי נתנה שבת לדחות אצל תינוקות דעלמא\u0004 \u0005[סתם],\u0006 כלומר תינוקות אחרים שחובת מילתם בשבת. ואף לו יש אם כן צד היתר כלשהו וצידוק לטעות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב כהנא: \u0003לגבי דהאי גברא מיהת לא איתיהיב\u0004 \u0005[אותו אדם מכל מקום לא ניתנה]\u0006 רשות לדחות את השבת שהרי הוא עצמו אינו יודע אלא על שני תינוקות אלו בלבד.","אמרנו ש \u0003שאר כל הזבחים ששחטן לשום פסח, אם אינן ראויין לפסח — חייב, ואם ראויין, ר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004 ומעירים: \u0003מאן תנא\u0004 \u0005[מי הוא התנא]\u0006 \u0003דשני ליה\u0004 \u0005[ששונה לו,\u0006 בעיניו\u0005]\u0006 לענין הלכה \u0003בין\u0004 קרבנות \u0003ראויין לשאינן ראויין?\u0004","ומשיבים: שיטת \u0003ר' שמעון היא. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד הזבחים הראויין\u0004 לפסח \u0003ואחד זבחים שאינן ראויין, וכן השוחט לשם אימורי ציבור\u0004 בשבת — \u0003פטור\u0004 מקרבן אם שגג בכך, אלו \u0003דברי ר' מאיר. אמר ר' שמעון: לא נחלקו ר' אליעזר ור' יהושע על\u0004 המביא זבחים \u0003שאינן ראויין שחייב, על מה נחלקו\u0004 — על קרבנות \u0003הראויין, שר' אליעזר מחייב חטאת, ור' יהושע פוטר.\u0004 משמע שסתם משנתינו כשיטת ר' שמעון.","\u0003אמר רב ביבי אמר ר' אלעזר: פוטר היה ר' מאיר אפילו עגל של זבחי שלמים ששחטו לשום הפסח,\u0004 אף שכאן אין לטעות ולהחליף טלה של פסח בעגל, מכל מקום לדעתו אין מקום לחלק. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לרב ביבי: והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: מודה היה ר' מאיר בבעלי מומין\u0004 שהקריבם בשבת שחייב חטאת עליהם! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בבעלי מומין\u0004 הוא \u0003לא טריד בהו\u0004 \u0005[טרוד בהם]\u0006 שבעלי מומים יודע הוא שאינם עומדים להקרבה, \u0003והאי\u0004 \u0005[ו\u0006עגל \u0005זה]\u0006 \u0003טריד ביה\u0004 \u0005[טרוד בו]\u0006 להקריבו ויכול לטעות בו.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן:\u0004 אם שחט \u0003חולין\u0004 גמורים \u0003לשום פסח, מאי לי אמר\u0004 \u0005[מה היה אומר]\u0006 \u0003ר' מאיר\u0004 בזה? האם גם פה פוטר היה כבשאר טעויות, או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוטר היה ר' מאיר אפילו\u0004 הקריב \u0003חולין\u0004 גמורים \u0003לשום פסח.\u0004","ושאלו: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: מודה היה ר' מאיר בבעלי מומין\u0004 כיון שאינם עומדים להקרבה, ואם כן הוא הדין בחולין שאף הם אינם עומדים להקרבה! אמר לו: יש לחלק, \u0003בעלי מומין\u0004 בתמימים \u0003לא מיחלפי\u0004 \u0005[מתחלפים],\u0006 ואם בכל זאת טעה והחליף — חייב, אבל \u0003הני\u0004 \u0005[אלה]\u0006 חולין וקדשים שאין סימן הבדל חיצוני בהם \u0003מיחלפי\u0004 \u0005[מתחלפים],\u0006 ולכך אם החליפם — פטור.","ושואלים: \u0003וטעמא\u0004 \u0005[ו\u0006כי \u0005הטעם]\u0006 של \u0003ר' מאיר משום איחלופי\u0004 \u0005[מתחלף]\u0006 \u0003ולא איחלופי\u0004 \u0005[מתחלף]\u0006 הוא? והרי \u0003אמר רב ביבי אמר ר' אלעזר: פוטר היה ר' מאיר אפילו עגל של זבחי שלמים ששחטו לשום הפסח\u0004 אפילו כאשר אין שום אפשרות לטעות! \u0003אלמא, טעמא\u0004 \u0005[מכאן שטעמו]\u0006 של \u0003ר' מאיר משום דטריד\u0004 \u0005[ש\u0006הוא \u0005טרוד]\u0006 בעשיית המצוה, ולכן פטור אם שגג ועבר תוך כדי כך, אבל לא מפני שעשויים להתחלף!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 שני הטעמים תופסים לדעת ר' מאיר; אם הוא \u0003טריד\u0004 \u0005[טרוד]\u0006 הריהו פטור \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא מחלף\u0004 \u0005[מתחלף],\u0006 ופוטר גם בזמן ש\u0003מחלף\u0004 \u0005[מתחלף]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא טריד\u0004 \u0005[טרוד],\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003בעלי מומין,\u0004 ש\u0003לא איחלופי מחלף\u0004 \u0005[\u0006עשויים \u0005להתחלף]\u0006 \u0003ו\u0004הוא \u0003לא מטריד טריד\u0004 \u0005[טרוד]\u0006 בהקרבתם.","מסופר: \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' זירא ור' שמואל בר רב יצחק אקילעא\u0004 \u0005[במרפסת]\u0006 של \u0003ר' שמואל בר רב יצחק, ויתבי וקא אמרי\u0004 \u0005[וישבו ואמרו],\u0006 \u0003אמר ר' שמעון בן לקיש: נתחלף לו\u0004 בשוגג \u0003שפוד של נותר\u0004 שהיה עליו נותר מבשר הקדשים האסור באכילה, והאוכלו בזדון חייב כרת, \u0003בשפוד של צלי\u0004 של בשר קודש שמצוה לאכלו, \u0003ואכלו — חייב\u0004 חטאת. שהרי התכוון למצוה וטעה, וכיון ששגג — צריך להביא קרבן חטאת.","\u0003ור' יוחנן אמר:\u0004 אם את \u0003אשתו\u0004 בשעה שהיתה \u0003נדה בעל\u0004 בשגגה — \u0003חייב\u0004 חטאת, ששגג באיסור נדה. אם \u0003יבמתו נדה בעל\u0004 בשגגה — \u0003פטור,\u0004 שכן יש מצוה בעצם הבעילה ביבמתו, כאמור: \"יבמה יבוא עליה\" (דברים כה, ה), וגם אם טעה, ותוך כדי עשיית המצוה נכשל בעבירה — אינו חייב חטאת. ותחילה מנסים לברר האם ר' יוחנן וריש לקיש מסכימים או חלוקים זה על זה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003כל שכן בההיא\u0004 \u0005[באותו\u0006 מקרה\u0005]\u0006 של ר' שמעון בן לקיש במי שאכל בטעות שיפוד של נותר ש\u0003מחייב\u0004 ר' יוחנן, שכן במעשה אכילת הנותר \u0003לא עשה\u0004 שום \u0003מצוה\u0004 ורק התכוון למצוה, מה שאין כן במקרה שבעל אשתו נדה, שיש קצת מצוה בבעילה זו, כאשר יבואר.","\u0003אית דאמרי\u0004 \u0005[יש שאומרים]\u0006 שלדעת ר' יוחנן \u0003בההוא,\u0004 כשנתחלף לו שיפוד של נותר בשל קודש — \u0003פטור. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 כאשר בעל אשתו נדה חייב, \u0003דהוה ליה לשיולי\u0004 \u0005[שהיה לו לשאול]\u0006 אותה אם נדה היא, ומשום שלא שאל — חייב חטאת. \u0003אבל הכא\u0004 \u0005[כאן\u0006 בשיפוד\u0005]\u0006 ש\u0003לא הוה ליה לשיולי\u0004 \u0005[היה לו\u0006 את מי \u0005לשאול]\u0006 — \u0003לא.\u0004","ושואלים: \u0003ור' יוחנן, מאי שנא\u0004 \u0005[במה שונה]\u0006 שפוטר הבא על \u0003יבמתו\u0004 הנדה? משום \u0003דקא עביד\u0004 \u0005[שהוא עושה]\u0006 \u0003מצוה, אשתו נמי\u0004 \u0005[גם כן]\u0006 הרי \u0003קא עביד\u0004 \u0005[עושה]\u0006 \u0003מצוה\u0004 בביאתה, שהרי מקיים מצות פריה ורביה! ומשיבים: מדובר כאן \u0003באשתו מעוברת\u0004 שאין כאן עוד צד פריה ורביה.","ומקשים: והלוא בכל זאת \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מצות \u0003שמחת עונה,\u0004 שחייב אדם בתוך שאר חובות הנישואין להיזקק לאשתו בכל זמן קבוע (עונה) (ראה שמות כא, י), ומצוה היא! ועונים שכאן מדובר \u0003שלא בשעת עונתה.\u0004","ועדיין מקשים: אפילו כך, \u0003והאמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבא: חייב אדם לשמח\u0004 את \u0003אשתו בדבר מצוה\u0004 (בתשמיש) אף שלא בזמן עונתה, אם רצונה בכך! ומתרצים: שמדובר כאן \u0003סמוך לווסתה,\u0004 שאז אסור לו לבוא עליה מפני החשש שמא תמצא נדה בשעת תשמיש.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בקרוב לווסתה, שהיה עליו להיזהר ולא לבוא עליה, \u0003אפילו יבמתו נמי\u0004 \u0005[גם כן]\u0006 יהא חייב אם בא עליה בזמן הסמוך לווסתה! ומסבירים: \u0003יבמתו בזיז מינה\u0004 \u0005[מתבייש ממנה]\u0006 עדיין, ולא נוח לו לשאול אם קרוב לווסתה הוא, \u0003אשתו לא בזיז מינה\u0004 \u0005[מתבייש ממנה]\u0006 והיה עליו לשאול אותה.","ושואלים: \u0003ור' יוחנן כמאן\u0004 \u0005[כשיטת מי]\u0006 אמר דברים אלה לענין טועה בדבר מצוה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כשיטת \u0003ר' יוסי דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' יוסי אומר: יום טוב הראשון של חג\u0004 הסוכות \u0003שחל להיות בשבת, ושכח והוציא את הלולב לרשות הרבים\u0004 וטלטלו בה, ועבר בשגגה על מלאכה האסורה מן התורה — \u0003פטור\u0004 מקרבן חטאת, \u0003מפני שהוציא ברשות\u0004 כלומר, לשם מצוה.","אולם יש מקום לחלק בין דברים אלה לדברי ר' יוחנן: \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003זמנו בהול,\u0004 כיון שנטילת לולב מן התורה מצוותה רק יום אחד, מפני הבהילות לקיים את המצוה לא שם לב שעובר עבירה תוך כדי כך, מה שאין כן במצות ביאה ביבמתו, שאין לה זמן מסויים.","\u0003ואלא\u0004 תאמר שסבור כשיטת \u0003ר' יהושע דזבחים,\u0004 במשנתנו, הפוטר אם שחטם לשם הפסח, הרי יש מקום לדחות: \u0003דילמא התם נמי\u0004 \u0005[שמא שם גם כן]\u0006 יש לומר שפוטר מפני ש\u0003זמנו בהול.\u0004","\u0003ואלא\u0004 תאמר ששיטתו כשיטת \u0003ר' יהושע\u0004 של \u0003תינוקות\u0004 שצריכים למול בשבת. אפשר לדחות: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003זמנו בהול,\u0004 ושמא רק משום כך פוטרו ר' יהושע.","\u0003ואלא\u0004 נאמר כי שיטתו \u0003כר' יהושע\u0004 בענין \u0003תרומה, דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 כהן ש\u0003היה אוכל בתרומה ונודע\u0004 לו \u0003שהוא בן גרושה או בן חלוצה\u0004 והריהו לכן חלל, שאין קדושת כהונה עליו ואסור בתרומה. \u0003ר' אליעזר מחייב\u0004 אותו כמו כל זר שאכל תרומה בשוגג \u0003בקרן\u0004 התרומה \u0003וחומש\u0004 תוספת, ו\u0003ר' יהושע פוטר.\u0004 ונאמר שכיון שחשב שעשה מצוה בשעת אכילת התרומה (שהרי סבר שהוא כהן) אף שנעשתה בכך באמת עבירה — פטור, והרי זה דומה לדברי ר' יוחנן.","אולם עדיין אפשר לדחות את ההשוואה, ולומר: \u0003דילמא\u0004 \u0005[שמא]\u0006 יש לפרש אותו ענין כשיטת \u0003רב ביבי בר אביי,\u0004 ש\u0003אמר רב ביבי בר אביי:\u0004 שם מדובר \u0003בתרומה\u0004 של חמץ \u0003בערב הפסח,\u0004 ש\u0003זמנה בהול\u0004 שצריך להזדרז ולאוכלה, שאם לא יעשה כן יצטרכו לשורפה.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש טעם אחר לחלק: \u0003שאני\u0004 \u0005[שונה]\u0006 אכילת \u0003תרומה דאיקרי\u0004 \u0005[שנקראת]\u0006 גם היא \u0003עבודה\u0004 של קודש, \u0003ועבודה רחמנא אכשר\u0004 \u0005[הכתוב הכשיר]\u0006 אם עשאה אדם מזרע הכהונה אף שאינו ראוי לה.","\u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כהן\u0004 ש\u0003היה עומד ומקריב\u0004 על גבי המזבח \u0003ונודע שהוא בן גרושה או בן חלוצה — כל הקרבנות כולן שהקריב על גבי המזבח\u0004 עד לאותה שעה — \u0003פסולין,\u0004 שהרי רק כהן רשאי להקריב וקרבנו נרצה, \u0003ור' יהושע מכשיר. ואמרינן\u0004 \u0005[ואמרנו]\u0006 \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יהושע — דכתיב\u0004 \u0005[שנאמר]\u0006 בבני לוי: \u0003\"ברך ה' חילו ופעל ידיו תרצה\"\u0004 (דברים לג, יא), ללמד שבדיעבד רוצה ה' את פועל ידי הכהנים, אפילו התברר שהיו כבר פסולים בשעת עבודה.","ושואלים על מה שהזכרנו קודם: \u0003ותרומה היכא איקרי\u0004 \u0005[היכן קרויה בכתוב]\u0006 \u0003עבודה?\u0004 ומסבירים: \u0003תניא\u0004 \u0005[שנויה ברייתא]\u0006 בענין זה, \u0003מעשה בר' טרפון שלא בא אמש\u0004 (בערב) \u0003לבית המדרש, לשחרית מצאו רבן גמליאל, אמר לו: מפני מה לא באת אמש לבית המדרש? אמר לו: עבודה\u0004 של קודש \u0003עבדתי. אמר לו: כל דבריך\u0004 שאתה אומר \u0003אינן אלא דברי תימה, וכי עבודה בזמן הזה\u0004 שחרב בית המקדש \u0003מנין? אמר לו: הרי הוא אומר\u0004 בכתוב:"],["\u0003\"עבדת מתנה אתן את כהנתכם והזר הקרב יומת\"\u0004 (במדבר יח, ז), ובאותם כתובים מדובר במתנות הניתנות לכהנים ותרומה ביניהן, ללמדנו כי \u0003עשו אכילת תרומה בגבולין\u0004 (מחוץ למקדש) \u0003כעבודת בית המקדש.\u0004","במשנתנו למדנו שאם \u0003שחטו\u0004 בשבת \u0003שלא לאוכליו\u0004 או שלא למנוייו וכיוצא בזה בשוגג — חייב להביא קרבן חטאת. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 \u0003כיון דהתם\u0004 \u0005[ששם]\u0006 לענין שחיטתו — \u0003פסול, הכא\u0004 \u0005[כאן]\u0006 לענין שבת — \u0003חייב,\u0004 שהרי נתברר שעשה מלאכה שלא לצורך קרבן! ומשיבים: \u0003משום דתנא סיפא\u0004 \u0005[ששנה בסוף\u0006 המשנה\u0005]\u0006 מקרה בו הוא \u0003פטור, תנא רישא\u0004 \u0005[שנה בראשה]\u0006 מקרה בו הוא \u0003חייב,\u0004 אף שאין בכך חידוש כל כך.","ומקשים: \u0003והא נמי פשיטא\u0004 \u0005[והרי זה גם כן פשוט]\u0006 \u0003משום דהתם\u0004 \u0005[ששם]\u0006 לענין קרבן \u0003כשר, הכא\u0004 \u0005[כאן]\u0006 לענין שבת \u0003פטור\u0004 שהרי עלה קרבנו לרצון, וכדין שחטו. \u0003אלא איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003שחטו שלא לשמו בשבת, תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003שלא לאוכליו.\u0004 ושואלים עוד: \u0003והיא גופא\u0004 \u0005[עצמה],\u0006 הלכה זו בשחטו שלא לשמו, \u0003למה לי?\u0004 הלוא גם היא פשוטה! ומשיבים: \u0003משום דקבעי לאיפלוגי\u0004 \u0005[שרצה\u0006 להביא \u0005מחלוקת]\u0006 \u0003ר' אליעזר ור' יהושע\u0004 שנה הלכות אלה.","מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בר חיננא לבריה\u0004 \u0005[לבנו]\u0006 \u0003כי אזלת לקמיה\u0004 \u0005[כאשר תבוא לפני]\u0006 \u0003ר' זריקא, בעי מיניה\u0004 \u0005[שאל ממנו]:\u0006 \u0003לדברי האומר \"מקלקל בחבורה — פטור\",\u0004 שהעושה חבורה בשבת ואינו עושה על ידה כל מלאכת תיקון אלא קלקול בלבד — אינו נחשב כעושה מלאכה בשבת. ולפי הכלל שאין המקלקלים חייבים על מה שעשו בשבת, לשיטה זו כיצד נסביר \u0003\"שחטו שלא לאוכליו — חייב\"?\u0004 הלוא בשחיטה פסולה זו הריהו כאילו פצע בבהמה שלא לשום תועלת ורק קלקל בה את הקרבן, \u0003מה תיקן\u0004 בשחיטה זו שיתחייב משום מלאכה?","ומשיבים: \u0003תיקן\u0004 לענין של \u0003אם עלו לא ירדו,\u0004 כפי ההלכה שקרבן פסול כגון זה, אם העלהו בשגגה על גבי המזבח — אין צריך להורידו, ואפשר להקריב את אימוריו, ונמצא שיש מקצת תיקון בשחיטתו.","ושואלים עוד: שנינו במשנה \u0003שחטו ונמצא בעל מום — חייב, ומה תיקן\u0004 בכך? ומשיבים: \u0003תיקן\u0004 אם היה המום קטן, כגון \u0003בדוקין\u0004 (בעפעף) \u0003שבעין ואליבא\u0004 \u0005[ועל פי]\u0006 שיטת \u0003ר' עקיבא\u0004 ש\u0003אמר:\u0004 שקרבן שהיה בו מום קטן כגון זה, \u0003אם עלו\u0004 אימוריו למזבח \u0003לא ירדו\u0004 ממנו, שאין גנאי כל כך בזבח זה.","ועוד שואלים: שנינו במשנה \u0003שחטו ונמצא טריפה בסתר — פטור.\u0004 ונלמד מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם היה \u0003בגלוי — חייב.\u0004 ויש לשאול \u0003מה תיקן\u0004 בשחיטת טריפה שבגלוי? ומשיבים: \u0003תיקן להוציא מידי נבילה,\u0004 שכן אם תמות הטריפה מעצמה תהא נבילה ותיטמא, ועל ידי שחיטה שוב אינה מטמאה כנבילה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: הא דתניא\u0004 \u0005[זו\u0006 הברייתא, \u0005ששנויה]\u0006 במקום אחר: \u0003השוחט\u0004 בשגגה \u0003חטאת בשבת בחוץ\u0004 (שלא במקדש) לשם \u0003עבודה זרה — חייב עליה שלש חטאות:\u0004 משום חילול שבת, משום קדשים ששחטן בחוץ, ומשום עבודה זרה, ואף שם אפשר לשאול: \u0003מה תיקן?\u0004 ושם אין לומר שהוציאה מידי טומאת נבילה, כי כל קרבן המובא לעבודה זרה הוא עצמו מטמא, ונמצא שלא עשה בקרבן שום תיקון!","\u0003אמר רב עוירא:\u0004 אף בשחיטה זו יש תיקון מה, \u0003שמוציאו\u0004 את הקרבן \u0003מידי אבר מן החי.\u0004 שאפילו גוי שאוכל אבר מבהמה בלתי שחוטה חייב משום אבר מן החי, וכיון ששוחטה — אינו חייב על כך, נמצא שיש תיקון גם בשחיטה זו.","במשנה שנינו שאם \u0003שחטו ונודע\u0004 אחר כך שמתו בעליו — הרי זה פטור. \u0003אמר רב הונא אמר רב: אשם שניתק לרעיה\u0004 שמתו בעליו או נתכפרו באשם אחר, מוציאים אותו שירעה בשדה עד שיפול בו מום ואז יוכלו למכרו, ובדמיו יקנו אחר כך קרבן עולה (קיץ המזבח). ואם בינתיים, לפני שנפל בו מום \u0003שחטו סתם\u0004 בלא לפרש לשם מה שוחטו — \u0003כשר לעולה.\u0004 ומסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן שסבר]\u0006 אותו חכם: \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה,\u0004 שאין צורך באמירה מפורשת לעקור את הקרבן משמו הקודם, ואף אם שוחטו סתם הוכשר.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא ניתק\u0004 לרעיה והיה קרבן אשם שנתכפרו בעליו באחר \u0003נמי\u0004 \u0005[גם כן\u0006 יהא כשר\u0005],\u0006 שאף בלא מום הריהו מן הסתם מיועד לקיץ המזבח, כיון שלאחר שכבר נתכפרו בעליו שוב אין צריך לו! ומשיבים: \u0003גזירה\u0004 גזרו חכמים שלא לעשות זאת באשם \u0003לאחר כפרה\u0004 (שנתכפרו כבר בעליו באחר) \u0003אטו\u0004 \u0005[משום]\u0006 אשם \u0003לפני כפרה,\u0004 שהרי לפני כפרה ודאי אשם הוא ולא עולה, ורק לאחר כפרת בעלים בלית ברירה הריהו מוכשר לצורך עולה, ואז מעיקר הדין גם אם מקריבים אותו מיד כעולה — היה כשר.","\u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 שכן הוא \u0003דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אשם שמתו בעליו או שנתכפרו בעליו\u0004 באחר — \u0003ירעה עד שיסתאב, וימכר, ויפלו דמיו\u0004 לקרבן \u0003נדבה\u0004 וציבור. \u0003ר' אליעזר אומר:\u0004 אשם זה \u0003ימות\u0004 שגורמים לו למות מעצמו. \u0003ר' יהושע אומר: ימכר\u0004 כשיפול בו מום \u0003ויביא בדמיו עולה\u0004 לעצמו. משמע שלדעת ר' יהושע מיד לאחר כפרה נסתלקה ממנו קדושת אשם, ונעשה כעולה.","ובכל זאת גם הוא אומר \u0003בדמיו — אין\u0004 \u0005[כן],\u0006 \u0003אבל גופו\u0004 עצמו \u0003לא\u0004 יקריב לעולה. ובלי ספק טעמו ש\u0003גזר לאחר כפרה אטו\u0004 \u0005[משום]\u0006 \u0003לפני כפרה.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא הדבר.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב חסדא לרב הונא\u0004 על שיטתו בענין עקירת קרבן משמו, מענין הפסח ש\u0003שחטו ונודע שמשכו בעלים את ידם\u0004 ונמנו על קרבן אחר או שמתו או שנטמאו,"],["\u0003ותני עלה\u0004 \u0005[ו\u0006ברייתא \u0005שנויה על\u0006 משנתינו זו\u0005]\u0006 \u0003בחול כי האי גונא\u0004 \u0005[כעין זה]\u0006 שנתברר שאין עוד אוכלים לפסח \u0003ישרף מיד. אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 שקרבן ללא בעלים \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 משמו כדי שיהיה שלמים, ואם לא נעקר שמו במפורש נשאר הוא בקדושתו הראשונה, אפשר לומר גם כאן כי \u0003האי\u0004 \u0005[\u0006קרבן \u0005זה]\u0006 \u0003פסח הוא\u0004 עדיין, \u0003וכיון דלית ליה\u0004 \u0005[שאין לו]\u0006 \u0003בעלים הוה ליה\u0004 \u0005[הרי זה]\u0006 \u0003פסולו בגופו\u0004 שהרי הוקרב שלא לצורך, \u0003אמטו להכי\u0004 \u0005[משום כך]\u0006 \u0003ישרף מיד.\u0004","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שקרבן כגון זה \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה,\u0004 אלא ממילא קדושתו הראשונה בטלה עם הסתלקות בעליו — \u0003מרישא הוה ליה\u0004 \u0005[מתחילתו\u0006 עם הקרבתו \u0005הריהו]\u0006 \u0003שלמים\u0004 שהרי פסח שנעקר משמו דינו כשלמים, \u0003פסולו משום מאי\u0004 \u0005[מה] —\u0006 \u0003משום דבר אחר הוא דקא שחיט ליה\u0004 \u0005[ששוחט אותו]\u0006 \u0003אחר תמיד של בין הערבים,\u0004 שקרבן פסח זמנו אחר התמיד, ואילו קרבן השלמים שנשחט אז — נפסל. אולם במקרה כזה \u0003עיבור צורה בעי\u0004 \u0005[צריך],\u0006 שיש להשהותו עד שתתקלקל צורתו (שילין בלילה ויהא דינו כנותר) ורק אז אפשר לשורפו.","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זה הכלל: כל קרבן שפסולו\u0004 היה \u0003בגופו — ישרף מיד\u0004 ואין צורך להשהותו. ואם היה הפסול \u0003בדם\u0004 הקרבן או \u0003בבעלים — ילינו את הבשר עד למחר ובתוך כך תעובר צורתו\u0004 ורק אחר כך \u0003יצא לבית השריפה,\u0004 ואם כן הרי זו הוכחה שקרבן שאין לו בעלים אינו נשרף מיד אלא צריך עדיין עיבור צורה קודם לכן, ומתוך שנאמר בברייתא כי בחול ישרף מיד, אין זה אלא מתוך שצריך עדיין עקירה במפורש, וקשה לרב הונא!","\u0003אלא לא תימא\u0004 \u0005[תאמר]\u0006 בענין אשם ש\u0003שחטו סתם כשר לשום עולה, אלא אימא\u0004 \u0005[אמור]\u0006 אם לקח קרבן אשם זה שנתכפרו בעליו באחר ו\u0003שחטו\u0004 במפורש \u0003לשום עולה — כשר. אלמא\u0004 \u0005[מכאן]\u0006 \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 מפורשת של הקרבן משמו הקודם. ושואלים: ולשיטת \u0003ר' חייא בר גמדא\u0004 שדן בשאלה אם פסח טעון עקירה ש\u0003אמר נזרקה מפי חבורה\u0004 בתוך הדיון ההלכתי \u0003ואמרי\u0004 \u0005[ואמרו]\u0006 כולם והסכימו שצריך עקירה, \u0003כגון שהיו בעלים טמאי מתים ונדחין לפסח שני,\u0004 שאז מן הסתם קרבן זה רוצים להניחו לצורך פסח שני ואין בדעתם לשנותו כלל לקרבן אחר, ולכך בלא עקירה מפורשת אינו נעקר.","","ונדייק מדברים אלה: \u0003האי\u0004 \u0005[זה]\u0006 \u0003הוא\u0004 הקרבן הצריך \u0003עקירה\u0004 במפורש, משום שיש מקום לשער שעדיין כוונת הבעלים לשמו, \u0003הא בעלמא\u0004 \u0005[הרי בכלל]\u0006 \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה.\u0004 לשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שלכאורה ממשנתנו מתברר שצריך עקירה במפורש ושלא כשיטת רב הונא!","\u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שהפרישו\u0004 את הפסח \u0003קודם חצות\u0004 היום, והגיע זמן חצות היום ונקבע לשם פסח \u0003ומתו בעלים אחר חצות\u0004 היום, \u0003דהוה ליה\u0004 \u0005[שנהיה]\u0006 הקרבן בגדר של \u0003נראה ונדחה,\u0004 שקודם היה נראה (ראוי) להקריבו או לפסח או לשלמים. ולאחר מכן נדחה, שלאחר חצות היום נדחה משלמים ונקבע בקדושת פסח, ולאחר מיתת הבעלים נדחה שוב אף מפסח. וכלל בידינו ש\u0003כל הנראה ונדחה — שוב אינו חוזר ונראה,\u0004 ולכך נפסל הקרבן וישרף מיד, שאין לו תקנה לא כפסח ולא כשלמים.","את התירוץ הזה דוחים: \u0003מידי הוא טעמא\u0004 \u0005[וכי למי הטעם הזה]\u0006 \u0003אלא\u0004 לשיטת \u0003רב\u0004 שלדעתו אין צריך עקירה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר רב\u0004 עצמו: \u0003בעלי חיים אינם נדחים\u0004 שכל דין דיחוי הוא רק בקרבן שכבר נשחט, אבל לגבי בעלי חיים אין אומרים שנדחו מקדושתם או ממצותם.","\u0003אלא אמר רב פפא: הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המוסיפה על המשנה כי בחול ישרף מיד, \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: וכן השוחט\u0004 קרבנות \u0003אחרים\u0004 כגון שלמים \u0003לשם פסח — פסול,\u0004 ואם כן \u0003הוה ליה\u0004 \u0005[נעשה]\u0006 \u0003פסולו בגופו\u0004 וטעון שריפה מיד.","ומקשים: \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003ר' אליעזר היא,\u0004 הלוא \u0003חטאת נמי\u0004 \u0005[גם כן]\u0006 \u0003מחייב,\u0004 ששחט קרבן פסול בשבת, \u0003דהא לית ליה\u0004 \u0005[שהרי אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003ר' אליעזר\u0004 את ההנחה כי \u0003טועה בדבר מצוה פטור.\u0004","\u0003אלא\u0004 יש לדחות מה שאמרנו, \u0003תרגמא\u0004 \u0005[הסבירה]\u0006 \u0003רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רב סלא חסידא\u0004 \u0005[החסיד]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 כשיטת \u0003יוסף בן חונאי היא. דתנן\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 במשנה\u0005]\u0006 \u0003יוסף בן חונאי אומר:\u0004 קרבנות אחרים \u0003הנשחטים לשם פסח\u0004 או \u0003לשם חטאת\u0004 — \u0003פסולים,\u0004 שלענין זה דעתו כר' אליעזר, \u0003אלמא\u0004 \u0005[מכאן]:\u0006 \u0003פסולו בגופו היא, ומשום הכי\u0004 \u0005[כך]\u0006 \u0003ישרף מיד, ובפטורי\u0004 \u0005[ו\u0006לענין \u0005פטורים]\u0006 מחטאת בענין שגגה בשבת — \u0003סבר לה\u0004 כשיטת \u0003ר' יהושע,\u0004 שהטועה בדבר מצוה פטור.","\u0003רב אשי אמר\u0004 תירוץ אחר לשאלה: \u0003רב\u0004 ש\u0003אמר\u0004 את הלכתו לענין אשם סבור כשיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה. דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר: אם יש\u0004 לשוחט הפסח בשבת \u0003שהות ביום לידע אם משכו בעלים את ידיהם או שמתו או שנטמאו\u0004 — חייב חטאת על מה שהקריב בשבת, ואז \u0003תעובר צורתו ויוצא לבית השריפה. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שהצריכוהו עיבור צורה? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שלדעתו \u0003לא בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה\u0004 ולכן אין זה פסול בגופו של הקרבן, ולכן טעון עיבור צורה ולא ישרף מיד!","ודוחים: \u0003ממאי\u0004 \u0005[ממה],\u0006 מנין מסיק אתה מסקנה זו? \u0003דילמא\u0004 \u0005[שמא]\u0006 צריך עקירה ופסולו בגופו ומה שהוצרך לעיבור צורה הוא \u0003משום שסבר\u0004 בענין זה כשיטת \u0003תנא דבי\u0004 \u0005[התנא מבית\u0006 מדרשו של\u0005]\u0006 \u0003רבה בר אבוה\u0004 ש\u0003אמר: אפילו פגול\u0004 שהוא פסול שבגופו \u0003נמי בעי\u0004 \u0005[גם כן צריך]\u0006 \u0003עיבור צורה. דיליף\u0004 \u0005[שלומד]\u0006 גזירה שווה \u0003\"עו‍ן\" \"עו‍ן\" מנותר,\u0004 שנאמר בפיגול \"עון\" ונאמר בנותר \"עון\".","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כן]\u0006 שלפי שיטה זו נאמרה ההלכה, במקרה של \u0003נטמאו בעלים מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 במקרה זה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי בעי\u0004 \u0005[צריך]\u0006 \u0003עקירה,\u0004 שהרי \u0003אמר ר' חייא בר גמדא: נזרקה מפי חבורה\u0004 תוך כדי הדיון ההלכתי שהצורך בעקירה הוא דווקא במקרה \u0003כגון שהיו בעלים טמאי מת ונדחו\u0004 כולם \u0003לפסח שני,\u0004 וכיון שקרבנם מיועד לפסח שני, לכך צריכים עקירה.","\u0003אלא מחוורתא כדשני מעיקרא\u0004 \u0005[מחוור,\u0006 ברור \u0005כפי שתירץ מתחילה]\u0006 שמשנתנו זו כשיטת \u0003יוסף בן חונאי היא,\u0004 ולכן בחול ישרף מיד, ובשבת אינו צריך להביא קרבן חטאת כשיטת ר' יהושע.",""]]};
